/* =========================================================
   SERVICES HERO
========================================================= */

.services-hero {
    position: relative;
    isolation: isolate;

    width: 100%;

    display: flex;
    align-items: center;

    overflow: hidden;

    background: #061525;
    color: #ffffff;
}


/* =========================================================
   BACKGROUND VIDEO
========================================================= */

.services-hero-video {
    position: absolute;
    inset: 0;

    width: 100%;
    height: 100%;

    object-fit: cover;
    object-position: center center;

    z-index: -3;

    pointer-events: none;
}


/* =========================================================
   DARK VIDEO OVERLAY
========================================================= */

.services-hero-overlay {
    position: absolute;
    inset: 0;

    z-index: -2;

    background:
        linear-gradient(90deg,
            rgba(3, 13, 27, 0.93) 0%,
            rgba(4, 17, 33, 0.82) 40%,
            rgba(4, 17, 33, 0.65) 70%,
            rgba(3, 12, 25, 0.78) 100%);
}


/* =========================================================
   BLUE ATMOSPHERIC GLOW
========================================================= */

.services-hero::after {
    content: "";

    position: absolute;
    inset: 0;

    z-index: -1;

    pointer-events: none;

    background:
        radial-gradient(circle at 18% 50%,
            rgba(56, 189, 248, 0.15),
            transparent 35%),
        radial-gradient(circle at 85% 40%,
            rgba(14, 165, 233, 0.09),
            transparent 32%);
}


/* =========================================================
   CONTAINER
========================================================= */

.services-hero-container {
    width: min(100% - 40px, 1180px);

    margin-inline: auto;
}


/* =========================================================
   HERO CONTENT
========================================================= */

.services-hero-content {
    display: flex;

    align-items: center;

    gap: 30px;

    max-width: 920px;

    margin-inline: auto;

    padding: 65px 0;

    opacity: 0;

    /*
       Main entrance animation
    */
    animation:
        servicesHeroReveal 1.2s cubic-bezier(0.22, 1, 0.36, 1) 0.1s forwards;
}


/* =========================================================
   ENGLISH / LTR
   Line on the LEFT
   Content enters from LEFT
========================================================= */

html[dir="ltr"] .services-hero-content {
    direction: ltr;

    flex-direction: row;

    transform: translateX(-70px);
}

html[dir="ltr"] .services-hero-text {
    text-align: left;
}


/* =========================================================
   ARABIC / RTL
   Line on the RIGHT
   Content enters from RIGHT
========================================================= */

html[dir="rtl"] .services-hero-content {
    direction: rtl;

    flex-direction: row;

    transform: translateX(70px);
}

html[dir="rtl"] .services-hero-text {
    text-align: right;
}


/* =========================================================
   HERO MAIN REVEAL
========================================================= */

@keyframes servicesHeroReveal {

    0% {
        opacity: 0;
    }

    100% {
        opacity: 1;
        transform: translateX(0);
    }

}


/* =========================================================
   VERTICAL LINE
========================================================= */

.services-hero-line {
    position: relative;

    flex: 0 0 5px;

    width: 5px;

    height: 150px;

    overflow: hidden;

    border-radius: 999px;

    background:
        linear-gradient(to bottom,
            rgba(56, 189, 248, 0.18),
            rgba(56, 189, 248, 0.30),
            rgba(56, 189, 248, 0.18));

    box-shadow:
        0 0 12px rgba(56, 189, 248, 0.15),
        inset 0 0 5px rgba(56, 189, 248, 0.18);
}


/* =========================================================
   MOVING LIGHT INSIDE LINE
========================================================= */

.services-hero-line span {
    position: absolute;

    top: -40%;
    left: 0;

    width: 100%;
    height: 40%;

    border-radius: inherit;

    background:
        linear-gradient(to bottom,
            transparent 0%,
            rgba(125, 211, 252, 0.40) 25%,
            #38bdf8 50%,
            rgba(125, 211, 252, 0.40) 75%,
            transparent 100%);

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.85),
        0 0 24px rgba(56, 189, 248, 0.45);

    animation:
        servicesLineLight 4s ease-in-out infinite;
}


/* =========================================================
   LINE LIGHT ANIMATION
========================================================= */

@keyframes servicesLineLight {

    0% {
        top: -40%;
        opacity: 0;
    }

    12% {
        opacity: 1;
    }

    50% {
        opacity: 1;
    }

    88% {
        opacity: 1;
    }

    100% {
        top: 100%;
        opacity: 0;
    }

}


/* =========================================================
   TEXT AREA
========================================================= */

.services-hero-text {
    flex: 1;

    min-width: 0;
}


/* =========================================================
   TITLE
========================================================= */

.services-hero-title {
    position: relative;

    margin: 0 0 18px;

    font-size: clamp(3rem, 6vw, 5.5rem);

    font-weight: 800;

    line-height: 1;

    letter-spacing: -0.045em;

    color: #ffffff;

    /*
       White text + blue light sweep
    */
    background:
        linear-gradient(110deg,
            #ffffff 0%,
            #ffffff 32%,
            #ffffff 42%,
            #7dd3fc 48%,
            #38bdf8 51%,
            #7dd3fc 54%,
            #ffffff 62%,
            #ffffff 100%);

    background-size: 260% 100%;

    background-position: 120% 0;

    -webkit-background-clip: text;

    background-clip: text;

    -webkit-text-fill-color: transparent;

    /*
       Title appears first,
       then the blue light starts later
    */
    animation:
        servicesTitleReveal 1.1s cubic-bezier(0.22, 1, 0.36, 1) 0.65s both,

        servicesTitleLight 8s linear 1.8s infinite;

    filter:
        drop-shadow(0 0 0 rgba(56, 189, 248, 0));
}


/* =========================================================
   TITLE REVEAL
========================================================= */

@keyframes servicesTitleReveal {

    0% {
        opacity: 0;

        transform:
            translateY(25px);

        filter:
            blur(6px);
    }

    55% {
        opacity: 0.75;
    }

    75% {
        opacity: 0.92;
    }

    100% {
        opacity: 1;

        transform:
            translateY(0);

        filter:
            blur(0);
    }

}


/* =========================================================
   SLOW BLUE LIGHT SWEEP
========================================================= */

@keyframes servicesTitleLight {

    0% {

        background-position: 120% 0;

        filter:
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }


    30% {

        background-position: 75% 0;

        filter:
            drop-shadow(0 0 1px rgba(56, 189, 248, 0.05));
    }


    42% {

        background-position: 55% 0;

        filter:
            drop-shadow(0 0 4px rgba(56, 189, 248, 0.12));
    }


    48% {

        background-position: 40% 0;

        filter:
            drop-shadow(0 0 8px rgba(56, 189, 248, 0.25));
    }


    52% {

        background-position: 30% 0;

        filter:
            drop-shadow(0 0 16px rgba(56, 189, 248, 0.42));
    }


    58% {

        background-position: 15% 0;

        filter:
            drop-shadow(0 0 7px rgba(56, 189, 248, 0.18));
    }


    70% {

        background-position: -10% 0;

        filter:
            drop-shadow(0 0 2px rgba(56, 189, 248, 0.06));
    }


    82% {

        background-position: -45% 0;

        filter:
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }


    100% {

        background-position: -120% 0;

        filter:
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }

}


/* =========================================================
   DESCRIPTION
========================================================= */

.services-hero-description {
    max-width: 760px;

    margin: 0;

    color: rgba(255, 255, 255, 0.88);

    font-size: clamp(1rem, 1.6vw, 1.2rem);

    font-weight: 400;

    line-height: 1.8;

    letter-spacing: 0.01em;

    text-shadow:
        0 2px 12px rgba(0, 0, 0, 0.45);

    /*
       Description starts hidden
       and appears after the title
    */
    opacity: 0;

    transform:
        translateY(22px);

    filter:
        blur(5px);

    animation:
        servicesDescriptionReveal 1.1s cubic-bezier(0.22, 1, 0.36, 1) 1.35s forwards;
}


/* =========================================================
   DESCRIPTION REVEAL
========================================================= */

@keyframes servicesDescriptionReveal {

    0% {

        opacity: 0;

        transform:
            translateY(22px);

        filter:
            blur(5px);
    }


    45% {

        opacity: 0.55;
    }


    70% {

        opacity: 0.85;

        filter:
            blur(1.5px);
    }


    100% {

        opacity: 1;

        transform:
            translateY(0);

        filter:
            blur(0);
    }

}


/* =========================================================
   ARABIC
========================================================= */

html[dir="rtl"] .services-hero-title {
    letter-spacing: 0;
}


html[dir="rtl"] .services-hero-description {
    line-height: 2;
}


/* =========================================================
   TECHNOLOGY SOLUTIONS SECTION
========================================================= */

.technology-section {

    position: relative;

    width: 100%;

    background: #ffffff;

    color: #10243b;

    overflow: hidden;

    padding: 85px 0 65px;
}


/* =========================================================
   CONTAINER
========================================================= */

.technology-container {

    position: relative;

    width: min(100% - 40px, 1280px);

    margin-inline: auto;
}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.technology-layout {

    display: grid;

    grid-template-columns:
        minmax(0, 1.05fr) minmax(500px, 0.95fr);

    gap: 65px;

    align-items: center;
}


/* =========================================================
   =========================================================
   SECTION REVEAL SYSTEM
   العناصر تبدأ من تحت وتظهر بالتتابع
   =========================================================
========================================================= */

.technology-section .technology-content>*,
.technology-section .technology-visual {

    opacity: 0;

    transform:
        translateY(55px);

    filter:
        blur(5px);

    transition:
        opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1),
        transform 0.75s cubic-bezier(0.22, 1, 0.36, 1),
        filter 0.75s ease;
}


/* =========================================================
   WHEN SECTION BECOMES VISIBLE
========================================================= */

.technology-section.is-visible .technology-content>*,
.technology-section.is-visible .technology-visual {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);
}


/* =========================================================
   STAGGER ANIMATION
========================================================= */

.technology-section.is-visible .technology-eyebrow {

    transition-delay: 0.05s;
}


.technology-section.is-visible .technology-title {

    transition-delay: 0.16s;
}


.technology-section.is-visible .technology-title-accent {

    transition-delay: 0.27s;
}


.technology-section.is-visible .technology-description {

    transition-delay: 0.38s;
}


.technology-section.is-visible .technology-description-secondary {

    transition-delay: 0.47s;
}


.technology-section.is-visible .technology-cards {

    transition-delay: 0.58s;
}


.technology-section.is-visible .technology-cta {

    transition-delay: 0.82s;
}


.technology-section.is-visible .technology-visual {

    transition-delay: 0.18s;
}


/* =========================================================
   CONTAINER
========================================================= */

.technology-content {

    position: relative;

    z-index: 3;
}


/* =========================================================
   EYEBROW
========================================================= */

.technology-eyebrow {

    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 17px;

    color: #087ec5;

    font-size: 14px;

    font-weight: 700;

    letter-spacing: 0.045em;

    text-transform: uppercase;
}


.technology-eyebrow-line {

    width: 30px;

    height: 2px;

    flex: 0 0 30px;

    border-radius: 999px;

    background: #159ee5;

    box-shadow:
        0 0 9px rgba(21, 158, 229, 0.35);
}


/* =========================================================
   TITLE
========================================================= */

.technology-title {

    margin: 0;

    color: #10243b;

    font-size: 46px;

    font-weight: 800;

    line-height: 1.08;

    letter-spacing: -0.035em;
}


/* =========================================================
   TITLE ACCENT
========================================================= */

.technology-title-accent {

    width: 70px;

    height: 3px;

    margin-top: 19px;

    margin-bottom: 24px;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            #159ee5,
            rgba(21, 158, 229, 0.12));

    box-shadow:
        0 0 9px rgba(21, 158, 229, 0.25);
}


/* =========================================================
   DESCRIPTION
========================================================= */

.technology-description {

    max-width: 700px;

    margin: 0 0 16px;

    color: #64748b;

    font-size: 16px;

    font-weight: 400;

    line-height: 1.82;

    letter-spacing: 0.004em;
}


.technology-description-secondary {

    margin-bottom: 25px;

    color: #718096;
}


/* =========================================================
   TECHNOLOGY CARDS
========================================================= */

.technology-cards {

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 13px;

    margin-top: 20px;

    margin-bottom: 28px;
}


/* =========================================================
   CARD INDIVIDUAL REVEAL
========================================================= */

.technology-card {

    position: relative;

    display: flex;

    align-items: center;

    gap: 14px;

    min-height: 116px;

    padding: 15px;

    background:
        linear-gradient(145deg,
            #ffffff 0%,
            #f8fbfe 100%);

    border: 1px solid rgba(15, 120, 180, 0.13);

    border-radius: 13px;

    box-shadow:
        0 7px 22px rgba(15, 52, 80, 0.055);

    overflow: hidden;

    opacity: 0;

    transform:
        translateY(35px);

    filter:
        blur(3px);

    transition:
        opacity 0.65s cubic-bezier(0.22, 1, 0.36, 1),
        transform 0.65s cubic-bezier(0.22, 1, 0.36, 1),
        filter 0.65s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CARD STAGGER
========================================================= */

.technology-section.is-visible .technology-card:nth-child(1) {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);

    transition-delay: 0.60s;
}


.technology-section.is-visible .technology-card:nth-child(2) {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);

    transition-delay: 0.70s;
}


.technology-section.is-visible .technology-card:nth-child(3) {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);

    transition-delay: 0.80s;
}


.technology-section.is-visible .technology-card:nth-child(4) {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);

    transition-delay: 0.90s;
}


.technology-section.is-visible .technology-card:nth-child(5) {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);

    transition-delay: 1s;
}


.technology-section.is-visible .technology-card:nth-child(6) {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);

    transition-delay: 1.10s;
}


/* =========================================================
   CARD BLUE EDGE
========================================================= */

.technology-card::before {

    content: "";

    position: absolute;

    left: 0;

    top: 0;

    width: 3px;

    height: 100%;

    background:
        linear-gradient(to bottom,
            transparent,
            #159ee5,
            transparent);

    opacity: 0.45;

    transition:
        opacity 0.35s ease;
}


/* =========================================================
   CARD HOVER
========================================================= */

.technology-card:hover {

    transform:
        translateY(-4px) !important;

    border-color:
        rgba(21, 158, 229, 0.35);

    box-shadow:
        0 14px 32px rgba(15, 80, 120, 0.10);
}


.technology-card:hover::before {

    opacity: 1;
}


/* =========================================================
   CARD ICON
========================================================= */

.technology-card-icon {

    flex: 0 0 64px;

    width: 64px;

    height: 64px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 12px;

    color: #159ee5;

    background:
        linear-gradient(145deg,
            #06233b,
            #0b3857);

    border: 1px solid rgba(56, 189, 248, 0.32);

    box-shadow:

        0 6px 18px rgba(3, 45, 72, 0.16),

        inset 0 0 14px rgba(56, 189, 248, 0.08);

    transition:
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


.technology-card:hover .technology-card-icon {

    transform:
        scale(1.04);

    box-shadow:

        0 8px 24px rgba(21, 158, 229, 0.18),

        0 0 18px rgba(56, 189, 248, 0.12);
}


.technology-card-icon svg {

    width: 34px;

    height: 34px;
}


/* =========================================================
   CARD INFORMATION
========================================================= */

.technology-card-info {

    min-width: 0;

    flex: 1;
}


.technology-card-info h3 {

    margin: 0 0 6px;

    color: #152d47;

    font-size: 15px;

    font-weight: 750;

    line-height: 1.15;

    white-space: nowrap;
}


.technology-card-info p {

    margin: 0;

    color: #718096;

    font-size: 12.5px;

    line-height: 1.55;
}


/* =========================================================
   CTA
========================================================= */

.technology-cta {

    position: relative;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 16px;

    min-width: 235px;

    min-height: 54px;

    padding: 13px 24px;

    color: #159ee5;

    background: #ffffff;

    border: 2px solid #159ee5;

    border-radius: 9px;

    font-size: 16px;

    font-weight: 700;

    text-decoration: none;

    box-shadow:
        0 3px 10px rgba(21, 158, 229, 0.14);

    overflow: hidden;

    transition:
        color 0.35s ease,
        background 0.35s ease,
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CTA SHINE
========================================================= */

.technology-cta::before {

    content: "";

    position: absolute;

    top: 0;

    left: -120%;

    width: 80%;

    height: 100%;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.45),
            transparent);

    transform:
        skewX(-20deg);

    transition:
        left 0.7s ease;
}


.technology-cta:hover::before {

    left: 130%;
}


.technology-cta:hover {

    color: #ffffff;

    background: #159ee5;

    transform:
        translateY(-2px);

    box-shadow:
        0 8px 22px rgba(21, 158, 229, 0.25);
}


/* =========================================================
   CTA ARROW
========================================================= */

.technology-cta-arrow {

    font-size: 21px;

    line-height: 1;

    transition:
        transform 0.3s ease;
}


.technology-cta:hover .technology-cta-arrow {

    transform:
        translateX(5px);
}


/* =========================================================
   RIGHT VISUAL
========================================================= */

.technology-visual {

    position: relative;

    z-index: 2;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.technology-image-wrapper {

    position: relative;

    width: 100%;

    height: 640px;

    overflow: hidden;

    border-radius: 24px;

    background: #020b14;

    border: 1px solid rgba(7, 45, 70, 0.35);

    box-shadow:
        0 25px 55px rgba(8, 38, 60, 0.14);
}


/* =========================================================
   IMAGE
========================================================= */

.technology-image {

    position: absolute;

    inset: 0;

    width: 100%;

    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center center;

    transition:
        transform 1.2s ease;
}


.technology-image-wrapper:hover .technology-image {

    transform:
        scale(1.02);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.technology-image-overlay {

    position: absolute;

    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(180deg,
            rgba(2, 15, 28, 0.05) 0%,
            transparent 45%,
            rgba(1, 10, 20, 0.18) 100%);
}


/* =========================================================
   HOLOGRAM SYSTEM
========================================================= */

.technology-hologram {

    position: absolute;

    left: 35%;

    top: 52%;

    width: 360px;

    height: 360px;

    transform:
        translate(-50%, -50%);

    z-index: 5;

    pointer-events: none;

    overflow: visible;

    perspective: 900px;
}


/* =========================================================
   3D PALM ENERGY SOURCE
========================================================= */

.holo-core {

    position: absolute;

    left: 50%;

    top: 73%;

    width: 78px;

    height: 78px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle at 35% 30%,
            #ffffff 0%,
            rgba(255, 255, 255, 0.98) 6%,
            rgba(210, 243, 255, 0.98) 13%,
            rgba(125, 211, 252, 0.95) 24%,
            rgba(56, 189, 248, 0.72) 39%,
            rgba(14, 165, 233, 0.42) 55%,
            rgba(2, 80, 130, 0.20) 68%,
            transparent 78%);

    box-shadow:

        inset -10px -12px 18px rgba(0, 40, 75, 0.48),

        inset 8px 8px 16px rgba(255, 255, 255, 0.42),

        0 0 14px rgba(125, 211, 252, 1),

        0 0 32px rgba(56, 189, 248, 0.95),

        0 0 65px rgba(14, 165, 233, 0.65),

        0 0 105px rgba(14, 165, 233, 0.32);

    filter:
        blur(0.6px);

    opacity: 0.96;

    z-index: 8;

    animation:
        hologramCore3D 2.1s ease-in-out infinite;
}


/* =========================================================
   3D ENERGY RING
========================================================= */

.holo-core::before {

    content: "";

    position: absolute;

    left: 50%;

    top: 50%;

    width: 38px;

    height: 38px;

    transform:
        translate(-50%, -50%) rotateX(68deg);

    border:
        1px solid rgba(191, 235, 255, 0.95);

    border-radius: 50%;

    box-shadow:

        0 0 8px rgba(125, 211, 252, 1),

        0 0 18px rgba(56, 189, 248, 0.95),

        0 0 34px rgba(56, 189, 248, 0.55);

    animation:
        energyRing3D 1.75s ease-out infinite;
}


/* =========================================================
   3D ENERGY BALL HIGHLIGHT
========================================================= */

.holo-core::after {

    content: "";

    position: absolute;

    left: 26%;

    top: 20%;

    width: 18px;

    height: 12px;

    border-radius: 50%;

    background:
        radial-gradient(ellipse,
            rgba(255, 255, 255, 1) 0%,
            rgba(255, 255, 255, 0.85) 35%,
            rgba(191, 235, 255, 0.30) 65%,
            transparent 100%);

    filter:
        blur(1px);

    transform:
        rotate(-25deg);

    box-shadow:

        0 0 10px rgba(255, 255, 255, 0.95),

        0 0 24px rgba(125, 211, 252, 0.8);
}


/* =========================================================
   3D CORE CENTER
========================================================= */

.holo-core-center {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 12px;

    height: 12px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background: #ffffff;

    box-shadow:

        0 0 8px #ffffff,

        0 0 18px #dff7ff,

        0 0 32px #7dd3fc,

        0 0 55px #38bdf8,

        0 0 85px rgba(56, 189, 248, 0.85);

    z-index: 10;
}


/* =========================================================
   3D CORE PULSE
========================================================= */

@keyframes hologramCore3D {

    0%,
    100% {

        transform:
            translate(-50%, -50%) scale(0.72);

        opacity: 0.55;

        filter:
            blur(2px);

        box-shadow:

            inset -10px -12px 18px rgba(0, 40, 75, 0.45),

            inset 8px 8px 16px rgba(255, 255, 255, 0.35),

            0 0 14px rgba(125, 211, 252, 0.75),

            0 0 35px rgba(56, 189, 248, 0.65),

            0 0 70px rgba(14, 165, 233, 0.35);
    }


    50% {

        transform:
            translate(-50%, -50%) scale(1.12);

        opacity: 1;

        filter:
            blur(0);

        box-shadow:

            inset -12px -14px 20px rgba(0, 40, 75, 0.52),

            inset 10px 10px 18px rgba(255, 255, 255, 0.50),

            0 0 18px rgba(191, 235, 255, 1),

            0 0 40px rgba(56, 189, 248, 1),

            0 0 80px rgba(14, 165, 233, 0.75),

            0 0 125px rgba(14, 165, 233, 0.38);
    }

}


/* =========================================================
   3D RING EXPANSION
========================================================= */

@keyframes energyRing3D {

    0% {

        width: 24px;

        height: 24px;

        opacity: 0;

        transform:
            translate(-50%, -50%) rotateX(68deg) scale(0.6);
    }


    12% {

        opacity: 1;
    }


    55% {

        width: 78px;

        height: 42px;

        opacity: 0.65;

        transform:
            translate(-50%, -50%) rotateX(68deg) scale(1);
    }


    100% {

        width: 125px;

        height: 62px;

        opacity: 0;

        transform:
            translate(-50%, -50%) rotateX(68deg) scale(1.18);
    }

}


/* =========================================================
   PALM CONTACT GLOW
========================================================= */

.technology-hologram::before {

    content: "";

    position: absolute;

    left: 50%;

    top: 73%;

    width: 145px;

    height: 80px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(ellipse,
            rgba(255, 255, 255, 0.70) 0%,
            rgba(191, 235, 255, 0.60) 10%,
            rgba(56, 189, 248, 0.48) 25%,
            rgba(14, 165, 233, 0.24) 45%,
            transparent 76%);

    filter:
        blur(10px);

    opacity: 0.75;

    z-index: 4;

    animation:
        palmContactGlow 2.1s ease-in-out infinite;
}


/* =========================================================
   PALM CONTACT GLOW ANIMATION
========================================================= */

@keyframes palmContactGlow {

    0%,
    100% {

        transform:
            translate(-50%, -50%) scale(0.72);

        opacity: 0.38;
    }


    50% {

        transform:
            translate(-50%, -50%) scale(1.18);

        opacity: 0.88;
    }

}


/* =========================================================
   HOLOGRAM ELEMENT
========================================================= */

.holo-element {

    position: absolute;

    display: flex;

    align-items: center;

    justify-content: center;

    width: 86px;

    height: 48px;

    padding: 0 10px;

    border:
        1px solid rgba(125, 211, 252, 0.95);

    border-radius: 8px;

    background:
        linear-gradient(145deg,
            rgba(56, 189, 248, 0.20),
            rgba(2, 30, 50, 0.10));

    box-shadow:

        0 0 10px rgba(56, 189, 248, 0.90),

        0 0 25px rgba(56, 189, 248, 0.55),

        0 0 48px rgba(56, 189, 248, 0.25),

        inset 0 0 14px rgba(56, 189, 248, 0.22);

    color: #c8f2ff;

    opacity: 0;

    backdrop-filter:
        blur(3px);

    transform-origin:
        center bottom;

    animation:
        handHologramExplosion 4.8s cubic-bezier(0.22, 1, 0.36, 1) infinite;
}


/* =========================================================
   HOLOGRAM INTERNAL SCAN
========================================================= */

.holo-element::after {

    content: "";

    position: absolute;

    left: 8%;

    right: 8%;

    top: 50%;

    height: 1px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.95),
            transparent);

    box-shadow:
        0 0 7px rgba(56, 189, 248, 0.90);

    opacity: 0.65;

    animation:
        holoScanFast 1.4s ease-in-out infinite;
}


/* =========================================================
   HOLOGRAM ICON
========================================================= */

.holo-icon {

    width: 27px;

    height: 27px;

    display: flex;

    align-items: center;

    justify-content: center;

    position: relative;

    z-index: 2;

    filter:
        drop-shadow(0 0 8px rgba(56, 189, 248, 1));
}


.holo-icon svg {

    width: 100%;

    height: 100%;
}


/* =========================================================
   EXPLOSION POSITIONS
========================================================= */

.holo-1 {

    left: 50%;

    top: 72%;

    width: 96px;

    height: 52px;

    animation-delay: 0s;

    --x: -145px;

    --y: -165px;

    --r: -12deg;
}


.holo-2 {

    left: 50%;

    top: 72%;

    width: 88px;

    height: 48px;

    animation-delay: 0.65s;

    --x: 120px;

    --y: -180px;

    --r: 14deg;
}


.holo-3 {

    left: 50%;

    top: 72%;

    width: 102px;

    height: 54px;

    animation-delay: 1.30s;

    --x: -175px;

    --y: -75px;

    --r: -8deg;
}


.holo-4 {

    left: 50%;

    top: 72%;

    width: 84px;

    height: 48px;

    animation-delay: 1.95s;

    --x: 165px;

    --y: -80px;

    --r: 10deg;
}


.holo-5 {

    left: 50%;

    top: 72%;

    width: 94px;

    height: 50px;

    animation-delay: 2.60s;

    --x: -110px;

    --y: -245px;

    --r: -16deg;
}


.holo-6 {

    left: 50%;

    top: 72%;

    width: 88px;

    height: 48px;

    animation-delay: 3.25s;

    --x: 95px;

    --y: -265px;

    --r: 17deg;
}


/* =========================================================
   EXPLOSION ANIMATION
========================================================= */

@keyframes handHologramExplosion {

    /* -----------------------------------------
       0% — داخل الكف
    ----------------------------------------- */

    0% {

        opacity: 0;

        transform:
            translate(-50%, 8px) scale(0.08) rotate(0deg);

        filter:
            blur(6px);

        box-shadow:
            0 0 0 rgba(56, 189, 248, 0);
    }


    /* -----------------------------------------
       7% — شحنة الطاقة
    ----------------------------------------- */

    7% {

        opacity: 0.25;

        transform:
            translate(-50%, 1px) scale(0.25) rotate(var(--r));

        filter:
            blur(3px);
    }


    /* -----------------------------------------
       15% — خروج سريع من الكف
    ----------------------------------------- */

    15% {

        opacity: 1;

        transform:
            translate(-50%, -8px) scale(0.70) rotate(var(--r));

        filter:
            blur(1px);

        box-shadow:

            0 0 20px rgba(125, 211, 252, 1),

            0 0 45px rgba(56, 189, 248, 1),

            0 0 80px rgba(56, 189, 248, 0.65);
    }


    /* -----------------------------------------
       23% — EXPLOSION BURST
    ----------------------------------------- */

    23% {

        opacity: 1;

        transform:
            translate(calc(-50% + var(--x) * 0.38),
                calc(-8px + var(--y) * 0.38)) scale(1.04) rotate(var(--r));

        filter:
            blur(0);

        box-shadow:

            0 0 22px rgba(191, 235, 255, 1),

            0 0 48px rgba(56, 189, 248, 1),

            0 0 90px rgba(14, 165, 233, 0.75),

            0 0 130px rgba(14, 165, 233, 0.30);
    }


    /* -----------------------------------------
       40% — انتشار الانفجار
    ----------------------------------------- */

    40% {

        opacity: 0.96;

        transform:
            translate(calc(-50% + var(--x) * 0.78),
                calc(-8px + var(--y) * 0.78)) scale(0.96) rotate(calc(var(--r) * 1.35));

        filter:
            blur(0);

        box-shadow:

            0 0 18px rgba(125, 211, 252, 1),

            0 0 38px rgba(56, 189, 248, 0.85),

            0 0 70px rgba(14, 165, 233, 0.48);
    }


    /* -----------------------------------------
       54% — الوصول للمسار النهائي
    ----------------------------------------- */

    54% {

        opacity: 0.78;

        transform:
            translate(calc(-50% + var(--x)),
                calc(-8px + var(--y))) scale(0.84) rotate(calc(var(--r) * 1.65));

        filter:
            blur(0.2px);
    }


    /* -----------------------------------------
       67% — استمرار الطاقة
    ----------------------------------------- */

    67% {

        opacity: 0.55;

        transform:
            translate(calc(-50% + var(--x) * 1.08),
                calc(-8px + var(--y) * 1.08)) scale(0.72) rotate(calc(var(--r) * 1.9));

        filter:
            blur(0.7px);
    }


    /* -----------------------------------------
       82% — تلاشي
    ----------------------------------------- */

    82% {

        opacity: 0.28;

        transform:
            translate(calc(-50% + var(--x) * 1.16),
                calc(-8px + var(--y) * 1.18)) scale(0.55) rotate(calc(var(--r) * 2.1));

        filter:
            blur(1.8px);

        box-shadow:

            0 0 10px rgba(56, 189, 248, 0.35);
    }


    /* -----------------------------------------
       100% — اختفاء كامل
    ----------------------------------------- */

    100% {

        opacity: 0;

        transform:
            translate(calc(-50% + var(--x) * 1.25),
                calc(-8px + var(--y) * 1.30)) scale(0.25) rotate(calc(var(--r) * 2.4));

        filter:
            blur(5px);

        box-shadow:
            0 0 0 rgba(56, 189, 248, 0);
    }

}


/* =========================================================
   FAST HOLOGRAM SCAN
========================================================= */

@keyframes holoScanFast {

    0%,
    100% {

        opacity: 0.15;

        transform:
            scaleX(0.45);
    }


    50% {

        opacity: 1;

        transform:
            scaleX(1);
    }

}


/* =========================================================
   BOTTOM BLUE DIVIDER
========================================================= */

.technology-divider {

    position: relative;

    width: 72%;

    height: 2px;

    margin: 68px auto 0;

    background:
        linear-gradient(90deg,
            transparent 0%,
            rgba(21, 158, 229, 0.16) 15%,
            rgba(21, 158, 229, 0.42) 35%,
            rgba(21, 158, 229, 0.68) 50%,
            rgba(21, 158, 229, 0.42) 65%,
            rgba(21, 158, 229, 0.16) 85%,
            transparent 100%);

    box-shadow:
        0 0 8px rgba(21, 158, 229, 0.20);
}


/* =========================================================
   DIVIDER MOVING LIGHT
========================================================= */

.technology-divider span {

    position: absolute;

    top: 50%;

    left: 50%;

    width: 100px;

    height: 8px;

    transform:
        translate(-50%, -50%);

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.85),
            #38bdf8,
            rgba(56, 189, 248, 0.85),
            transparent);

    filter:
        blur(1px);

    box-shadow:

        0 0 12px rgba(56, 189, 248, 0.65),

        0 0 28px rgba(56, 189, 248, 0.30);

    animation:
        dividerLight 4s ease-in-out infinite;
}


/* =========================================================
   DIVIDER ANIMATION
========================================================= */

@keyframes dividerLight {

    0% {

        left: 15%;

        opacity: 0;
    }


    15% {

        opacity: 1;
    }


    50% {

        opacity: 1;
    }


    85% {

        opacity: 1;
    }


    100% {

        left: 85%;

        opacity: 0;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .technology-section .technology-content>*,
    .technology-section .technology-visual,
    .technology-card {

        opacity: 1 !important;

        transform:
            none !important;

        filter:
            none !important;

        transition:
            none !important;
    }


    .holo-core,
    .holo-core::before,
    .technology-hologram::before,
    .holo-element,
    .holo-element::after,
    .technology-divider span {

        animation:
            none !important;
    }

}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .technology-content {

    text-align: right;
}


html[dir="rtl"] .technology-eyebrow {

    flex-direction: row-reverse;

    justify-content: flex-start;

    direction: rtl;
}


html[dir="rtl"] .technology-title-accent {

    margin-right: 0;

    margin-left: auto;
}


html[dir="rtl"] .technology-card {

    direction: rtl;
}


html[dir="rtl"] .technology-card::before {

    left: auto;

    right: 0;
}


html[dir="rtl"] .technology-card-info {

    text-align: right;
}


html[dir="rtl"] .technology-cta {

    direction: rtl;
}


html[dir="rtl"] .technology-cta-arrow {

    transform:
        rotate(180deg);
}


html[dir="rtl"] .technology-cta:hover .technology-cta-arrow {

    transform:
        rotate(180deg) translateX(5px);
}


/* =========================================================
   IT INFRASTRUCTURE SECTION
========================================================= */

.infrastructure-section {

    position: relative;

    width: 100%;

    color: #e7f7ff;

    overflow: hidden;

    padding: 95px 0 75px;

    background:
        radial-gradient(circle at 72% 28%,
            rgba(21, 158, 229, 0.10),
            transparent 32%),
        radial-gradient(circle at 18% 75%,
            rgba(56, 189, 248, 0.055),
            transparent 28%),
        linear-gradient(145deg,
            #061522 0%,
            #081d2d 48%,
            #061421 100%);
}


/* =========================================================
   SUBTLE BACKGROUND GRID
========================================================= */

.infrastructure-section::before {

    content: "";

    position: absolute;

    inset: 0;

    pointer-events: none;

    opacity: 0.16;

    background-image:
        linear-gradient(rgba(56, 189, 248, 0.035) 1px,
            transparent 1px),
        linear-gradient(90deg,
            rgba(56, 189, 248, 0.035) 1px,
            transparent 1px);

    background-size: 55px 55px;

    mask-image:
        linear-gradient(to bottom,
            transparent,
            black 18%,
            black 82%,
            transparent);
}


/* =========================================================
   CONTAINER
========================================================= */

.infrastructure-container {

    position: relative;

    z-index: 2;

    width: min(100% - 40px, 1280px);

    margin-inline: auto;
}


/* =========================================================
   HEADER
========================================================= */

.infrastructure-header {

    position: relative;

    max-width: 1080px;

    margin-bottom: 42px;

    text-align: left;
}


/* =========================================================
   EYEBROW
========================================================= */

.infrastructure-eyebrow {

    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 15px;

    color: #55c9f7;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 0.10em;

    text-transform: uppercase;
}


.infrastructure-eyebrow-line {

    width: 32px;

    height: 2px;

    flex: 0 0 32px;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            #159ee5,
            #7dd3fc);

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.55);
}


/* =========================================================
   TITLE
========================================================= */

.infrastructure-title {

    margin: 0;

    color: #f3fbff;

    font-size: 46px;

    font-weight: 800;

    line-height: 1.08;

    letter-spacing: -0.035em;
}


/* =========================================================
   TITLE ACCENT
========================================================= */

.infrastructure-title-accent {

    width: 75px;

    height: 3px;

    margin-top: 18px;

    margin-bottom: 23px;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            #159ee5,
            rgba(56, 189, 248, 0.10));

    box-shadow:
        0 0 12px rgba(21, 158, 229, 0.30);
}


/* =========================================================
   DESCRIPTION
========================================================= */

.infrastructure-description {

    max-width: 1040px;

    margin: 0;

    color: #a9bdca;

    font-size: 16px;

    font-weight: 400;

    line-height: 1.9;

    letter-spacing: 0.002em;
}


/* =========================================================
   IMAGE VISUAL
========================================================= */

.infrastructure-visual {

    position: relative;

    width: 100%;

    margin-bottom: 25px;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.infrastructure-image-wrapper {

    position: relative;

    width: 100%;

    height: 520px;

    overflow: hidden;

    border-radius: 22px;

    background: #020b14;

    border: 1px solid rgba(56, 189, 248, 0.18);

    box-shadow:

        0 25px 65px rgba(0, 0, 0, 0.30),

        0 0 35px rgba(21, 158, 229, 0.055);

    isolation: isolate;
}


/* =========================================================
   IMAGE
========================================================= */

.infrastructure-image {

    position: absolute;

    inset: 0;

    width: 100%;

    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center;

    transform: scale(1.015);

    transition:
        transform 1.4s cubic-bezier(0.22, 1, 0.36, 1),
        filter 0.8s ease;
}


.infrastructure-image-wrapper:hover .infrastructure-image {

    transform: scale(1.035);

    filter:
        saturate(1.05) brightness(1.04);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.infrastructure-image-overlay {

    position: absolute;

    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(180deg,
            rgba(1, 12, 22, 0.08),
            transparent 38%,
            rgba(1, 12, 22, 0.30)),

        linear-gradient(90deg,
            rgba(3, 22, 36, 0.16),
            transparent 45%,
            rgba(3, 22, 36, 0.12));
}


/* =========================================================
   MOVING IMAGE LIGHT
========================================================= */

.infrastructure-image-wrapper::after {

    content: "";

    position: absolute;

    top: -20%;

    left: -45%;

    width: 28%;

    height: 140%;

    z-index: 3;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.10),
            rgba(255, 255, 255, 0.18),
            rgba(125, 211, 252, 0.08),
            transparent);

    transform:
        skewX(-18deg);

    filter:
        blur(5px);

    animation:
        infrastructureImageSweep 7s ease-in-out infinite;
}


@keyframes infrastructureImageSweep {

    0% {

        left: -45%;

        opacity: 0;
    }

    12% {

        opacity: 0.65;
    }

    38% {

        opacity: 0.32;
    }

    55% {

        opacity: 0;
    }

    100% {

        left: 125%;

        opacity: 0;
    }

}


/* =========================================================
   HOLOGRAM SYSTEM
========================================================= */

.infrastructure-hologram {

    position: absolute;

    left: 50%;

    top: 56%;

    width: 500px;

    height: 400px;

    transform:
        translate(-50%, -50%);

    z-index: 6;

    pointer-events: none;

    perspective: 1000px;

    transform-style: preserve-3d;
}


/* =========================================================
   CENTRAL 3D CORE
========================================================= */

.infra-core {

    position: absolute;

    left: 50%;

    top: 62%;

    width: 72px;

    height: 72px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle at 33% 28%,
            #ffffff 0%,
            rgba(255, 255, 255, 0.98) 7%,
            rgba(210, 244, 255, 0.98) 15%,
            rgba(125, 211, 252, 0.88) 27%,
            rgba(56, 189, 248, 0.55) 43%,
            rgba(14, 165, 233, 0.25) 61%,
            transparent 78%);

    box-shadow:

        inset -10px -12px 18px rgba(0, 35, 65, 0.50),

        inset 8px 8px 16px rgba(255, 255, 255, 0.45),

        0 0 15px rgba(191, 235, 255, 0.95),

        0 0 35px rgba(56, 189, 248, 0.90),

        0 0 70px rgba(14, 165, 233, 0.50);

    opacity: 0.95;

    animation:
        infraCorePulse 2.8s ease-in-out infinite;
}


/* =========================================================
   CORE CENTER
========================================================= */

.infra-core-center {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 10px;

    height: 10px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background: #ffffff;

    box-shadow:

        0 0 8px #ffffff,

        0 0 18px #dff7ff,

        0 0 35px #7dd3fc,

        0 0 58px #38bdf8,

        0 0 90px rgba(56, 189, 248, 0.75);

    z-index: 5;
}


/* =========================================================
   3D CORE RING
========================================================= */

.infra-core::before {

    content: "";

    position: absolute;

    left: 50%;

    top: 50%;

    width: 32px;

    height: 32px;

    transform:
        translate(-50%, -50%) rotateX(68deg);

    border:
        1px solid rgba(191, 235, 255, 0.95);

    border-radius: 50%;

    box-shadow:

        0 0 10px rgba(125, 211, 252, 0.95),

        0 0 25px rgba(56, 189, 248, 0.70);

    animation:
        infraCoreRing 2.4s ease-out infinite;
}


/* =========================================================
   CORE PULSE
========================================================= */

@keyframes infraCorePulse {

    0%,
    100% {

        transform:
            translate(-50%, -50%) scale(0.72);

        opacity: 0.50;
    }

    50% {

        transform:
            translate(-50%, -50%) scale(1.10);

        opacity: 1;
    }

}


/* =========================================================
   CORE RING
========================================================= */

@keyframes infraCoreRing {

    0% {

        width: 22px;

        height: 22px;

        opacity: 0;
    }

    15% {

        opacity: 0.95;
    }

    100% {

        width: 115px;

        height: 58px;

        opacity: 0;

        transform:
            translate(-50%, -50%) rotateX(68deg) scale(1.15);
    }

}


/* =========================================================
   NETWORK LINES
========================================================= */

.infra-network-line {

    position: absolute;

    left: 50%;

    top: 62%;

    width: 2px;

    height: 190px;

    transform-origin: center bottom;

    background:
        linear-gradient(to top,
            rgba(125, 211, 252, 0.95),
            rgba(56, 189, 248, 0.55),
            transparent);

    box-shadow:
        0 0 9px rgba(56, 189, 248, 0.75);

    opacity: 0;

    animation:
        infraNetworkAppear 3.8s ease-out infinite;
}


/* =========================================================
   NETWORK LINE POSITIONS
========================================================= */

.infra-line-1 {

    transform:
        translate(-50%, -100%) rotate(-58deg);

    animation-delay: 0s;
}


.infra-line-2 {

    transform:
        translate(-50%, -100%) rotate(-25deg);

    animation-delay: 0.45s;
}


.infra-line-3 {

    transform:
        translate(-50%, -100%) rotate(27deg);

    animation-delay: 0.9s;
}


.infra-line-4 {

    transform:
        translate(-50%, -100%) rotate(60deg);

    animation-delay: 1.35s;
}


@keyframes infraNetworkAppear {

    0% {

        opacity: 0;

        height: 10px;

        filter: blur(4px);
    }

    20% {

        opacity: 0.85;

        height: 120px;

        filter: blur(1px);
    }

    42% {

        opacity: 0.60;

        height: 190px;

        filter: blur(0);
    }

    70% {

        opacity: 0.28;
    }

    100% {

        opacity: 0;

        height: 220px;

        filter: blur(3px);
    }

}


/* =========================================================
   NODES
========================================================= */

.infra-node {

    position: absolute;

    width: 12px;

    height: 12px;

    border-radius: 50%;

    background: #dff8ff;

    border: 1px solid rgba(125, 211, 252, 0.95);

    box-shadow:

        0 0 8px rgba(255, 255, 255, 0.95),

        0 0 18px rgba(56, 189, 248, 0.95),

        0 0 35px rgba(56, 189, 248, 0.55);

    opacity: 0;

    animation:
        infraNodePulse 3.8s ease-out infinite;
}


.infra-node span {

    position: absolute;

    inset: -7px;

    border:

        1px solid rgba(56, 189, 248, 0.42);

    border-radius: 50%;

    animation:
        infraNodeRing 2.4s ease-out infinite;
}


/* =========================================================
   NODE POSITIONS
========================================================= */

.infra-node-1 {

    left: 20%;

    top: 26%;

    animation-delay: 0.45s;
}


.infra-node-2 {

    left: 78%;

    top: 25%;

    animation-delay: 1.15s;
}


.infra-node-3 {

    left: 12%;

    top: 58%;

    animation-delay: 1.85s;
}


.infra-node-4 {

    left: 85%;

    top: 58%;

    animation-delay: 2.55s;
}


/* =========================================================
   NODE ANIMATION
========================================================= */

@keyframes infraNodePulse {

    0% {

        opacity: 0;

        transform:
            scale(0.2);
    }

    20% {

        opacity: 1;

        transform:
            scale(1);
    }

    48% {

        opacity: 0.82;

        transform:
            scale(1.12);
    }

    75% {

        opacity: 0.38;
    }

    100% {

        opacity: 0;

        transform:
            scale(0.55);
    }

}


@keyframes infraNodeRing {

    0% {

        opacity: 0;

        transform:
            scale(0.35);
    }

    35% {

        opacity: 0.80;
    }

    100% {

        opacity: 0;

        transform:
            scale(2.5);
    }

}


/* =========================================================
   DIGITAL PANELS
========================================================= */

.infra-panel {

    position: absolute;

    display: flex;

    flex-direction: column;

    justify-content: center;

    gap: 5px;

    width: 108px;

    height: 58px;

    padding: 10px 12px;

    border:
        1px solid rgba(125, 211, 252, 0.65);

    border-radius: 7px;

    background:
        linear-gradient(145deg,
            rgba(56, 189, 248, 0.16),
            rgba(2, 30, 50, 0.20));

    box-shadow:

        0 0 10px rgba(56, 189, 248, 0.45),

        0 0 28px rgba(56, 189, 248, 0.20),

        inset 0 0 14px rgba(56, 189, 248, 0.10);

    backdrop-filter:
        blur(4px);

    opacity: 0;

    animation:
        infraPanelExplosion 5.2s cubic-bezier(0.22, 1, 0.36, 1) infinite;
}


/* =========================================================
   PANEL CONTENT
========================================================= */

.infra-panel-dot {

    width: 7px;

    height: 7px;

    border-radius: 50%;

    background: #7dd3fc;

    box-shadow:
        0 0 8px rgba(125, 211, 252, 1);
}


.infra-panel-line {

    display: block;

    width: 72%;

    height: 2px;

    border-radius: 999px;

    background:
        rgba(191, 235, 255, 0.72);

    box-shadow:
        0 0 5px rgba(56, 189, 248, 0.55);
}


.infra-panel-line.short {

    width: 45%;

    opacity: 0.55;
}


/* =========================================================
   PANEL POSITIONS
========================================================= */

.infra-panel-1 {

    left: 7%;

    top: 20%;

    --px: -135px;

    --py: -105px;

    --pr: -8deg;

    animation-delay: 0.2s;
}


.infra-panel-2 {

    right: 5%;

    top: 17%;

    --px: 135px;

    --py: -120px;

    --pr: 9deg;

    animation-delay: 1.1s;
}


.infra-panel-3 {

    left: 2%;

    bottom: 14%;

    --px: -160px;

    --py: 20px;

    --pr: -7deg;

    animation-delay: 2s;
}


.infra-panel-4 {

    right: 1%;

    bottom: 12%;

    --px: 155px;

    --py: 30px;

    --pr: 8deg;

    animation-delay: 2.9s;
}


/* =========================================================
   PANEL EXPLOSION ANIMATION
========================================================= */

@keyframes infraPanelExplosion {

    0% {

        opacity: 0;

        transform:
            translate(-50%, 8px) scale(0.15) rotate(0deg);

        filter:
            blur(5px);
    }

    15% {

        opacity: 0.22;

        transform:
            translate(-50%, 2px) scale(0.35) rotate(var(--pr));

        filter:
            blur(2px);
    }

    27% {

        opacity: 1;

        transform:
            translate(-50%, -8px) scale(0.72) rotate(var(--pr));

        filter:
            blur(0);
    }

    45% {

        opacity: 1;

        transform:
            translate(calc(-50% + var(--px) * 0.55),
                calc(-8px + var(--py) * 0.55)) scale(0.98) rotate(var(--pr));

        filter:
            blur(0);
    }

    63% {

        opacity: 0.78;

        transform:
            translate(var(--px),
                var(--py)) scale(0.92) rotate(calc(var(--pr) * 1.3));

        filter:
            blur(0.2px);
    }

    80% {

        opacity: 0.32;

        transform:
            translate(calc(var(--px) * 1.08),
                calc(var(--py) * 1.08)) scale(0.72) rotate(calc(var(--pr) * 1.6));

        filter:
            blur(1px);
    }

    100% {

        opacity: 0;

        transform:
            translate(calc(var(--px) * 1.18),
                calc(var(--py) * 1.18)) scale(0.42) rotate(calc(var(--pr) * 2));

        filter:
            blur(4px);
    }

}


/* =========================================================
   FLOATING PARTICLES
========================================================= */

.infra-particle {

    position: absolute;

    left: 50%;

    top: 62%;

    width: 5px;

    height: 5px;

    border-radius: 50%;

    background: #bcefff;

    box-shadow:

        0 0 8px rgba(255, 255, 255, 0.95),

        0 0 18px rgba(56, 189, 248, 0.85);

    opacity: 0;

    animation:
        infraParticleExplosion 3.8s ease-out infinite;
}


/* =========================================================
   PARTICLE DIRECTIONS
========================================================= */

.particle-1 {
    --particle-x: -185px;
    --particle-y: -125px;
    animation-delay: 0.15s;
}

.particle-2 {
    --particle-x: 175px;
    --particle-y: -145px;
    animation-delay: 0.65s;
}

.particle-3 {
    --particle-x: -210px;
    --particle-y: -20px;
    animation-delay: 1.15s;
}

.particle-4 {
    --particle-x: 220px;
    --particle-y: -35px;
    animation-delay: 1.65s;
}

.particle-5 {
    --particle-x: -130px;
    --particle-y: -210px;
    animation-delay: 2.15s;
}

.particle-6 {
    --particle-x: 135px;
    --particle-y: -220px;
    animation-delay: 2.65s;
}


/* =========================================================
   PARTICLE ANIMATION
========================================================= */

@keyframes infraParticleExplosion {

    0% {

        opacity: 0;

        transform:
            translate(-50%, -50%) scale(0.2);
    }

    18% {

        opacity: 1;

        transform:
            translate(-50%, -50%) scale(1);
    }

    65% {

        opacity: 0.65;

        transform:
            translate(calc(-50% + var(--particle-x)),
                calc(-50% + var(--particle-y))) scale(0.75);
    }

    100% {

        opacity: 0;

        transform:
            translate(calc(-50% + var(--particle-x) * 1.25),
                calc(-50% + var(--particle-y) * 1.25)) scale(0.2);
    }

}


/* =========================================================
   CARDS GRID
========================================================= */

.infrastructure-cards {

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 14px;

    margin-top: 28px;

    margin-bottom: 32px;
}


/* =========================================================
   CARD
========================================================= */

.infrastructure-card {

    position: relative;

    display: flex;

    align-items: center;

    gap: 15px;

    min-height: 116px;

    padding: 16px;

    overflow: hidden;

    border:
        1px solid rgba(56, 189, 248, 0.15);

    border-radius: 14px;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.075),
            rgba(255, 255, 255, 0.025));

    box-shadow:

        0 12px 28px rgba(0, 0, 0, 0.15),

        inset 0 1px 0 rgba(255, 255, 255, 0.045);

    backdrop-filter:
        blur(7px);

    transition:
        transform 0.35s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CARD BLUE EDGE
========================================================= */

.infrastructure-card::before {

    content: "";

    position: absolute;

    left: 0;

    top: 0;

    width: 3px;

    height: 100%;

    background:
        linear-gradient(to bottom,
            transparent,
            #159ee5,
            transparent);

    opacity: 0.45;

    transition:
        opacity 0.35s ease;
}


/* =========================================================
   CARD HOVER
========================================================= */

.infrastructure-card:hover {

    transform:
        translateY(-5px);

    border-color:
        rgba(56, 189, 248, 0.38);

    box-shadow:

        0 18px 38px rgba(0, 0, 0, 0.22),

        0 0 24px rgba(56, 189, 248, 0.08);
}


.infrastructure-card:hover::before {

    opacity: 1;
}


/* =========================================================
   CARD ICON
========================================================= */

.infrastructure-card-icon {

    flex:
        0 0 62px;

    width: 62px;

    height: 62px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 12px;

    color: #55c9f7;

    background:
        linear-gradient(145deg,
            #06243a,
            #0a3854);

    border:
        1px solid rgba(56, 189, 248, 0.30);

    box-shadow:

        0 7px 18px rgba(0, 0, 0, 0.22),

        inset 0 0 14px rgba(56, 189, 248, 0.08);

    transition:
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


.infrastructure-card:hover .infrastructure-card-icon {

    transform:
        scale(1.04);

    box-shadow:

        0 8px 24px rgba(21, 158, 229, 0.20),

        0 0 18px rgba(56, 189, 248, 0.13);
}


.infrastructure-card-icon svg {

    width: 32px;

    height: 32px;
}


/* =========================================================
   CARD INFORMATION
========================================================= */

.infrastructure-card-info {

    min-width: 0;

    flex: 1;
}


.infrastructure-card-info h3 {

    margin: 0 0 6px;

    color: #eaf8ff;

    font-size: 15px;

    font-weight: 700;

    line-height: 1.25;
}


.infrastructure-card-info p {

    margin: 0;

    color: #8fa9b8;

    font-size: 12.5px;

    line-height: 1.6;
}


/* =========================================================
   CTA WRAPPER
========================================================= */

.infrastructure-cta-wrapper {

    display: flex;

    justify-content: flex-start;

    margin-top: 5px;
}


/* =========================================================
   CTA
========================================================= */

.infrastructure-cta {

    position: relative;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-width: 210px;

    min-height: 52px;

    padding: 13px 26px;

    overflow: hidden;

    color: #7dd3fc;

    background:
        transparent;

    border:
        1px solid #159ee5;

    border-radius: 9px;

    font-size: 15px;

    font-weight: 700;

    text-decoration: none;

    box-shadow:
        0 5px 18px rgba(21, 158, 229, 0.10);

    transition:
        color 0.35s ease,
        background 0.35s ease,
        border-color 0.35s ease,
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CTA FILL
========================================================= */

.infrastructure-cta::after {

    content: "";

    position: absolute;

    inset: 0;

    z-index: -1;

    background:
        linear-gradient(100deg,
            #087ec5,
            #159ee5,
            #38bdf8);

    transform:
        scaleX(0);

    transform-origin: left center;

    transition:
        transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}


/* =========================================================
   CTA SHINE
========================================================= */

.infrastructure-cta::before {

    content: "";

    position: absolute;

    top: -20%;

    left: -110%;

    width: 70%;

    height: 140%;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.75),
            rgba(255, 255, 255, 0.95),
            transparent);

    transform:
        skewX(-20deg);

    filter:
        blur(1px);
}


/* =========================================================
   CTA HOVER
========================================================= */

.infrastructure-cta:hover {

    color: #ffffff;

    border-color: #38bdf8;

    transform:
        translateY(-2px);

    box-shadow:

        0 10px 28px rgba(21, 158, 229, 0.25),

        0 0 22px rgba(56, 189, 248, 0.10);
}


.infrastructure-cta:hover::after {

    transform:
        scaleX(1);
}


.infrastructure-cta:hover::before {

    animation:
        infrastructureButtonShine 0.75s ease forwards;
}


@keyframes infrastructureButtonShine {

    0% {

        left: -110%;

        opacity: 0;
    }

    15% {

        opacity: 1;
    }

    100% {

        left: 140%;

        opacity: 0;
    }

}


/* =========================================================
   BOTTOM DIVIDER
========================================================= */

.infrastructure-divider {

    position: relative;

    width: 72%;

    height: 2px;

    margin: 68px auto 0;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(21, 158, 229, 0.15) 15%,
            rgba(21, 158, 229, 0.42) 35%,
            rgba(21, 158, 229, 0.70) 50%,
            rgba(21, 158, 229, 0.42) 65%,
            rgba(21, 158, 229, 0.15) 85%,
            transparent);

    box-shadow:
        0 0 9px rgba(21, 158, 229, 0.20);
}


/* =========================================================
   DIVIDER MOVING LIGHT
========================================================= */

.infrastructure-divider span {

    position: absolute;

    top: 50%;

    left: 15%;

    width: 100px;

    height: 8px;

    transform:
        translate(-50%, -50%);

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.75),
            #38bdf8,
            rgba(56, 189, 248, 0.75),
            transparent);

    filter:
        blur(1px);

    box-shadow:

        0 0 12px rgba(56, 189, 248, 0.65),

        0 0 28px rgba(56, 189, 248, 0.28);

    animation:
        infrastructureDividerLight 4s ease-in-out infinite;
}


@keyframes infrastructureDividerLight {

    0% {

        left: 15%;

        opacity: 0;
    }

    15% {

        opacity: 1;
    }

    50% {

        opacity: 1;
    }

    85% {

        opacity: 1;
    }

    100% {

        left: 85%;

        opacity: 0;
    }

}


/* =========================================================
   REVEAL ANIMATION
   العناصر تظهر من أسفل إلى أعلى
========================================================= */

.reveal-item {

    opacity: 0;

    transform:
        translateY(38px);

    filter:
        blur(4px);

    transition:
        opacity 0.75s ease,
        transform 0.75s cubic-bezier(0.22, 1, 0.36, 1),
        filter 0.75s ease;
}


/* =========================================================
   ACTIVE REVEAL
========================================================= */

.infrastructure-section.is-visible .reveal-item {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);
}


/* =========================================================
   SEQUENTIAL DELAYS
========================================================= */

.infrastructure-section.is-visible .reveal-item:nth-child(1) {

    transition-delay:
        0.05s;
}


.infrastructure-section.is-visible .reveal-item:nth-child(2) {

    transition-delay:
        0.18s;
}


.infrastructure-section.is-visible .reveal-item:nth-child(3) {

    transition-delay:
        0.31s;
}


.infrastructure-section.is-visible .reveal-item:nth-child(4) {

    transition-delay:
        0.44s;
}


/* =========================================================
   VISUAL DELAY
========================================================= */

.infrastructure-section.is-visible .infrastructure-visual {

    transition-delay:
        0.55s;
}


/* =========================================================
   CARDS SEQUENTIAL DELAY
========================================================= */

.infrastructure-section.is-visible .infrastructure-card:nth-child(1) {

    transition-delay:
        0.68s;
}


.infrastructure-section.is-visible .infrastructure-card:nth-child(2) {

    transition-delay:
        0.80s;
}


.infrastructure-section.is-visible .infrastructure-card:nth-child(3) {

    transition-delay:
        0.92s;
}


.infrastructure-section.is-visible .infrastructure-card:nth-child(4) {

    transition-delay:
        1.04s;
}


/* =========================================================
   CTA DELAY
========================================================= */

.infrastructure-section.is-visible .infrastructure-cta-wrapper {

    transition-delay:
        1.18s;
}


/* =========================================================
   DIVIDER DELAY
========================================================= */

.infrastructure-section.is-visible .infrastructure-divider {

    transition-delay:
        1.30s;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .infrastructure-header {

    text-align: right;
}


html[dir="rtl"] .infrastructure-eyebrow {

    flex-direction: row-reverse;

    justify-content: flex-start;

    direction: rtl;
}


html[dir="rtl"] .infrastructure-title-accent {

    margin-right: 0;

    margin-left: auto;
}


html[dir="rtl"] .infrastructure-card {

    direction: rtl;
}


html[dir="rtl"] .infrastructure-card::before {

    left: auto;

    right: 0;
}


html[dir="rtl"] .infrastructure-card-info {

    text-align: right;
}


html[dir="rtl"] .infrastructure-cta-wrapper {

    justify-content: flex-start;
}


html[dir="rtl"] .infrastructure-cta::after {

    transform-origin:
        right center;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .infrastructure-section *,
    .infrastructure-section *::before,
    .infrastructure-section *::after {

        animation-duration:
            0.01ms !important;

        animation-iteration-count:
            1 !important;

        transition-duration:
            0.01ms !important;
    }

    .reveal-item {

        opacity: 1;

        transform: none;

        filter: none;
    }

}

/* =========================================================
   WEB DESIGN & DEVELOPMENT SECTION
========================================================= */

.web-design-section {

    position: relative;

    width: 100%;

    background: #ffffff;

    color: #10243b;

    overflow: hidden;

    padding: 85px 0 65px;
}


/* =========================================================
   CONTAINER
========================================================= */

.web-design-container {

    position: relative;

    width: min(100% - 40px, 1280px);

    margin-inline: auto;
}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.web-design-layout {

    display: grid;

    grid-template-columns:
        minmax(0, 1.05fr) minmax(500px, 0.95fr);

    gap: 65px;

    align-items: center;
}


/* =========================================================
   CONTENT
========================================================= */

.web-design-content {

