    margin: 0 0 22px;

    color: #718096;

    font-size: 16px;

    font-weight: 400;

    line-height: 1.82;

    letter-spacing: 0.004em;
}


.web-design-description p {

    margin: 0;
}


.web-design-description p+p {

    margin-top: 16px;
}


/* =========================================================
   CARDS GRID
========================================================= */

.web-design-cards {

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 13px;

    margin-top: 20px;

    margin-bottom: 28px;
}


/* =========================================================
   CARD
========================================================= */

.web-design-card {

    position: relative;

    display: flex;

    align-items: center;

    gap: 14px;

    min-height: 116px;

    padding: 15px;

    background:
        linear-gradient(145deg,
            #ffffff 0%,
            #f8fbfe 100%);

    border: 1px solid rgba(15, 120, 180, 0.13);

    border-radius: 13px;

    box-shadow:
        0 7px 22px rgba(15, 52, 80, 0.055);

    overflow: hidden;

    transition:
        transform 0.35s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CARD BLUE EDGE
========================================================= */

.web-design-card::before {

    content: "";

    position: absolute;

    left: 0;

    top: 0;

    width: 3px;

    height: 100%;

    background:
        linear-gradient(to bottom,
            transparent,
            #159ee5,
            transparent);

    opacity: 0.45;

    transition:
        opacity 0.35s ease;
}


/* =========================================================
   CARD HOVER
========================================================= */

.web-design-card:hover {

    transform:
        translateY(-4px);

    border-color:
        rgba(21, 158, 229, 0.35);

    box-shadow:
        0 14px 32px rgba(15, 80, 120, 0.10);
}


.web-design-card:hover::before {

    opacity: 1;
}


/* =========================================================
   CARD ICON
========================================================= */

.web-design-card-icon {

    flex: 0 0 64px;

    width: 64px;

    height: 64px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 12px;

    color: #159ee5;

    background:
        linear-gradient(145deg,
            #06233b,
            #0b3857);

    border: 1px solid rgba(56, 189, 248, 0.32);

    box-shadow:

        0 6px 18px rgba(3, 45, 72, 0.16),

        inset 0 0 14px rgba(56, 189, 248, 0.08);

    transition:
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


.web-design-card:hover .web-design-card-icon {

    transform:
        scale(1.04);

    box-shadow:

        0 8px 24px rgba(21, 158, 229, 0.18),

        0 0 18px rgba(56, 189, 248, 0.12);
}


.web-design-card-icon svg {

    width: 34px;

    height: 34px;
}


/* =========================================================
   CARD INFORMATION
========================================================= */

.web-design-card-info {

    min-width: 0;

    flex: 1;
}


.web-design-card-info h3 {

    margin: 0 0 6px;

    color: #152d47;

    font-size: 15px;

    font-weight: 750;

    line-height: 1.15;

    white-space: nowrap;
}


.web-design-card-info p {

    margin: 0;

    color: #718096;

    font-size: 12.5px;

    line-height: 1.55;
}


/* =========================================================
   CTA
========================================================= */

.web-design-cta {

    position: relative;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-width: 235px;

    min-height: 54px;

    padding: 13px 24px;

    color: #159ee5;

    background: #ffffff;

    border: 2px solid #159ee5;

    border-radius: 9px;

    font-size: 16px;

    font-weight: 700;

    text-decoration: none;

    box-shadow:
        0 3px 10px rgba(21, 158, 229, 0.14);

    overflow: hidden;

    isolation: isolate;

    transition:
        color 0.35s ease,
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CTA BLUE FILL
   LEFT → RIGHT
========================================================= */

.web-design-cta::before {

    content: "";

    position: absolute;

    inset-block: 0;

    inset-inline-start: 0;

    width: 0;

    background:
        linear-gradient(90deg,
            #159ee5,
            #159ee5);

    z-index: -1;

    transition:
        width 0.45s cubic-bezier(0.65,
            0,
            0.35,
            1);
}


/* =========================================================
   CTA SHINE
========================================================= */

.web-design-cta::after {

    content: "";

    position: absolute;

    top: 0;

    left: -120%;

    width: 70%;

    height: 100%;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.42),
            transparent);

    transform:
        skewX(-20deg);

    z-index: 2;

    transition:
        left 0.7s ease;
}


/* =========================================================
   CTA TEXT
========================================================= */

.web-design-cta-text {

    position: relative;

    z-index: 3;

    transition:
        color 0.35s ease;
}


/* =========================================================
   CTA HOVER
========================================================= */

.web-design-cta:hover::before {

    width: 100%;
}


.web-design-cta:hover::after {

    left: 130%;
}


.web-design-cta:hover {

    color: #ffffff;

    transform:
        translateY(-2px);

    box-shadow:
        0 8px 22px rgba(21, 158, 229, 0.25);
}


.web-design-cta:hover .web-design-cta-text {

    color: #ffffff;
}


/* =========================================================
   RIGHT VISUAL
========================================================= */

.web-design-visual {

    position: relative;

    z-index: 2;

    min-width: 0;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.web-design-image-wrapper {

    position: relative;

    width: 100%;

    height: 640px;

    overflow: hidden;

    border-radius: 24px;

    background: #f4f9fc;

    border: 1px solid rgba(7, 45, 70, 0.18);

    box-shadow:
        0 25px 55px rgba(8, 38, 60, 0.13);

    isolation: isolate;
}


/* =========================================================
   IMAGE
========================================================= */

.web-design-image {

    position: absolute;

    inset: 0;

    width: 100%;

    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center center;

    transition:
        transform 1.2s ease;
}


.web-design-image-wrapper:hover .web-design-image {

    transform:
        scale(1.018);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.web-design-image-overlay {

    position: absolute;

    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(180deg,
            rgba(255, 255, 255, 0.02),
            transparent 50%,
            rgba(0, 40, 70, 0.08));
}


/* =========================================================
   TOUCH EFFECT
========================================================= */

.web-touch-effect {

    position: absolute;

    left: 15%;

    top: 28%;

    width: 240px;

    height: 240px;

    transform:
        translate(-50%, -50%);

    z-index: 6;

    pointer-events: none;

    border-radius: 50%;
}


/* =========================================================
   SOFT TOUCH GLOW
========================================================= */

.web-touch-glow {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 75px;

    height: 75px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(255, 255, 255, 0.95) 0%,
            rgba(125, 211, 252, 0.72) 14%,
            rgba(56, 189, 248, 0.42) 32%,
            rgba(14, 165, 233, 0.18) 52%,
            transparent 75%);

    filter:
        blur(3px);

    opacity: 0.8;

    animation:
        touchGlow 2.8s ease-in-out infinite;
}


/* =========================================================
   RIPPLE RINGS
========================================================= */

.web-touch-ring {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 48px;

    height: 48px;

    transform:
        translate(-50%, -50%) scale(0.35);

    border:
        1.5px solid rgba(56, 189, 248, 0.82);

    border-radius: 50%;

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.55),
        inset 0 0 10px rgba(56, 189, 248, 0.15);

    opacity: 0;

    animation:
        touchRipple 3.6s cubic-bezier(0.18,
            0.72,
            0.25,
            1) infinite;
}


/* =========================================================
   RIPPLE DELAYS
========================================================= */

.web-touch-ring-1 {

    animation-delay: 0s;
}


.web-touch-ring-2 {

    animation-delay: 1.2s;
}


.web-touch-ring-3 {

    animation-delay: 2.4s;
}


/* =========================================================
   TOUCH CORE
========================================================= */

.web-touch-core {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 34px;

    height: 34px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle,
            #ffffff 0%,
            rgba(255, 255, 255, 0.98) 12%,
            rgba(191, 235, 255, 0.95) 27%,
            rgba(56, 189, 248, 0.65) 48%,
            rgba(14, 165, 233, 0.20) 68%,
            transparent 78%);

    filter:
        blur(0.6px);

    box-shadow:

        0 0 8px #ffffff,

        0 0 18px rgba(191, 235, 255, 0.95),

        0 0 35px rgba(56, 189, 248, 0.85),

        0 0 65px rgba(14, 165, 233, 0.48);

    animation:
        touchCore 2.8s ease-in-out infinite;
}


/* =========================================================
   TOUCH CENTER DOT
========================================================= */

.web-touch-dot {

    position: absolute;

    left: 50%;

    top: 50%;

    width: 7px;

    height: 7px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background: #ffffff;

    box-shadow:

        0 0 6px #ffffff,

        0 0 14px #ffffff,

        0 0 25px #7dd3fc,

        0 0 40px #38bdf8;

    z-index: 5;
}


/* =========================================================
   BLUE LIGHT SWEEP
========================================================= */

.web-touch-sweep {

    position: absolute;

    inset: -20%;

    z-index: 4;

    pointer-events: none;

    background:
        radial-gradient(ellipse at 57% 51%,
            rgba(56, 189, 248, 0.22) 0%,
            rgba(56, 189, 248, 0.11) 14%,
            rgba(14, 165, 233, 0.055) 28%,
            transparent 52%);

    mix-blend-mode:
        screen;

    opacity: 0;

    animation:
        touchScreenGlow 3.6s ease-in-out infinite;
}


/* =========================================================
   TOUCH GLOW ANIMATION
========================================================= */

@keyframes touchGlow {

    0%,
    100% {

        transform:
            translate(-50%, -50%) scale(0.72);

        opacity: 0.48;
    }

    50% {

        transform:
            translate(-50%, -50%) scale(1.22);

        opacity: 0.92;
    }

}


/* =========================================================
   RIPPLE ANIMATION
========================================================= */

@keyframes touchRipple {

    0% {

        width: 38px;

        height: 38px;

        opacity: 0;

        transform:
            translate(-50%, -50%) scale(0.35);
    }

    8% {

        opacity: 0.9;
    }

    45% {

        opacity: 0.55;
    }

    75% {

        opacity: 0.18;
    }

    100% {

        width: 215px;

        height: 215px;

        opacity: 0;

        transform:
            translate(-50%, -50%) scale(1);
    }

}


/* =========================================================
   CORE ANIMATION
========================================================= */

@keyframes touchCore {

    0%,
    100% {

        transform:
            translate(-50%, -50%) scale(0.76);

        opacity: 0.62;
    }

    45% {

        transform:
            translate(-50%, -50%) scale(1.08);

        opacity: 1;
    }

    70% {

        transform:
            translate(-50%, -50%) scale(0.92);

        opacity: 0.82;
    }

}


/* =========================================================
   SCREEN LIGHT ANIMATION
========================================================= */

@keyframes touchScreenGlow {

    0% {

        opacity: 0;

        transform:
            scale(0.72);
    }

    12% {

        opacity: 0.65;
    }

    38% {

        opacity: 0.28;

        transform:
            scale(1);
    }

    65% {

        opacity: 0.12;
    }

    100% {

        opacity: 0;

        transform:
            scale(1.12);
    }

}


/* =========================================================
   BOTTOM DIVIDER
========================================================= */

.web-design-divider {

position: relative;

    width: 72%;

    height: 2px;

    margin: 68px auto 0;

    background:
        linear-gradient(90deg,
            transparent 0%,
            rgba(21, 158, 229, 0.16) 15%,
            rgba(21, 158, 229, 0.42) 35%,
            rgba(21, 158, 229, 0.68) 50%,
            rgba(21, 158, 229, 0.42) 65%,
            rgba(21, 158, 229, 0.16) 85%,
            transparent 100%);

    box-shadow:
        0 0 8px rgba(21, 158, 229, 0.20);
}


/* =========================================================
   DIVIDER MOVING LIGHT
========================================================= */

.web-design-divider span {

    position: absolute;
    
        top: 50%;
    
        left: 50%;
    
        width: 100px;
    
        height: 8px;
    
        transform:
            translate(-50%, -50%);
    
        border-radius: 999px;
    
        background:
            linear-gradient(90deg,
                transparent,
                rgba(56, 189, 248, 0.85),
                #38bdf8,
                rgba(56, 189, 248, 0.85),
                transparent);
    
        filter:
            blur(1px);
    
        box-shadow:
    
            0 0 12px rgba(56, 189, 248, 0.65),
    
            0 0 28px rgba(56, 189, 248, 0.30);
    
        animation:
            dividerLight 4s ease-in-out infinite;
}


/* =========================================================
   DIVIDER ANIMATION
========================================================= */

@keyframes webDividerLight {

    0% {

        left: 15%;

        opacity: 0;
    }

    15% {

        opacity: 1;
    }

    50% {

        opacity: 1;
    }

    85% {

        opacity: 1;
    }

    100% {

        left: 85%;

        opacity: 0;
    }

}


/* =========================================================
   SCROLL REVEAL
   العناصر تظهر من تحت إلى فوق
========================================================= */

.web-reveal {

    opacity: 0;

    transform:
        translateY(42px);

    filter:
        blur(4px);

    transition:
        opacity 0.8s ease,
        transform 0.8s cubic-bezier(0.22,
            1,
            0.36,
            1),
        filter 0.8s ease;
}


/* =========================================================
   ACTIVE REVEAL
========================================================= */

.web-design-section.web-visible .web-reveal {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);
}


/* =========================================================
   REVEAL DELAYS
========================================================= */

.web-design-section.web-visible .web-reveal-1 {
    transition-delay: 0.05s;
}

.web-design-section.web-visible .web-reveal-2 {
    transition-delay: 0.14s;
}

.web-design-section.web-visible .web-reveal-3 {
    transition-delay: 0.22s;
}

.web-design-section.web-visible .web-reveal-4 {
    transition-delay: 0.30s;
}

.web-design-section.web-visible .web-reveal-5 {
    transition-delay: 0.40s;
}

.web-design-section.web-visible .web-reveal-6 {
    transition-delay: 0.50s;
}

.web-design-section.web-visible .web-reveal-7 {
    transition-delay: 0.60s;
}

.web-design-section.web-visible .web-reveal-8 {
    transition-delay: 0.70s;
}

.web-design-section.web-visible .web-reveal-9 {
    transition-delay: 0.82s;
}

.web-design-section.web-visible .web-reveal-10 {
    transition-delay: 0.50s;
}

.web-design-section.web-visible .web-reveal-11 {
    transition-delay: 1s;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .web-design-layout {

    direction: rtl;
}


html[dir="rtl"] .web-design-content {

    text-align: right;
}


html[dir="rtl"] .web-design-eyebrow {

    flex-direction: row-reverse;

    justify-content: flex-start;

    direction: rtl;
}


html[dir="rtl"] .web-design-title-accent {

    margin-right: 0;

    margin-left: auto;
}


html[dir="rtl"] .web-design-card {

    direction: rtl;
}


html[dir="rtl"] .web-design-card::before {

    left: auto;

    right: 0;
}


html[dir="rtl"] .web-design-card-info {

    text-align: right;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .web-reveal {

        opacity: 1 !important;

        transform: none !important;

        filter: none !important;

        transition: none !important;
    }


    .web-touch-glow,
    .web-touch-ring,
    .web-touch-core,
    .web-touch-sweep,
    .web-design-divider span {

        animation: none !important;
    }

}

/* =========================================================
   SOFTWARE DEVELOPMENT SECTION
========================================================= */

.software-development-section {

    position: relative;
    width: 100%;

    color: #e7f7ff;

    overflow: hidden;

    padding: 95px 0 75px;

    background:
        radial-gradient(circle at 72% 28%,
            rgba(21, 158, 229, 0.10),
            transparent 32%),
        radial-gradient(circle at 18% 75%,
            rgba(56, 189, 248, 0.055),
            transparent 28%),
        linear-gradient(145deg,
            #061522 0%,
            #081d2d 48%,
            #061421 100%);
}


/* =========================================================
   BACKGROUND GRID
========================================================= */

.software-development-section::before {

    content: "";

    position: absolute;

    inset: 0;

    pointer-events: none;

    opacity: 0.16;

    background-image:
        linear-gradient(rgba(56, 189, 248, 0.035) 1px,
            transparent 1px),
        linear-gradient(90deg,
            rgba(56, 189, 248, 0.035) 1px,
            transparent 1px);

    background-size: 55px 55px;

    mask-image:
        linear-gradient(to bottom,
            transparent,
            black 18%,
            black 82%,
            transparent);
}


/* =========================================================
   BACKGROUND GLOW
========================================================= */

.software-development-section::after {

    content: "";

    position: absolute;

    top: 12%;
    right: -12%;

    width: 420px;
    height: 420px;

    pointer-events: none;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.055),
            transparent 68%);

    filter: blur(12px);

    opacity: 0.65;
}


/* =========================================================
   CONTAINER
========================================================= */

.software-development-container {

    position: relative;

    z-index: 2;

    width: min(100% - 40px, 1280px);

    margin-inline: auto;
}


/* =========================================================
   HEADER
========================================================= */

.software-development-header {

    position: relative;

    max-width: 1080px;

    margin-bottom: 42px;

    text-align: left;
}


/* =========================================================
   EYEBROW
========================================================= */

.software-development-eyebrow {

    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 15px;

    color: #55c9f7;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 0.10em;

    text-transform: uppercase;
}


/* =========================================================
   EYEBROW LINE
========================================================= */

.software-development-eyebrow-line {

    width: 32px;

    height: 2px;

    flex: 0 0 32px;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            #159ee5,
            #7dd3fc);

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.55);
}


/* =========================================================
   TITLE
========================================================= */

.software-development-title {

    margin: 0;

    color: #f3fbff;

    font-size: 46px;

    font-weight: 800;

    line-height: 1.08;

    letter-spacing: -0.035em;
}


/* =========================================================
   TITLE ACCENT
========================================================= */

.software-development-title-accent {

    width: 75px;

    height: 3px;

    margin-top: 18px;

    margin-bottom: 23px;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            #159ee5,
            rgba(56, 189, 248, 0.10));

    box-shadow:
        0 0 12px rgba(21, 158, 229, 0.30);
}


/* =========================================================
   DESCRIPTION
========================================================= */

.software-development-description {

    max-width: 1080px;

    margin: 0;

    color: #a9bdca;

    font-size: 16px;

    font-weight: 400;

    line-height: 1.9;

    letter-spacing: 0.002em;
}


/* =========================================================
   VISUAL
========================================================= */

.software-development-visual {

    position: relative;

    width: 100%;

    margin-bottom: 28px;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.software-development-image-wrapper {

    position: relative;

    width: 100%;

    height: 520px;

    overflow: hidden;

    border-radius: 22px;

    background: #020b14;

    border:
        1px solid rgba(56, 189, 248, 0.18);

    box-shadow:
        0 25px 65px rgba(0, 0, 0, 0.30),
        0 0 35px rgba(21, 158, 229, 0.055);

    isolation: isolate;
}


/* =========================================================
   IMAGE
========================================================= */

.software-development-image {

    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center;

    transform: scale(1.015);

    transition:
        transform 1.4s cubic-bezier(0.22, 1, 0.36, 1),
        filter 0.8s ease;
}


/* =========================================================
   IMAGE HOVER
========================================================= */

.software-development-image-wrapper:hover .software-development-image {

    transform: scale(1.035);

    filter:
        saturate(1.08) brightness(1.04);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.software-development-image-overlay {

    position: absolute;

    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(180deg,
            rgba(1, 12, 22, 0.08),
            transparent 38%,
            rgba(1, 12, 22, 0.38)),
        linear-gradient(90deg,
            rgba(3, 22, 36, 0.18),
            transparent 45%,
            rgba(3, 22, 36, 0.16));
}


/* =========================================================
   SOFTWARE HOLOGRAM
========================================================= */

.software-hologram {

    position: absolute;

    inset: 0;

    z-index: 6;

    pointer-events: none;

    overflow: hidden;
}


/* =========================================================
   ACTIVATION ORIGIN
   POINT OF THE FINGER
========================================================= */

.software-origin {

    position: absolute;

    left: 62%;

    top: 31%;

    width: 20px;

    height: 20px;

    transform: translate(-50%, -50%);

    z-index: 20;
}


/* =========================================================
   ORIGIN CORE
========================================================= */

.origin-core {

    position: absolute;

    left: 50%;
    top: 50%;

    width: 8px;
    height: 8px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background: #dff8ff;

    box-shadow:
        0 0 5px #ffffff,
        0 0 12px #7dd3fc,
        0 0 25px #38bdf8,
        0 0 50px rgba(56, 189, 248, 0.75);

    animation:
        softwareOriginPulse 2.2s ease-in-out infinite;
}


/* =========================================================
   ORIGIN FLASH
========================================================= */

.origin-flash {

    position: absolute;

    left: 50%;
    top: 50%;

    width: 5px;
    height: 5px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background: #ffffff;

    box-shadow:
        0 0 10px #ffffff,
        0 0 25px #38bdf8,
        0 0 45px #159ee5;

    animation:
        softwareOriginFlash 2.8s ease-out infinite;
}


/* =========================================================
   ORIGIN RINGS
========================================================= */

.origin-ring {

    position: absolute;

    left: 50%;
    top: 50%;

    border:
        1px solid rgba(125, 211, 252, 0.70);

    border-radius: 50%;

    transform:
        translate(-50%, -50%);

    opacity: 0;
}


/* =========================================================
   ORIGIN RING 01
========================================================= */

.origin-ring-1 {

    width: 25px;
    height: 25px;

    animation:
        softwareOriginRing 2.8s ease-out infinite;
}


/* =========================================================
   ORIGIN RING 02
========================================================= */

.origin-ring-2 {

    width: 48px;
    height: 48px;

    animation:
        softwareOriginRing 2.8s ease-out infinite 0.65s;
}


/* =========================================================
   ORIGIN RING 03
========================================================= */

.origin-ring-3 {

    width: 78px;
    height: 78px;

    animation:
        softwareOriginRing 2.8s ease-out infinite 1.3s;
}


/* =========================================================
   ORIGIN CORE PULSE
========================================================= */

@keyframes softwareOriginPulse {

    0%,
    100% {

        transform:
            translate(-50%, -50%) scale(0.75);

        opacity: 0.70;
    }

    50% {

        transform:
            translate(-50%, -50%) scale(1.35);

        opacity: 1;
    }
}


/* =========================================================
   ORIGIN FLASH ANIMATION
========================================================= */

@keyframes softwareOriginFlash {

    0% {

        transform:
            translate(-50%, -50%) scale(0.4);

        opacity: 0;
    }

    15% {

        transform:
            translate(-50%, -50%) scale(1);

        opacity: 1;
    }

    30% {

        transform:
            translate(-50%, -50%) scale(0.5);

        opacity: 0.3;
    }

    100% {

        transform:
            translate(-50%, -50%) scale(0.2);

        opacity: 0;
    }
