/* =========================================================
   SOFTWARE ORB
========================================================= */

.software-orb {

    position: absolute;

    width: 74px;
    height: 74px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    color: #7dd3fc;

    background:
        radial-gradient(circle at center,
            rgba(56, 189, 248, 0.18),
            rgba(4, 27, 44, 0.60) 55%,
            rgba(1, 10, 19, 0.88) 100%);

    border:
        1px solid rgba(56, 189, 248, 0.72);

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.50),
        0 0 24px rgba(56, 189, 248, 0.26),
        0 0 48px rgba(21, 158, 229, 0.13),
        inset 0 0 18px rgba(56, 189, 248, 0.13);

    backdrop-filter: blur(4px);

    opacity: 0;

    z-index: 8;
}


/* =========================================================
   ORB INNER LIGHT
========================================================= */

.software-orb::before {

    content: "";

    position: absolute;

    inset: 4px;

    border-radius: 50%;

    border:
        1px solid rgba(125, 211, 252, 0.12);

    box-shadow:
        inset 0 0 15px rgba(56, 189, 248, 0.08);

    pointer-events: none;
}


/* =========================================================
   ORB OUTER GLOW
========================================================= */

.software-orb::after {

    content: "";

    position: absolute;

    inset: -3px;

    border-radius: 50%;

    border:
        1px solid rgba(56, 189, 248, 0.20);

    filter: blur(1px);

    opacity: 0.75;

    pointer-events: none;
}


/* =========================================================
   ORB RINGS
========================================================= */

.orb-ring {

    position: absolute;

    border-radius: 50%;

    pointer-events: none;
}


/* =========================================================
   RING A
========================================================= */

.ring-a {

    inset: -7px;

    border:
        1px solid rgba(56, 189, 248, 0.40);

    border-top-color:
        rgba(125, 211, 252, 0.95);

    border-bottom-color:
        transparent;

    animation:
        hologramRingRotate 4s linear infinite;
}


/* =========================================================
   RING B
========================================================= */

.ring-b {

    inset: -12px;

    border:
        1px dashed rgba(56, 189, 248, 0.25);

    animation:
        hologramRingRotateReverse 7s linear infinite;
}


/* =========================================================
   ORB SCAN
========================================================= */

.orb-scan {

    position: absolute;

    left: 12%;
    right: 12%;

    top: -30%;

    height: 18%;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.55),
            transparent);

    filter: blur(2px);

    opacity: 0.45;

    animation:
        orbScan 3.2s ease-in-out infinite;
}


/* =========================================================
   ORB ICON
========================================================= */

.orb-icon {

    position: relative;

    z-index: 3;

    width: 40px;
    height: 40px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.18),
            transparent 70%);

    filter:
        drop-shadow(0 0 8px rgba(56, 189, 248, 0.65));
