/* =========================================================
   CARDS GRID
========================================================= */

.software-development-cards {

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 14px;

    margin-top: 28px;

    margin-bottom: 32px;
    
}


/* =========================================================
   CARD
========================================================= */

.software-development-card {

    position: relative;

    display: flex;

    align-items: center;

    gap: 15px;

    min-height: 116px;

    padding: 16px;

    overflow: hidden;

    border:
        1px solid rgba(56, 189, 248, 0.15);

    border-radius: 14px;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.075),
            rgba(255, 255, 255, 0.025));

    box-shadow:
        0 12px 28px rgba(0, 0, 0, 0.15),
        inset 0 1px 0 rgba(255, 255, 255, 0.045);

    backdrop-filter: blur(7px);

    transition:
        transform 0.35s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease,
        background 0.35s ease;
}


/* =========================================================
   CARD BLUE EDGE
========================================================= */

.software-development-card::before {

    content: "";

    position: absolute;

    left: 0;
    top: 0;

    width: 3px;
    height: 100%;

    background:
        linear-gradient(to bottom,
            transparent,
            #159ee5,
            transparent);

    opacity: 0.45;

    transition:
        opacity 0.35s ease;
}


/* =========================================================
   CARD GLOW
========================================================= */

.software-development-card::after {

    content: "";

    position: absolute;

    top: -80%;
    left: -25%;

    width: 45%;
    height: 260%;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.08),
            transparent);

    transform:
        rotate(18deg) translateX(-120%);

    transition:
        transform 0.7s ease;
}


/* =========================================================
   CARD HOVER
========================================================= */

.software-development-card:hover {

    transform:
        translateY(-5px);

    border-color:
        rgba(56, 189, 248, 0.38);

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.095),
            rgba(255, 255, 255, 0.035));

    box-shadow:
        0 18px 38px rgba(0, 0, 0, 0.22),
        0 0 24px rgba(56, 189, 248, 0.08);
}


.software-development-card:hover::before {

    opacity: 1;
}


.software-development-card:hover::after {

    transform:
        rotate(18deg) translateX(330%);
}


/* =========================================================
   CARD ICON
========================================================= */

.software-development-card-icon {

    position: relative;

    flex:
        0 0 62px;

    width: 62px;
    height: 62px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    color: #55c9f7;

    background:
        linear-gradient(145deg,
            #06243a,
            #0a3854);

    border:
        1px solid rgba(56, 189, 248, 0.30);

    box-shadow:
        0 7px 18px rgba(0, 0, 0, 0.22),
        inset 0 0 14px rgba(56, 189, 248, 0.08);

    transition:
        transform 0.35s ease,
        box-shadow 0.35s ease,
        border-color 0.35s ease;
}


/* =========================================================
   ICON INNER GLOW
========================================================= */

.software-development-card-icon::after {

    content: "";

    position: absolute;

    inset: 5px;

    border-radius: 9px;

    border:
        1px solid rgba(125, 211, 252, 0.07);

    pointer-events: none;
}


/* =========================================================
   ICON HOVER
========================================================= */

.software-development-card:hover .software-development-card-icon {

    transform:
        scale(1.04);

    border-color:
        rgba(56, 189, 248, 0.48);

    box-shadow:
        0 8px 24px rgba(21, 158, 229, 0.20),
        0 0 18px rgba(56, 189, 248, 0.13);
}


/* =========================================================
   ICON SVG
========================================================= */

.software-development-card-icon svg {

    width: 32px;
    height: 32px;

    transition:
        transform 0.35s ease,
        filter 0.35s ease;
}


.software-development-card:hover .software-development-card-icon svg {

    transform:
        scale(1.08);

    filter:
        drop-shadow(0 0 7px rgba(56, 189, 248, 0.42));
}


