    font-size: 15px;

    font-weight: 700;

    text-decoration: none;

    box-shadow:
        0 5px 18px rgba(21, 158, 229, 0.10);

    transition:
        color 0.35s ease,
        background 0.35s ease,
        border-color 0.35s ease,
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CTA FILL
========================================================= */

.software-development-cta::after {

    content: "";

    position: absolute;

    inset: 0;

    z-index: -1;

    background:
        linear-gradient(100deg,
            #087ec5,
            #159ee5,
            #38bdf8);

    transform:
        scaleX(0);

    transform-origin:
        left center;

    transition:
        transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}


/* =========================================================
   CTA SHINE
========================================================= */

.software-development-cta::before {

    content: "";

    position: absolute;

    top: -20%;
    left: -110%;

    width: 70%;
    height: 140%;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.75),
            rgba(255, 255, 255, 0.95),
            transparent);

    transform:
        skewX(-20deg);

    filter: blur(1px);
}


/* =========================================================
   CTA HOVER
========================================================= */

.software-development-cta:hover {

    color: #ffffff;

    border-color:
        #38bdf8;

    transform:
        translateY(-2px);

    box-shadow:
        0 10px 28px rgba(21, 158, 229, 0.25),
        0 0 22px rgba(56, 189, 248, 0.10);
}


.software-development-cta:hover::after {

    transform:
        scaleX(1);
}


.software-development-cta:hover::before {

    animation:
        softwareButtonShine 0.75s ease forwards;
}


/* =========================================================
   CTA SHINE ANIMATION
========================================================= */

@keyframes softwareButtonShine {

    0% {

        left: -110%;

        opacity: 0;
    }

    15% {

        opacity: 1;
    }

    100% {

        left: 140%;

        opacity: 0;
    }
}


/* =========================================================
   BOTTOM DIVIDER
========================================================= */

.software-development-divider {

    position: relative;

    width: 72%;

    height: 2px;

    margin:
        68px auto 0;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(21, 158, 229, 0.15) 15%,
            rgba(21, 158, 229, 0.42) 35%,
            rgba(21, 158, 229, 0.70) 50%,
            rgba(21, 158, 229, 0.42) 65%,
            rgba(21, 158, 229, 0.15) 85%,
            transparent);

    box-shadow:
        0 0 9px rgba(21, 158, 229, 0.20);
}


/* =========================================================
   DIVIDER MOVING LIGHT
========================================================= */

.software-development-divider span {

    position: absolute;

    top: 50%;
    left: 15%;

    width: 100px;
    height: 8px;

    transform:
        translate(-50%, -50%);

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.75),
            #38bdf8,
            rgba(56, 189, 248, 0.75),
            transparent);

    filter:
        blur(1px);

    box-shadow:
        0 0 12px rgba(56, 189, 248, 0.65),
        0 0 28px rgba(56, 189, 248, 0.28);

    animation:
        softwareDividerLight 4s ease-in-out infinite;
}


/* =========================================================
   DIVIDER ANIMATION
========================================================= */

@keyframes softwareDividerLight {

    0% {

        left: 15%;

        opacity: 0;
    }

    15% {

        opacity: 1;
    }

    50% {

        left: 50%;

        opacity: 1;
    }

    85% {

        opacity: 1;
    }

    100% {

        left: 85%;

        opacity: 0;
    }
}


/* =========================================================
   REVEAL ANIMATION
========================================================= */

.software-development-section .reveal-item {

    opacity: 0;

    transform:
        translateY(38px);

    filter:
        blur(4px);

    transition:
        opacity 0.75s ease,
        transform 0.75s cubic-bezier(0.22, 1, 0.36, 1),
        filter 0.75s ease;

    will-change:
        transform,
        opacity,
        filter;
}


/* =========================================================
   ACTIVE REVEAL
========================================================= */

.software-development-section.is-visible .reveal-item {

    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);
}


/* =========================================================
   HEADER REVEAL
========================================================= */

.software-development-section.is-visible .software-development-header {

    transition-delay:
        0.05s;
}


/* =========================================================
   VISUAL REVEAL
========================================================= */

.software-development-section.is-visible .software-development-visual {

    transition-delay:
        0.40s;
}


/* =========================================================
   CARD REVEAL
========================================================= */

.software-development-section.is-visible .software-development-card:nth-child(1) {

    transition-delay:
        0.62s;
}


.software-development-section.is-visible .software-development-card:nth-child(2) {

    transition-delay:
        0.74s;
}


.software-development-section.is-visible .software-development-card:nth-child(3) {

    transition-delay:
        0.86s;
}


.software-development-section.is-visible .software-development-card:nth-child(4) {

    transition-delay:
        0.98s;
}


/* =========================================================
   CTA REVEAL
========================================================= */

.software-development-section.is-visible .software-development-cta-wrapper {

    transition-delay:
        1.12s;
}


/* =========================================================
   DIVIDER REVEAL
========================================================= */

.software-development-section.is-visible .software-development-divider {

    transition-delay:
        1.26s;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .software-development-header {

    text-align: right;
}


html[dir="rtl"] .software-development-eyebrow {

    flex-direction: row-reverse;

    justify-content: flex-start;

    direction: rtl;
}


html[dir="rtl"] .software-development-eyebrow-line {

    background:
        linear-gradient(270deg,
            #159ee5,
            #7dd3fc);
}


html[dir="rtl"] .software-development-title-accent {

    margin-right: 0;

    margin-left: auto;
}


html[dir="rtl"] .software-development-card {

    direction: rtl;
}


html[dir="rtl"] .software-development-card::before {

    left: auto;

    right: 0;
}


html[dir="rtl"] .software-development-card-info {

    text-align: right;
}


html[dir="rtl"] .software-development-cta-wrapper {

    justify-content: flex-start;
}


html[dir="rtl"] .software-development-cta::after {

    transform-origin:
        right center;
}


html[dir="rtl"] .software-development-card-info h3,
html[dir="rtl"] .software-development-card-info p {

    direction: rtl;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .software-development-section *,
    .software-development-section *::before,
    .software-development-section *::after {

        animation-duration:
            0.01ms !important;

        animation-iteration-count:
            1 !important;

        transition-duration:
            0.01ms !important;
    }


    .software-development-section .reveal-item {

        opacity: 1;

        transform: none;

        filter: none;
    }
}


/* =========================================================
   MICROSOFT CLOUD PLATFORM SECTION
========================================================= */

.microsoft-cloud-section {
    position: relative;
    width: 100%;
    background:
        linear-gradient(180deg,
            #ffffff 0%,
            #fafdff 52%,
            #ffffff 100%);
    color: #10243b;
    overflow: hidden;
    padding: 85px 0 65px;
}


/* =========================================================
   SUBTLE SECTION BACKGROUND
========================================================= */

.microsoft-cloud-section::before {
    content: "";
    position: absolute;
    top: 8%;
    right: -180px;
    width: 420px;
    height: 420px;
    border-radius: 50%;
    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.075) 0%,
            rgba(56, 189, 248, 0.025) 42%,
            transparent 72%);
    pointer-events: none;
}

.microsoft-cloud-section::after {
    content: "";
    position: absolute;
    bottom: -180px;
    left: -180px;
    width: 420px;
    height: 420px;
    border-radius: 50%;
    background:
        radial-gradient(circle,
            rgba(14, 165, 233, 0.055) 0%,
            rgba(14, 165, 233, 0.018) 42%,
            transparent 72%);
    pointer-events: none;
}


/* =========================================================
   CONTAINER
========================================================= */

.microsoft-cloud-container {
    position: relative;
    z-index: 2;
    width: min(100% - 40px, 1280px);
    margin-inline: auto;
}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.microsoft-cloud-layout {
    display: grid;
    grid-template-columns:
        minmax(0, 1.02fr) minmax(470px, 0.98fr);
    gap: 62px;
    align-items: center;
}


/* =========================================================
   CONTENT
========================================================= */

.microsoft-cloud-content {
    position: relative;
    z-index: 4;
    min-width: 0;
    max-width: 700px;
}


/* =========================================================
   EYEBROW
========================================================= */

.microsoft-cloud-eyebrow {
    display: flex;
    align-items: center;
    gap: 11px;
    margin-bottom: 17px;
    color: #087ec5;
    font-size: 13px;
    font-weight: 750;
    line-height: 1;
    letter-spacing: 0.075em;
    text-transform: uppercase;
}

.microsoft-cloud-eyebrow-line {
    width: 31px;
    height: 2px;
    flex: 0 0 31px;
    border-radius: 999px;
    background:
        linear-gradient(90deg,
            #159ee5,
            #38bdf8);
    box-shadow:
        0 0 10px rgba(21, 158, 229, 0.32);
}


/* =========================================================
   TITLE
========================================================= */

.microsoft-cloud-title {
    margin: 0;
    max-width: 670px;
    color: #10243b;
    font-size: 46px;
    font-weight: 800;
    line-height: 1.08;
    letter-spacing: -0.035em;
}


/* =========================================================
   TITLE ACCENT
========================================================= */

.microsoft-cloud-title-accent {
    width: 72px;
    height: 3px;
    margin-top: 19px;
    margin-bottom: 24px;
    border-radius: 999px;
    background:
        linear-gradient(90deg,
            #159ee5 0%,
            #38bdf8 45%,
            rgba(56, 189, 248, 0.08) 100%);
    box-shadow:
        0 0 10px rgba(21, 158, 229, 0.24);
}


/* =========================================================
   DESCRIPTION
========================================================= */

.microsoft-cloud-description {
    max-width: 690px;
    margin: 0 0 25px;
    color: #66788b;
    font-size: 15.5px;
    font-weight: 400;
    line-height: 1.82;
    letter-spacing: 0.003em;
}

.microsoft-cloud-description p {
    margin: 0;
}

.microsoft-cloud-description p+p {
    margin-top: 16px;
    color: #748596;
}


/* =========================================================
   CARDS CONTAINER
========================================================= */

.microsoft-cloud-cards {
    display: grid;
    grid-template-columns:
        repeat(2, minmax(0, 1fr));
    gap: 13px;
    width: 100%;
    margin-top: 23px;
    margin-bottom: 27px;
}


/* =========================================================
   MICROSOFT CLOUD CARD
========================================================= */

.microsoft-cloud-card {
    position: relative;
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
    min-height: 118px;
    padding: 15px;

    background:
        linear-gradient(145deg,
            #ffffff 0%,
            #f8fbfe 100%);

    border: 1px solid rgba(15, 120, 180, 0.13);
    border-radius: 14px;

    box-shadow:
        0 7px 22px rgba(15, 52, 80, 0.055);

    overflow: hidden;

    transition:
        transform 0.35s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease,
        background 0.35s ease;
}


/* =========================================================
   CARD BLUE EDGE
========================================================= */

.microsoft-cloud-card::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    width: 3px;
    height: 100%;

    border-radius: 999px;

    background:
        linear-gradient(to bottom,
            transparent,
            #159ee5 25%,
            #38bdf8 50%,
            #159ee5 75%,
            transparent);

    opacity: 0.42;

    pointer-events: none;

    transition:
        opacity 0.35s ease;
}


/* =========================================================
   CARD DIAGONAL SHINE
   Same shine concept as Software Development cards
========================================================= */

.microsoft-cloud-card::after {
    content: "";
    position: absolute;

    top: -80%;
    left: -25%;

    width: 45%;
    height: 260%;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.10),
            transparent);

    transform:
        rotate(18deg) translateX(-120%);

    transition:
        transform 0.7s ease;

    z-index: 3;
}


/* =========================================================
   CARD HOVER
========================================================= */

.microsoft-cloud-card:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(21, 158, 229, 0.32);

    background:
        linear-gradient(145deg,
            #ffffff 0%,
            #f5fbff 100%);

    box-shadow:
        0 15px 32px rgba(15, 80, 120, 0.095);
}

.microsoft-cloud-card:hover::before {
    opacity: 1;
}

.microsoft-cloud-card:hover::after {
    transform:
        rotate(18deg) translateX(330%);
}


/* =========================================================
   CARD ICON
========================================================= */

.microsoft-cloud-card-icon {
    position: relative;
    flex: 0 0 58px;

    width: 58px;
    height: 58px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 13px;

    color: #38bdf8;

    background:
        linear-gradient(145deg,
            #06233b 0%,
            #0b3857 100%);

    border:
        1px solid rgba(56, 189, 248, 0.30);

    box-shadow:
        0 7px 18px rgba(3, 45, 72, 0.16),
        inset 0 0 14px rgba(56, 189, 248, 0.08);

    overflow: hidden;

    transition:
        transform 0.35s ease,
        box-shadow 0.35s ease,
        border-color 0.35s ease;
}

.microsoft-cloud-card-icon::before {
    content: "";
    position: absolute;

    width: 30px;
    height: 30px;

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.20),
            transparent 70%);

    filter: blur(2px);
    opacity: 0.7;
}

.microsoft-cloud-card-icon svg {
    position: relative;
    z-index: 2;

    width: 30px;
    height: 30px;

    display: block;
}

.microsoft-cloud-card:hover .microsoft-cloud-card-icon {
    transform:
        scale(1.045);

    border-color:
        rgba(56, 189, 248, 0.55);

    box-shadow:
        0 9px 25px rgba(21, 158, 229, 0.18),
        0 0 20px rgba(56, 189, 248, 0.13),
        inset 0 0 16px rgba(56, 189, 248, 0.10);
}


/* =========================================================
   CARD INFORMATION
========================================================= */

.microsoft-cloud-card-info {
    min-width: 0;
    flex: 1;
}

.microsoft-cloud-card-info h3 {
    margin: 0 0 7px;

    color: #152d47;

    font-size: 14.5px;
    font-weight: 750;
    line-height: 1.25;

    letter-spacing: -0.01em;
}

.microsoft-cloud-card-info p {
    margin: 0;

    color: #718096;

    font-size: 12.1px;
    font-weight: 400;
    line-height: 1.56;
}


/* =========================================================
   CTA WRAPPER
========================================================= */

.microsoft-cloud-cta-wrapper {
    margin-top: 5px;
}


/* =========================================================
   CTA
========================================================= */

.microsoft-cloud-cta {
    position: relative;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-width: 220px;
    min-height: 53px;

    padding: 13px 24px;

    color: #159ee5;

    background:
        rgba(255, 255, 255, 0.96);

    border:
        2px solid #159ee5;

    border-radius: 9px;

    font-size: 15.5px;
    font-weight: 700;
    line-height: 1;

    text-decoration: none;

    box-shadow:
        0 4px 12px rgba(21, 158, 229, 0.12);

    overflow: hidden;
    isolation: isolate;

    transition:
        color 0.35s ease,
        transform 0.35s ease,
        box-shadow 0.35s ease,
        border-color 0.35s ease;
}


/* =========================================================
   CTA FILL
========================================================= */

.microsoft-cloud-cta::before {
    content: "";

    position: absolute;

    inset-block: 0;
    inset-inline-start: 0;

    width: 0;

    background:
        linear-gradient(90deg,
            #159ee5 0%,
            #1296d9 100%);

    z-index: -1;

    transition:
        width 0.45s cubic-bezier(0.65,
            0,
            0.35,
            1);
}


/* =========================================================
   CTA DIAGONAL SHINE
   Same shine concept as Software Development cards
========================================================= */

.microsoft-cloud-cta::after {
    content: "";

    position: absolute;

    top: -80%;
    left: -25%;

    width: 45%;
    height: 260%;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.30),
            transparent);

    transform:
        rotate(18deg) translateX(-120%);

    transition:
        transform 0.7s ease;

    z-index: 2;
}


/* =========================================================
   CTA TEXT
========================================================= */

.microsoft-cloud-cta-text {
    position: relative;
    z-index: 3;

    transition:
        color 0.35s ease;
}


/* =========================================================
   CTA HOVER
========================================================= */

.microsoft-cloud-cta:hover {
    color: #ffffff;

    border-color:
        #159ee5;

    transform:
        translateY(-2px);

    box-shadow:
        0 9px 23px rgba(21, 158, 229, 0.23);
}

.microsoft-cloud-cta:hover::before {
    width: 100%;
}

.microsoft-cloud-cta:hover::after {
    transform:
        rotate(18deg) translateX(330%);
}

.microsoft-cloud-cta:hover .microsoft-cloud-cta-text {
    color: #ffffff;
}


/* =========================================================
   RIGHT VISUAL
========================================================= */

.microsoft-cloud-visual {
    position: relative;
    z-index: 2;
    min-width: 0;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.microsoft-cloud-image-wrapper {
    position: relative;

    width: 100%;
    height: 640px;

    overflow: hidden;

    border-radius: 24px;

    background: #f1f8fc;

    border:
        1px solid rgba(7, 45, 70, 0.17);

    box-shadow:
        0 25px 55px rgba(8, 38, 60, 0.13);

    isolation: isolate;
}


/* =========================================================
   IMAGE
========================================================= */

.microsoft-cloud-image {
    position: absolute;
    inset: 0;

    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;
    object-position: center center;

    transition:
        transform 1.2s ease;
}

.microsoft-cloud-image-wrapper:hover .microsoft-cloud-image {
    transform:
        scale(1.018);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.microsoft-cloud-image-overlay {
    position: absolute;
    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(180deg,
            rgba(255, 255, 255, 0.035) 0%,
            transparent 42%,
            rgba(0, 40, 70, 0.13) 100%);
}


/* =========================================================
   CLOUD ANIMATION SYSTEM
========================================================= */

.microsoft-cloud-animation {
    position: absolute;
    inset: 0;

    z-index: 5;

    pointer-events: none;
    overflow: hidden;
}


/* =========================================================
   CLOUD GLOW
========================================================= */

.microsoft-cloud-glow {
    position: absolute;

    left: 50%;
    top: 48%;

    width: 290px;
    height: 290px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.25) 0%,
            rgba(56, 189, 248, 0.13) 25%,
            rgba(14, 165, 233, 0.065) 47%,
            transparent 73%);

    filter:
        blur(3px);

    opacity: 0.65;

    animation:
        cloudGlowPulse 4.5s ease-in-out infinite;
}


/* =========================================================
   CLOUD CORE
========================================================= */

.microsoft-cloud-core {
    position: absolute;

    left: 50%;
    top: 48%;

    width: 110px;
    height: 72px;

    transform:
        translate(-50%, -50%);

    display: flex;
    align-items: center;
    justify-content: center;

    color: rgba(255, 255, 255, 0.95);

    border-radius:
        50px 50px 38px 38px;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.97),
            rgba(191, 235, 255, 0.88));

    border:
        1px solid rgba(255, 255, 255, 0.88);

    box-shadow:
        0 0 12px rgba(255, 255, 255, 0.85),
        0 0 28px rgba(125, 211, 252, 0.85),
        0 0 55px rgba(56, 189, 248, 0.55),
        inset 0 -8px 18px rgba(14, 165, 233, 0.14);

    opacity: 0.93;

    animation:
        cloudCoreFloat 4s ease-in-out infinite;
}

.microsoft-cloud-core svg {
    position: relative;
    z-index: 3;

    width: 120px;
    height: 80px;

    overflow: visible;
}


/* =========================================================
   CLOUD CORE HIGHLIGHTS
========================================================= */

.microsoft-cloud-core::before {
    content: "";

    position: absolute;

    left: 16px;
    bottom: 23px;

    width: 43px;
    height: 43px;

    border-radius: 50%;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.98),
            rgba(191, 235, 255, 0.90));

    box-shadow:
        0 0 18px rgba(125, 211, 252, 0.55);
}

.microsoft-cloud-core::after {
    content: "";

    position: absolute;

    right: 14px;
    bottom: 20px;

    width: 55px;
    height: 55px;

    border-radius: 50%;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.98),
            rgba(191, 235, 255, 0.90));

    box-shadow:
        0 0 20px rgba(125, 211, 252, 0.60);
}


/* =========================================================
   ORBIT SYSTEM
========================================================= */

.microsoft-cloud-orbit {
    position: absolute;

    left: 50%;
    top: 48%;

    width: 145px;
    height: 145px;

    transform:
        translate(-50%, -50%);

    border:
        1px solid rgba(125, 211, 252, 0.42);

    border-radius: 50%;

    opacity: 0.48;

    box-shadow:
        0 0 9px rgba(56, 189, 248, 0.16);

    animation:
        cloudOrbitRotate 10s linear infinite;
}

.microsoft-cloud-orbit::before {
    content: "";

    position: absolute;

    left: 50%;
    top: 50%;

    width: 100%;
    height: 34px;

    transform:
        translate(-50%, -50%) rotate(60deg);

    border:
        1px solid rgba(125, 211, 252, 0.25);

    border-radius: 50%;
}

.microsoft-cloud-orbit::after {
    content: "";

    position: absolute;

    left: 50%;
    top: 50%;

    width: 100%;
    height: 34px;

    transform:
        translate(-50%, -50%) rotate(-60deg);

    border:
        1px solid rgba(125, 211, 252, 0.20);

    border-radius: 50%;
}

.microsoft-cloud-orbit span {
    position: absolute;

    top: -4px;
    left: 50%;

    width: 8px;
    height: 8px;

    transform:
        translateX(-50%);

    border-radius: 50%;

    background: #ffffff;

    box-shadow:
        0 0 7px #ffffff,
        0 0 15px #7dd3fc,
        0 0 25px #38bdf8;
}

.microsoft-cloud-orbit-1 {
    width: 155px;
    height: 155px;

    opacity: 0.52;

    animation-duration: 10s;
}

.microsoft-cloud-orbit-2 {
    width: 215px;
    height: 215px;

    transform:
        translate(-50%, -50%) rotate(55deg);

    opacity: 0.34;

    animation-duration: 15s;
    animation-direction: reverse;
}

.microsoft-cloud-orbit-3 {
    width: 275px;
    height: 275px;

    transform:
        translate(-50%, -50%) rotate(-35deg);

    opacity: 0.20;

    animation-duration: 21s;
}


/* =========================================================
   DATA PACKETS
========================================================= */

.microsoft-cloud-packet {
    position: absolute;

    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #ffffff;

    box-shadow:
        0 0 7px #ffffff,
        0 0 15px #7dd3fc,
        0 0 25px #38bdf8;

    opacity: 0;

    animation:
        cloudPacketMove 3.4s linear infinite;
}

.microsoft-cloud-packet-1 {
    left: 29%;
    top: 34%;
    animation-delay: 0s;
}

.microsoft-cloud-packet-2 {
    left: 71%;
    top: 34%;
    animation-delay: 0.85s;
}

.microsoft-cloud-packet-3 {
    left: 29%;
    top: 65%;
    animation-delay: 1.7s;
}

.microsoft-cloud-packet-4 {
    left: 71%;
    top: 65%;
    animation-delay: 2.55s;
}


/* =========================================================
   CLOUD SERVICE NODES
========================================================= */

.microsoft-cloud-node {
    position: absolute;

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 6px;

    min-width: 76px;
    height: 32px;

    padding: 0 9px;

    border-radius: 999px;

    background:
        rgba(5, 32, 52, 0.74);

    border:
        1px solid rgba(125, 211, 252, 0.34);

    color: #d9f6ff;

    font-size: 9px;
    font-weight: 750;

    line-height: 1;
    letter-spacing: 0.10em;

    text-transform: uppercase;

    backdrop-filter:
        blur(8px);

    -webkit-backdrop-filter:
        blur(8px);

    box-shadow:
        0 6px 18px rgba(0, 20, 35, 0.22),
        0 0 15px rgba(56, 189, 248, 0.10);

    animation:
        cloudNodeFloat 4s ease-in-out infinite;
}

.microsoft-cloud-node-icon {
    display: flex;
    align-items: center;
    justify-content: center;

    width: 18px;
    height: 18px;

    flex: 0 0 18px;

    color: #7dd3fc;
}

.microsoft-cloud-node-icon svg {
    width: 17px;
    height: 17px;

    display: block;
}


/* =========================================================
   NODE AZURE
========================================================= */

.microsoft-cloud-node-azure {
    left: 18%;
    top: 25%;

    animation-delay: 0s;
}


/* =========================================================
   NODE 365
========================================================= */

.microsoft-cloud-node-365 {
    right: 17%;
    top: 24%;

    animation-delay: 0.8s;
}


/* =========================================================
   NODE DYNAMICS
========================================================= */

.microsoft-cloud-node-dynamics {
    left: 16%;
    bottom: 25%;

    animation-delay: 1.6s;
}


/* =========================================================
   NODE DATA
========================================================= */

.microsoft-cloud-node-data {
    right: 17%;
    bottom: 24%;

    animation-delay: 2.4s;
}


/* =========================================================
   CENTRAL PULSE
========================================================= */

.microsoft-cloud-pulse {
    position: absolute;

    left: 50%;
    top: 48%;

    width: 18px;
    height: 18px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle,
            #ffffff 0%,
            #ffffff 22%,
            #7dd3fc 45%,
            #38bdf8 70%,
            transparent 100%);

    box-shadow:
        0 0 8px #ffffff,
        0 0 18px #7dd3fc,
        0 0 35px rgba(56, 189, 248, 0.85);

    animation:
        cloudPulse 2.4s ease-in-out infinite;
}


/* =========================================================
   DATA SCAN
========================================================= */

.microsoft-cloud-scan {
    position: absolute;

    left: 50%;
    top: 48%;

    width: 280px;
    height: 1px;

    transform:
        translate(-50%, -50%) rotate(-12deg);

    transform-origin: center;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.72),
            rgba(255, 255, 255, 0.95),
            rgba(125, 211, 252, 0.72),
            transparent);

    box-shadow:
        0 0 9px rgba(56, 189, 248, 0.48);

    opacity: 0;

    animation:
        cloudScan 4.5s ease-in-out infinite;
}


/* =========================================================
   CLOUD GLOW ANIMATION
========================================================= */

@keyframes cloudGlowPulse {

    0%,
    100% {
        transform:
            translate(-50%, -50%) scale(0.82);

        opacity: 0.38;
    }

    50% {
        transform:
            translate(-50%, -50%) scale(1.18);

        opacity: 0.82;
    }
}


/* =========================================================
   CLOUD CORE FLOAT
========================================================= */

@keyframes cloudCoreFloat {

    0%,
    100% {
        transform:
            translate(-50%, -50%) translateY(0) scale(0.96);

        opacity: 0.82;
    }

    50% {
        transform:
            translate(-50%, -50%) translateY(-7px) scale(1.04);

        opacity: 1;
    }
}


/* =========================================================
   ORBIT ROTATION
========================================================= */

@keyframes cloudOrbitRotate {

    from {
        transform:
            translate(-50%, -50%) rotate(0deg);
    }

    to {
        transform:
            translate(-50%, -50%) rotate(360deg);
    }
}


/* =========================================================
   PACKET MOVEMENT
========================================================= */

@keyframes cloudPacketMove {

    0% {
        opacity: 0;

        transform:
            translate(0, 0) scale(0.45);
    }

    15% {
        opacity: 1;
    }

    50% {
        opacity: 0.95;

        transform:
            translate(34px, 17px) scale(1);
    }

    82% {
        opacity: 0.45;

        transform:
            translate(72px, 36px) scale(0.72);
    }

    100% {
        opacity: 0;

        transform:
            translate(106px, 53px) scale(0.3);
    }
}


/* =========================================================
   NODE FLOAT
========================================================= */

@keyframes cloudNodeFloat {

    0%,
    100% {
        transform:
            translateY(0);

        opacity: 0.76;
    }

    50% {
        transform:
            translateY(-5px);

        opacity: 1;
    }
}


/* =========================================================
   CENTRAL PULSE
========================================================= */

@keyframes cloudPulse {

    0%,
    100% {
        transform:
            translate(-50%, -50%) scale(0.65);

        opacity: 0.55;
    }

    50% {
        transform:
            translate(-50%, -50%) scale(1.25);

        opacity: 1;
    }
}


/* =========================================================
   DATA SCAN
========================================================= */

@keyframes cloudScan {

    0% {
        opacity: 0;

        transform:
            translate(-50%, -50%) translateX(-110px) rotate(-12deg) scaleX(0.55);
    }

    18% {
        opacity: 0.65;
    }

    50% {
        opacity: 0.85;

        transform:
            translate(-50%, -50%) translateX(0) rotate(-12deg) scaleX(1);
    }

    82% {
        opacity: 0.45;
    }

    100% {
        opacity: 0;

        transform:
            translate(-50%, -50%) translateX(110px) rotate(-12deg) scaleX(0.55);
    }
}


/* =========================================================
   BOTTOM DIVIDER
========================================================= */

.microsoft-cloud-divider {
    position: relative;

    width: 72%;
    height: 2px;

    margin:
        68px auto 0;

    background:
        linear-gradient(90deg,
            transparent 0%,
            rgba(21, 158, 229, 0.14) 15%,
            rgba(21, 158, 229, 0.40) 35%,
            rgba(21, 158, 229, 0.68) 50%,
            rgba(21, 158, 229, 0.40) 65%,
            rgba(21, 158, 229, 0.14) 85%,
            transparent 100%);

    box-shadow:
        0 0 8px rgba(21, 158, 229, 0.18);
}


/* =========================================================
   DIVIDER MOVING LIGHT
========================================================= */

.microsoft-cloud-divider span {
    position: absolute;

    top: 50%;
    left: 15%;

    width: 100px;
    height: 8px;

    transform:
        translate(-50%, -50%);

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.85),
            #38bdf8,
            rgba(56, 189, 248, 0.85),
            transparent);

    filter:
        blur(1px);

    box-shadow:
        0 0 12px rgba(56, 189, 248, 0.65),
        0 0 28px rgba(56, 189, 248, 0.30);

    animation:
        microsoftCloudDividerLight 4s ease-in-out infinite;
}

@keyframes microsoftCloudDividerLight {

    0% {
        left: 15%;
        opacity: 0;
    }

    15% {
        opacity: 1;
    }

    50% {
        opacity: 1;
    }

    85% {
        opacity: 1;
    }

    100% {
        left: 85%;
        opacity: 0;
    }
}


/* =========================================================
   REVEAL SYSTEM
   Compatible with:
   class="reveal-item"
========================================================= */

.microsoft-cloud-section .reveal-item {
    opacity: 0;

    transform:
        translateY(38px);

    filter:
        blur(4px);

    transition:
        opacity 0.8s ease,
        transform 0.8s cubic-bezier(0.22,
            1,
            0.36,
            1),
        filter 0.8s ease;
}


/* =========================================================
   ACTIVE REVEAL
========================================================= */

.microsoft-cloud-section.is-visible .reveal-item,
.microsoft-cloud-section.visible .reveal-item,
.microsoft-cloud-section.microsoft-cloud-visible .reveal-item {
    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);
}


/* =========================================================
   REVEAL ORDER
   Elements appear one after another
========================================================= */

/* Content */
.microsoft-cloud-section.is-visible .microsoft-cloud-content {
    transition-delay: 0s;
}

.microsoft-cloud-section.is-visible .microsoft-cloud-eyebrow {
    transition-delay: 0.10s;
}

.microsoft-cloud-section.is-visible .microsoft-cloud-title {
    transition-delay: 0.22s;
}

.microsoft-cloud-section.is-visible .microsoft-cloud-description {
    transition-delay: 0.34s;
}


/* Cards */

.microsoft-cloud-section.is-visible .microsoft-cloud-card:nth-child(1) {
    transition-delay: 0.48s;
}

.microsoft-cloud-section.is-visible .microsoft-cloud-card:nth-child(2) {
    transition-delay: 0.60s;
}

.microsoft-cloud-section.is-visible .microsoft-cloud-card:nth-child(3) {
    transition-delay: 0.72s;
}

.microsoft-cloud-section.is-visible .microsoft-cloud-card:nth-child(4) {
    transition-delay: 0.84s;
}


/* CTA */

.microsoft-cloud-section.is-visible .microsoft-cloud-cta-wrapper {
    transition-delay: 0.98s;
}


/* Right visual */

.microsoft-cloud-section.is-visible .microsoft-cloud-visual {
    transition-delay: 1.10s;
}


/* Divider */

.microsoft-cloud-section.is-visible .microsoft-cloud-divider {
    transition-delay: 1.24s;
}


/* =========================================================
   SUPPORT OTHER POSSIBLE JS CLASSES
========================================================= */

.microsoft-cloud-section.visible .microsoft-cloud-content,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-content {
    transition-delay: 0s;
}

.microsoft-cloud-section.visible .microsoft-cloud-eyebrow,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-eyebrow {
    transition-delay: 0.10s;
}

.microsoft-cloud-section.visible .microsoft-cloud-title,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-title {
    transition-delay: 0.22s;
}

.microsoft-cloud-section.visible .microsoft-cloud-description,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-description {
    transition-delay: 0.34s;
}

.microsoft-cloud-section.visible .microsoft-cloud-card:nth-child(1),
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-card:nth-child(1) {
    transition-delay: 0.48s;
}

.microsoft-cloud-section.visible .microsoft-cloud-card:nth-child(2),
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-card:nth-child(2) {
    transition-delay: 0.60s;
}

.microsoft-cloud-section.visible .microsoft-cloud-card:nth-child(3),
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-card:nth-child(3) {
    transition-delay: 0.72s;
}

.microsoft-cloud-section.visible .microsoft-cloud-card:nth-child(4),
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-card:nth-child(4) {
    transition-delay: 0.84s;
}

.microsoft-cloud-section.visible .microsoft-cloud-cta-wrapper,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-cta-wrapper {
    transition-delay: 0.98s;
}

.microsoft-cloud-section.visible .microsoft-cloud-visual,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-visual {
    transition-delay: 1.10s;
}

.microsoft-cloud-section.visible .microsoft-cloud-divider,
.microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-divider {
    transition-delay: 1.24s;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .microsoft-cloud-layout {
    direction: rtl;
}

html[dir="rtl"] .microsoft-cloud-content {
    text-align: right;
}

html[dir="rtl"] .microsoft-cloud-eyebrow {
    flex-direction: row-reverse;
    justify-content: flex-start;
    direction: rtl;
}

html[dir="rtl"] .microsoft-cloud-eyebrow-line {
    background:
        linear-gradient(90deg,
            #38bdf8,
            #159ee5);
}

html[dir="rtl"] .microsoft-cloud-title-accent {
    margin-right: 0;
    margin-left: auto;

    background:
        linear-gradient(270deg,
            #159ee5 0%,
            #38bdf8 45%,
            rgba(56, 189, 248, 0.08) 100%);
}

html[dir="rtl"] .microsoft-cloud-card {
    direction: rtl;
    text-align: right;
}

html[dir="rtl"] .microsoft-cloud-card::before {
    left: auto;
    right: 0;
}

html[dir="rtl"] .microsoft-cloud-card-info {
    text-align: right;
}

html[dir="rtl"] .microsoft-cloud-cta-wrapper {
    text-align: right;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .microsoft-cloud-section .reveal-item {
        opacity: 1 !important;

        transform: none !important;

        filter: none !important;

        transition: none !important;
    }

    .microsoft-cloud-image,
    .microsoft-cloud-glow,
    .microsoft-cloud-core,
    .microsoft-cloud-orbit,
    .microsoft-cloud-packet,
    .microsoft-cloud-node,
    .microsoft-cloud-pulse,
    .microsoft-cloud-scan,
    .microsoft-cloud-divider span {
        animation: none !important;
    }

    .microsoft-cloud-card,
    .microsoft-cloud-card-icon,
    .microsoft-cloud-cta {
        transition: none !important;
    }

    .microsoft-cloud-card::after,
    .microsoft-cloud-cta::after {
        transition: none !important;
    }
}

/* =========================================================
   SECURITY SOLUTIONS SECTION
========================================================= */

.security-solutions-section {
    position: relative;
    width: 100%;
    min-height: 100vh;
    overflow: hidden;

    color: #e7f7ff;

    background:
        radial-gradient(circle at 15% 20%,
            rgba(56, 189, 248, 0.055),
            transparent 28%),
        radial-gradient(circle at 85% 75%,
            rgba(14, 165, 233, 0.045),
            transparent 30%),
        #061b2a;

    padding: 95px 0 80px;
}


/* =========================================================
   CONTAINER
========================================================= */

.security-solutions-container {
    position: relative;
    width: min(100% - 30px, 1200px);
    margin: 0 auto;
}


/* =========================================================
   HEADER
========================================================= */

.security-solutions-header {
    position: relative;
    width: 100%;
}


/* =========================================================
   EYEBROW
========================================================= */

.security-solutions-eyebrow {
    display: flex;
    align-items: center;
    gap: 12px;

    margin-bottom: 18px;

    color: #38bdf8;

    font-size: 13px;
    font-weight: 700;

    letter-spacing: 1.4px;
    text-transform: uppercase;
}


.security-solutions-eyebrow-line {
    display: block;

    width: 28px;
    height: 2px;

    background:
        linear-gradient(90deg,
            transparent,
            #38bdf8);

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.5);
}


/* =========================================================
   TITLE
========================================================= */

.security-solutions-title {
    margin: 0;

    color: #f3fbff;

    font-size: clamp(2.2rem, 4vw, 3.4rem);
    line-height: 1.05;

    font-weight: 800;
    letter-spacing: -1.5px;
}


/* =========================================================
   TITLE ACCENT
========================================================= */

.security-solutions-title-accent {
    position: relative;

    width: 68px;
    height: 3px;

    margin-top: 18px;

    background:
        linear-gradient(90deg,
            #159ee5,
            rgba(21, 158, 229, 0));

    box-shadow:
        0 0 12px rgba(21, 158, 229, 0.45);
}


/* =========================================================
   DESCRIPTION
========================================================= */

.security-solutions-description {
    max-width: 1120px;

    margin-top: 25px;
}


.security-solutions-description p {
    margin: 0 0 10px;

    color: #91aebe;

    font-size: 16px;
    line-height: 1.8;

    font-weight: 500;
}


.security-solutions-description p:last-child {
    margin-bottom: 0;
}


/* =========================================================
   SECURITY VISUAL
========================================================= */

.security-solutions-visual {
    position: relative;

    width: 100%;

    margin-top: 42px;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.security-solutions-image-wrapper {
    position: relative;

    width: 100%;
    height: 465px;

    overflow: hidden;

    border:
        1px solid rgba(56, 189, 248, 0.14);

    border-radius: 18px;

    background: #061521;

    box-shadow:
        0 20px 55px rgba(0, 0, 0, 0.28),
        inset 0 1px 0 rgba(255, 255, 255, 0.035);
}


/* =========================================================
   IMAGE
========================================================= */

.security-solutions-image {
    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    object-fit: cover;

    object-position: center;

    filter:
        saturate(0.9) brightness(0.65) contrast(1.08);

    transform: scale(1.015);

    transition:
        transform 1.2s ease,
        filter 0.8s ease;
}


.security-solutions-image-wrapper:hover .security-solutions-image {
    transform: scale(1.035);

    filter:
        saturate(1) brightness(0.72) contrast(1.08);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.security-solutions-image-overlay {
    position: absolute;

    inset: 0;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            rgba(2, 15, 25, 0.65),
            rgba(3, 19, 31, 0.18),
            rgba(2, 15, 25, 0.58));

    z-index: 2;
}


/* =========================================================
   SECURITY ANIMATION
========================================================= */

.security-solutions-animation {
    position: absolute;

    inset: 0;

    z-index: 5;

    pointer-events: none;
}


/* =========================================================
   CENTRAL GLOW
========================================================= */

.security-central-glow {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 180px;
    height: 180px;

    transform: translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.25),
            rgba(14, 165, 233, 0.08) 42%,
            transparent 72%);

    filter: blur(7px);

    animation:
        securityGlow 3.5s ease-in-out infinite;
}


/* =========================================================
   SHIELD
========================================================= */

.security-shield {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 105px;
    height: 125px;

    transform: translate(-50%, -50%);

    display: flex;
    align-items: center;
    justify-content: center;

    color: #7dd3fc;

    filter:
        drop-shadow(0 0 10px rgba(56, 189, 248, 0.65)) drop-shadow(0 0 28px rgba(14, 165, 233, 0.28));

    animation:
        shieldFloat 4s ease-in-out infinite;
}


.security-shield svg {
    width: 100%;
    height: 100%;
}


/* =========================================================
   PULSE
========================================================= */

.security-pulse {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 45px;
    height: 45px;

    transform: translate(-50%, -50%);

    border:
        1px solid rgba(125, 211, 252, 0.65);

    border-radius: 50%;

    opacity: 0;

    animation:
        securityPulse 2.6s ease-out infinite;
}


/* =========================================================
   SECURITY RINGS
========================================================= */

.security-ring {
    position: absolute;

    left: 50%;
    top: 50%;

    border:
        1px solid rgba(56, 189, 248, 0.25);

    border-radius: 50%;

    transform: translate(-50%, -50%);

    box-shadow:
        0 0 18px rgba(56, 189, 248, 0.05);

    animation:
        securityRingPulse 4s ease-in-out infinite;
}


.security-ring-1 {
    width: 210px;
    height: 210px;
}


.security-ring-2 {
    width: 300px;
    height: 300px;

    border-color:
        rgba(56, 189, 248, 0.17);

    animation-delay: 0.8s;
}


.security-ring-3 {
    width: 400px;
    height: 400px;

    border-color:
        rgba(56, 189, 248, 0.09);

    animation-delay: 1.5s;
}


/* =========================================================
   SCAN LINE
========================================================= */

.security-scan-line {
    position: absolute;

    left: 10%;
    top: 0;

    width: 80%;
    height: 2px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.75),
            transparent);

    box-shadow:
        0 0 14px rgba(56, 189, 248, 0.55);

    opacity: 0.65;

    animation:
        securityScan 4.5s linear infinite;
}


/* =========================================================
   NODES
========================================================= */

.security-node {
    position: absolute;

    display: flex;
    align-items: center;
    gap: 7px;

    padding: 8px 11px;

    border:
        1px solid rgba(56, 189, 248, 0.28);

    border-radius: 9px;

    color: #bdefff;

    background:
        rgba(3, 23, 37, 0.58);

    box-shadow:
        0 8px 22px rgba(0, 0, 0, 0.22),
        inset 0 1px 0 rgba(255, 255, 255, 0.04);

    backdrop-filter: blur(7px);

    font-size: 10px;
    font-weight: 700;

    letter-spacing: 0.8px;

    animation:
        securityNodeFloat 4s ease-in-out infinite;
}


.security-node-icon {
    display: flex;

    width: 22px;
    height: 22px;

    align-items: center;
    justify-content: center;

    color: #38bdf8;
}


.security-node-icon svg {
    width: 100%;
    height: 100%;
}


/* =========================================================
   NODE POSITIONS
========================================================= */

.security-node-network {
    left: 20%;
    top: 25%;
}


.security-node-firewall {
    right: 18%;
    top: 23%;

    animation-delay: 0.7s;
}


.security-node-endpoint {
    left: 18%;
    bottom: 22%;

    animation-delay: 1.2s;
}


.security-node-data {
    right: 18%;
    bottom: 21%;

    animation-delay: 1.8s;
}


/* =========================================================
   LOCK
========================================================= */

.security-lock {
    position: absolute;

    left: 50%;
    top: 68%;

    width: 42px;
    height: 42px;

    transform: translate(-50%, -50%);

    display: flex;
    align-items: center;
    justify-content: center;

    color: #38bdf8;

    border:
        1px solid rgba(56, 189, 248, 0.3);

    border-radius: 50%;

    background:
        rgba(3, 25, 40, 0.65);

    box-shadow:
        0 0 20px rgba(56, 189, 248, 0.15);

    animation:
        lockPulse 3s ease-in-out infinite;
}


.security-lock svg {
    width: 23px;
    height: 23px;
}


/* =========================================================
   DATA PACKETS
========================================================= */

.security-packet {
    position: absolute;

    width: 6px;
    height: 6px;

    border-radius: 50%;

    background: #7dd3fc;

    box-shadow:
        0 0 8px rgba(56, 189, 248, 0.9),
        0 0 18px rgba(56, 189, 248, 0.55);

    animation:
        packetMove 3.8s linear infinite;
}


.security-packet-1 {
    left: 22%;
    top: 34%;
}


.security-packet-2 {
    right: 24%;
    top: 36%;

    animation-delay: 0.8s;
}


.security-packet-3 {
    left: 27%;
    bottom: 32%;

    animation-delay: 1.5s;
}


.security-packet-4 {
    right: 27%;
    bottom: 30%;

    animation-delay: 2.1s;
}


.security-packet-5 {
    left: 50%;
    top: 20%;

    animation-delay: 2.7s;
}


/* =========================================================
   FEATURE CARDS GRID
========================================================= */

.security-solutions-cards {
    position: relative;

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 14px;

    margin-top: 24px;
}


/* =========================================================
   CARD
========================================================= */

.security-solutions-card {
    position: relative;

    display: flex;
    align-items: center;

    gap: 15px;

    min-height: 116px;

    padding: 16px;

    overflow: hidden;

    border:
        1px solid rgba(56, 189, 248, 0.15);

    border-radius: 14px;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.075),
            rgba(255, 255, 255, 0.025));

    box-shadow:
        0 12px 28px rgba(0, 0, 0, 0.15),
        inset 0 1px 0 rgba(255, 255, 255, 0.045);

    backdrop-filter: blur(7px);

    transition:
        transform 0.35s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease,
        background 0.35s ease;
}


/* =========================================================
   CARD BLUE EDGE
========================================================= */

.security-solutions-card::before {
    content: "";

    position: absolute;

    left: 0;
    top: 0;

    width: 3px;
    height: 100%;

    background:
        linear-gradient(to bottom,
            transparent,
            #159ee5,
            transparent);

    opacity: 0.45;

    transition:
        opacity 0.35s ease;
}


/* =========================================================
               CARD SHINE
========================================================= */

.security-solutions-card::after {
    content: "";

    position: absolute;

    top: -80%;
    left: -25%;

    width: 45%;
    height: 260%;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, 0.08),
            transparent);

    transform:
        rotate(18deg) translateX(-120%);

    transition:
        transform 0.7s ease;
}


/* =========================================================
   CARD HOVER
========================================================= */

.security-solutions-card:hover {
    transform:
        translateY(-5px);

    border-color:
        rgba(56, 189, 248, 0.38);

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.095),
            rgba(255, 255, 255, 0.035));

    box-shadow:
        0 18px 38px rgba(0, 0, 0, 0.22),
        0 0 24px rgba(56, 189, 248, 0.08);
}


.security-solutions-card:hover::before {
    opacity: 1;
}


.security-solutions-card:hover::after {
    transform:
        rotate(18deg) translateX(330%);
}


/* =========================================================
   CARD ICON
========================================================= */

.security-solutions-card-icon {
    flex:
        0 0 56px;

    width: 56px;
    height: 56px;

    display: flex;

    align-items: center;
    justify-content: center;

    border:
        1px solid rgba(56, 189, 248, 0.22);

    border-radius: 11px;

    color: #38bdf8;

    background:
        linear-gradient(145deg,
            rgba(56, 189, 248, 0.08),
            rgba(56, 189, 248, 0.025));

    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.04),
        0 7px 16px rgba(0, 0, 0, 0.16);

    transition:
        transform 0.35s ease,
        border-color 0.35s ease,
        box-shadow 0.35s ease;
}


.security-solutions-card-icon svg {
    width: 28px;
    height: 28px;
}


.security-solutions-card:hover .security-solutions-card-icon {
    transform:
        translateY(-2px);

    border-color:
        rgba(56, 189, 248, 0.42);

    box-shadow:
        0 0 18px rgba(56, 189, 248, 0.12);
}


/* =========================================================
   CARD INFO
========================================================= */

.security-solutions-card-info {
    position: relative;

    min-width: 0;

    z-index: 2;
}


.security-solutions-card-info h3 {
    margin: 0 0 6px;

    color: #e9f8ff;

    font-size: 15px;
    line-height: 1.35;

    font-weight: 700;
}


.security-solutions-card-info p {
    margin: 0;

    color: #88a8b8;

    font-size: 12px;
    line-height: 1.65;

    font-weight: 500;
}


/* =========================================================
   CTA WRAPPER
========================================================= */

.security-solutions-cta-wrapper {
    margin-top: 28px;
}


/* =========================================================
   CTA BUTTON
========================================================= */

.security-solutions-cta {

    position: relative;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    min-width: 210px;

    min-height: 52px;

    padding: 13px 26px;

    overflow: hidden;

    color: #7dd3fc;

    background: transparent;

    border:
        1px solid #159ee5;

    border-radius: 9px;

    font-size: 15px;

    font-weight: 700;

    text-decoration: none;

    box-shadow:
        0 5px 18px rgba(21, 158, 229, 0.10);

    transition:
        color 0.35s ease,
        background 0.35s ease,
        border-color 0.35s ease,
        transform 0.35s ease,
        box-shadow 0.35s ease;
}


/* =========================================================
   CTA SHINE
========================================================= */

.security-solutions-cta::after {

    content: "";

    position: absolute;

    inset: 0;

    z-index: -1;

    background:
        linear-gradient(100deg,
            #087ec5,
            #159ee5,
            #38bdf8);

    transform:
        scaleX(0);

    transform-origin:
        left center;

    transition:
        transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}


.security-solutions-cta::before {

    content: "";

    position: absolute;

    top: -20%;
    left: -110%;

    width: 70%;
    height: 140%;

    z-index: 2;

    pointer-events: none;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(255, 255, 255, 0.75),
            rgba(255, 255, 255, 0.95),
            transparent);

    transform:
        skewX(-20deg);

    filter: blur(1px);
}


/* =========================================================
   CTA HOVER
========================================================= */

.security-solutions-cta:hover {

    color: var(--white);

    border-color: #38bdf8;
        

    transform:
        translateY(-2px);

    box-shadow:
        0 10px 28px rgba(21, 158, 229, 0.25),
        0 0 22px rgba(56, 189, 248, 0.10);
}


.security-solutions-cta:hover::after {

    transform:
        scaleX(1);
}


.security-solutions-cta:hover::before {

    animation:
        softwareButtonShine 0.75s ease forwards;
}



/* =========================================================
   BOTTOM DIVIDER
========================================================= */

.security-solutions-divider {
    position: relative;

    width: 72%;
    height: 2px;

    margin:
        68px auto 0;

    background:
        linear-gradient(90deg,
            transparent 0%,
            rgba(21, 158, 229, 0.14) 15%,
            rgba(21, 158, 229, 0.40) 35%,
            rgba(21, 158, 229, 0.68) 50%,
            rgba(21, 158, 229, 0.40) 65%,
            rgba(21, 158, 229, 0.14) 85%,
            transparent 100%);

    box-shadow:
        0 0 8px rgba(21, 158, 229, 0.18);
}


/* =========================================================
   DIVIDER MOVING LIGHT
========================================================= */

.security-solutions-divider span {
    position: absolute;

    top: 50%;
    left: 15%;

    width: 100px;
    height: 8px;

    transform:
        translate(-50%, -50%);

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.85),
            #38bdf8,
            rgba(56, 189, 248, 0.85),
            transparent);

    filter:
        blur(1px);

    box-shadow:
        0 0 12px rgba(56, 189, 248, 0.65),
        0 0 28px rgba(56, 189, 248, 0.30);

    animation:
        securitysolutionsdividerLight 4s ease-in-out infinite;
}

@keyframes securitysolutionsdividerLight {

    0% {
        left: 15%;
        opacity: 0;
    }

    15% {
        opacity: 1;
    }

    50% {
        opacity: 1;
    }

    85% {
        opacity: 1;
    }

    100% {
        left: 85%;
        opacity: 0;
    }
}


/* =========================================================
   REVEAL SYSTEM
   Compatible with the JavaScript
========================================================= */

.security-solutions-section .reveal-item {
    opacity: 0;

    transform:
        translateY(28px);

    filter:
        blur(4px);

    transition:
        opacity 0.75s ease,
        transform 0.75s ease,
        filter 0.75s ease;
}


.security-solutions-section.is-visible .reveal-item {
    opacity: 1;

    transform:
        translateY(0);

    filter:
        blur(0);
}


/* =========================================================
   REVEAL DELAYS
========================================================= */

.security-solutions-section.is-visible .security-solutions-eyebrow {
    transition-delay: 0.05s;
}


.security-solutions-section.is-visible .security-solutions-title {
    transition-delay: 0.12s;
}


.security-solutions-section.is-visible .security-solutions-description {
    transition-delay: 0.2s;
}


.security-solutions-section.is-visible .security-solutions-visual {
    transition-delay: 0.28s;
}


.security-solutions-section.is-visible .security-solutions-card:nth-child(1) {
    transition-delay: 0.36s;
}


.security-solutions-section.is-visible .security-solutions-card:nth-child(2) {
    transition-delay: 0.44s;
}


.security-solutions-section.is-visible .security-solutions-card:nth-child(3) {
    transition-delay: 0.52s;
}


.security-solutions-section.is-visible .security-solutions-card:nth-child(4) {
    transition-delay: 0.60s;
}


.security-solutions-section.is-visible .security-solutions-cta-wrapper {
    transition-delay: 0.68s;
}


.security-solutions-section.is-visible .security-solutions-divider {
    transition-delay: 0.78s;
}


/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes securityGlow {

    0%,
    100% {
        transform:
            translate(-50%, -50%) scale(0.9);

        opacity: 0.65;
    }

    50% {
        transform:
            translate(-50%, -50%) scale(1.12);

        opacity: 1;
    }
}


@keyframes shieldFloat {

    0%,
    100% {
        transform:
            translate(-50%, -50%) translateY(0);
    }

    50% {
        transform:
            translate(-50%, -50%) translateY(-7px);
    }
}


@keyframes securityPulse {

    0% {
        width: 45px;
        height: 45px;

        opacity: 0.8;
    }

    100% {
        width: 250px;
        height: 250px;

        opacity: 0;
    }
}


@keyframes securityRingPulse {

    0%,
    100% {
        opacity: 0.35;
    }

    50% {
        opacity: 0.8;
    }
}


@keyframes securityScan {

    0% {
        transform:
            translateY(-10px);

        opacity: 0;
    }

    10% {
        opacity: 0.7;
    }

    90% {
        opacity: 0.7;
    }

    100% {
        transform:
            translateY(465px);

        opacity: 0;
    }
}


@keyframes securityNodeFloat {

    0%,
    100% {
        transform:
            translateY(0);
    }

    50% {
        transform:
            translateY(-5px);
    }
}


@keyframes lockPulse {

    0%,
    100% {
        box-shadow:
            0 0 15px rgba(56, 189, 248, 0.08);
    }

    50% {
        box-shadow:
            0 0 28px rgba(56, 189, 248, 0.28);
    }
}


@keyframes packetMove {

    0% {
        transform:
            scale(0.6) translate(0, 0);

        opacity: 0;
    }

    20% {
        opacity: 1;
    }

    80% {
        opacity: 1;
    }

    100% {
        transform:
            scale(1) translate(45px, 25px);

        opacity: 0;
    }
}


@keyframes securityDividerPulse {

    0%,
    100% {
        transform:
            translateY(-50%) translateX(0);

        opacity: 0.5;
    }

    50% {
        transform:
            translateY(-50%) translateX(80px);

        opacity: 1;
    }
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .security-solutions-eyebrow {
    flex-direction: row-reverse;

    justify-content: flex-start;
}


html[dir="rtl"] .security-solutions-card {
    direction: rtl;
}


html[dir="rtl"] .security-solutions-card-info {
    text-align: right;
}


html[dir="rtl"] .security-solutions-description {
    text-align: right;
}


html[dir="rtl"] .security-solutions-title {
    text-align: right;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .security-solutions-section *,
    .security-solutions-section *::before,
    .security-solutions-section *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

}



/* =========================================================
   SOLUTIONS SECTION
========================================================= */

#solutions {

    position: relative;
    width: 100%;
    overflow: hidden;
    padding: 100px 0;

    color: #ffffff;

    background:
        radial-gradient(circle at 12% 15%,
            rgba(56, 189, 248, 0.35),
            transparent 30%),

        radial-gradient(circle at 88% 85%,
            rgba(37, 99, 235, 0.22),
            transparent 32%),

        linear-gradient(135deg,
            #ffffff 0%,
            #eef8ff 22%,
            #d7efff 40%,
            #7dd3fc 62%,
            #38bdf8 82%,
            #159ee5 100%);
}


/* =========================================================
   BACKGROUND LIGHT
========================================================= */

#solutions::before {

    content: "";

    position: absolute;
    inset: 0;

    pointer-events: none;


    background:

        linear-gradient(115deg,

            transparent 0%,

            rgba(255, 255, 255, 0.55) 25%,

            rgba(255, 255, 255, 0.20) 45%,

            rgba(56, 189, 248, 0.18) 65%,

            transparent 100%);


    animation:
        solutionsBackgroundMove 10s ease-in-out infinite alternate;
}


@keyframes solutionsBackgroundMove {

    0% {

        transform: translateX(-3%);
        opacity: .65;

    }


    100% {

        transform: translateX(3%);
        opacity: 1;

    }

}


/* =========================================================
   CONTAINER
========================================================= */

#solutions .solutions-container {
    position: relative;
    z-index: 2;

    width: min(1180px, calc(100% - 40px));
    margin: 0 auto;
}


/* =========================================================
   HEADER
========================================================= */

#solutions .solutions-header {
    position: relative;

    display: flex;
    align-items: stretch;

    max-width: 980px;
    margin: 0 auto 58px;

    padding-left: 30px;
}

#solutions .solutions-header-content {
    position: relative;
    width: 100%;
}


/* =========================================================
   VERTICAL BORDER
   Based on SERVICES HERO line style
========================================================= */

#solutions .solutions-header-border {
    position: absolute;

    left: 0;
    top: 0;

    width: 5px;
    height: 100%;

    overflow: hidden;

    border-radius: 999px;

    background:
        linear-gradient(to bottom,
            rgba(56, 189, 248, 0.18),
            rgba(56, 189, 248, 0.42),
            rgba(56, 189, 248, 0.18));

    box-shadow:
        0 0 12px rgba(56, 189, 248, 0.20),
        inset 0 0 5px rgba(56, 189, 248, 0.22);
}


/* =========================================================
   MOVING LIGHT INSIDE BORDER
========================================================= */

#solutions .solutions-header-border span {
    position: absolute;

    top: -40%;
    left: 0;

    width: 100%;
    height: 40%;

    border-radius: inherit;

    background:
        linear-gradient(to bottom,
            transparent 0%,
            rgba(125, 211, 252, 0.40) 25%,
            #38bdf8 50%,
            rgba(125, 211, 252, 0.40) 75%,
            transparent 100%);

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.85),
        0 0 24px rgba(56, 189, 248, 0.45);

    animation:
        solutionsBorderLight 4s ease-in-out infinite;
}


/* =========================================================
   BORDER LIGHT ANIMATION
========================================================= */

@keyframes solutionsBorderLight {

    0% {
        top: -40%;
        opacity: 0;
    }

    12% {
        opacity: 1;
    }

    50% {
        top: 30%;
        opacity: 1;
    }

    88% {
        opacity: 1;
    }

    100% {
        top: 100%;
        opacity: 0;
    }
}


/* =========================================================
   EYEBROW
========================================================= */

#solutions .solutions-eyebrow {
    margin-bottom: 12px;

    color: #7dd3fc;

    font-size: 13px;
    font-weight: 700;

    letter-spacing: 2.5px;
    text-transform: uppercase;

    text-shadow:
        0 0 10px rgba(56, 189, 248, 0.25);
}


/* =========================================================
   MAIN TITLE
========================================================= */

#solutions .solutions-title {
    position: relative;

    margin: 0 0 22px;

        color: var(--text-primary);

    /*
        Keep original title size
    */
    font-size: clamp(1.75rem, 3.2vw, 2.65rem);

    font-weight: 800;

    line-height: 1.15;

    letter-spacing: -0.4px;

    text-align: left;

    /*
        White text + blue light sweep
    */
    background:
        linear-gradient(110deg,

            #ffffff 0%,
            #ffffff 32%,
            #ffffff 42%,

            #7dd3fc 48%,
            #38bdf8 51%,
            #7dd3fc 54%,

            #ffffff 62%,
            #ffffff 100%);

    background-size: 260% 100%;
    background-position: 120% 0;

    -webkit-background-clip: text;
    background-clip: text;

    -webkit-text-fill-color: transparent;

    animation:
        solutionsTitleReveal 1.1s cubic-bezier(0.22, 1, 0.36, 1) 0.65s both,

        solutionsTitleLight 8s linear 1.8s infinite;

    filter:
        drop-shadow(0 0 0 rgba(56, 189, 248, 0));

    z-index: 2;
}


/* =========================================================
   TITLE REVEAL
========================================================= */

@keyframes solutionsTitleReveal {

    0% {

        opacity: 0;

        transform:
            translateY(25px);

        filter:
            blur(6px);
    }

    55% {
        opacity: 0.75;
    }

    75% {
        opacity: 0.92;
    }

    100% {

        opacity: 1;

        transform:
            translateY(0);

        filter:
            blur(0);
    }
}


/* =========================================================
   BLUE LIGHT SWEEP
========================================================= */

@keyframes solutionsTitleLight {

    0% {

        background-position: 120% 0;

        filter:
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }

    30% {

        background-position: 75% 0;

        filter:
            drop-shadow(0 0 1px rgba(56, 189, 248, 0.05));
    }

    42% {

        background-position: 55% 0;

        filter:
            drop-shadow(0 0 4px rgba(56, 189, 248, 0.12));
    }

    48% {

        background-position: 40% 0;

        filter:
            drop-shadow(0 0 8px rgba(56, 189, 248, 0.25));
    }

    52% {

        background-position: 30% 0;

        filter:
            drop-shadow(0 0 16px rgba(56, 189, 248, 0.42));
    }

    58% {

        background-position: 15% 0;

        filter:
            drop-shadow(0 0 7px rgba(56, 189, 248, 0.18));
    }

    70% {

        background-position: -10% 0;

        filter:
            drop-shadow(0 0 2px rgba(56, 189, 248, 0.06));
    }

    82% {

        background-position: -45% 0;

        filter:
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }

    100% {

        background-position: -120% 0;

        filter:
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }
}


/* =========================================================
   DESCRIPTION
========================================================= */

#solutions .solutions-description {
    max-width: 900px;
}

#solutions .solutions-description p {
    margin: 0;

    color: var(--text-secondary);

    font-size: 16px;
    line-height: 1.9;

    text-align: left;
}


/* =========================================================
   SOLUTIONS GRID
========================================================= */

#solutions .solutions-grid {
    position: relative;

    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    /*
        Small spacing between cards
        Prevents hover borders from touching
    */
    gap: 18px;

    margin-top: 20px;

    align-items: stretch;
}


/* =========================================================
   SOLUTION CARD
========================================================= */

#solutions .solution-card {
    position: relative;

    min-height: 365px;

    padding: 34px 30px;

    overflow: hidden;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.14),
            rgba(255, 255, 255, 0.045));

    border:
        1px solid rgba(125, 211, 252, 0.16);

    border-radius: 18px;

    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.20),
        0 8px 25px rgba(2, 25, 42, 0.10);

    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);

    transition:
        transform 0.45s ease,
        background 0.45s ease,
        border-color 0.45s ease,
        box-shadow 0.45s ease,
        border-radius 0.45s ease;

    z-index: 1;
}


/* =========================================================
   CARD INNER
========================================================= */

#solutions .solution-card-inner {
    position: relative;

    height: 100%;

    display: flex;
    flex-direction: column;
}


/* =========================================================
   CARD SEPARATOR
   Disabled because GRID GAP is now used
========================================================= */

#solutions .solution-card:not(:last-child)::before {
    display: none;
}


/* =========================================================
   CARD HOVER BASE
========================================================= */

#solutions .solution-card:hover {
    transform:
        translateY(-12px) scale(1.035);

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.90),
            rgba(232, 248, 255, 0.58));

    border-color:
        rgba(56, 189, 248, 0.95);

    border-radius: 18px;

    box-shadow:
        inset 0 0 0 1px rgba(56, 189, 248, 0.20),
        0 0 0 1px rgba(56, 189, 248, 0.28),
        -10px -10px 30px rgba(56, 189, 248, 0.13),
        10px 10px 32px rgba(56, 189, 248, 0.18),
        0 25px 55px rgba(15, 65, 95, 0.20),
        0 0 35px rgba(56, 189, 248, 0.16);

    z-index: 10;
}


/* =========================================================
   TOP LEFT GLOW
========================================================= */

#solutions .solution-card:hover::before {
    content: "";

    position: absolute;

    top: -45px;
    left: -45px;

    width: 90px;
    height: 90px;

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.75),
            rgba(56, 189, 248, 0.18) 35%,
            transparent 72%);

    filter: blur(7px);

    pointer-events: none;

    z-index: 0;
}


/* =========================================================
   BOTTOM RIGHT GLOW
========================================================= */

#solutions .solution-card::after {
    content: "";

    position: absolute;

    right: -45px;
    bottom: -45px;

    width: 90px;
    height: 90px;

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(56, 189, 248, 0.65),
            rgba(56, 189, 248, 0.14) 35%,
            transparent 72%);

    filter: blur(8px);

    opacity: 0;

    transition:
        opacity 0.45s ease;

    pointer-events: none;
}

#solutions .solution-card:hover::after {
    opacity: 1;
}


/* =========================================================
   ICON
========================================================= */

#solutions .solution-card-icon {
    position: relative;

    width: 66px;
    height: 66px;

    margin-bottom: 25px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border:
        1px solid rgba(56, 189, 248, 0.35);

    border-radius: 17px;

    background:
        linear-gradient(145deg,
            rgba(56, 189, 248, 0.23),
            rgba(56, 189, 248, 0.055));

    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.40),
        0 8px 22px rgba(56, 189, 248, 0.10);

    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);

    transition:
        transform 0.4s ease,
        border-color 0.4s ease,
        box-shadow 0.4s ease;
}


/* =========================================================
   ICON INNER GLASS
========================================================= */

#solutions .solution-card-icon::after {
    content: "";

    position: absolute;

    inset: 7px;

    border:
        1px solid rgba(255, 255, 255, 0.20);

    border-radius: 12px;

    pointer-events: none;
}


/* =========================================================
   SVG ICON
========================================================= */

#solutions .solution-card-icon svg {
    position: relative;

    z-index: 2;

    width: 32px;
    height: 32px;

    stroke: #38bdf8;

    filter:
        drop-shadow(0 0 6px rgba(56, 189, 248, 0.45));

    transition:
        transform 0.4s ease,
        filter 0.4s ease;
}


/* =========================================================
   ICON HOVER
========================================================= */

#solutions .solution-card:hover .solution-card-icon {
    transform:
        translateY(-4px) scale(1.07);

    border-color:
        rgba(56, 189, 248, 0.75);

    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.70),
        0 0 25px rgba(56, 189, 248, 0.22);
}

#solutions .solution-card:hover .solution-card-icon svg {
    transform: scale(1.10);

    filter:
        drop-shadow(0 0 10px rgba(56, 189, 248, 0.80));
}


/* =========================================================
   CARD CONTENT
========================================================= */

#solutions .solution-card-content {
    position: relative;

    z-index: 2;

    flex: 1;
}


/* =========================================================
   CARD TITLE
========================================================= */

#solutions .solution-card-title {
    margin: 0 0 14px;

    color: #12344a;

    font-size: 20px;
    font-weight: 750;

    line-height: 1.35;

    text-align: left;
}


/* =========================================================
   CARD TEXT
========================================================= */

#solutions .solution-card-text {
    margin: 0 0 14px;

    color: #647b8c;

    font-size: 14px;

    line-height: 1.8;

    text-align: left;
}

#solutions .solution-card-text-secondary {
    margin-bottom: 0;
}


/* =========================================================
   LEARN MORE
========================================================= */

#solutions .solution-card-link {
    position: relative;

    z-index: 3;

    align-self: flex-start;

    display: inline-flex;

    align-items: center;

    gap: 8px;

    margin-top: 22px;

    color: #159ee5;

    font-size: 13px;
    font-weight: 700;

    text-decoration: none;

    transition:
        color 0.3s ease,
        gap 0.3s ease;
}


/* =========================================================
   LINK UNDERLINE
========================================================= */

#solutions .solution-card-link::after {
    content: "";

    position: absolute;

    left: 0;
    bottom: -5px;

    width: 0;
    height: 1px;

    background: #159ee5;

    box-shadow:
        0 0 7px rgba(56, 189, 248, 0.55);

    transition:
        width 0.3s ease;
}

#solutions .solution-card:hover .solution-card-link {
    color: #087fbd;
    gap: 12px;
}

#solutions .solution-card:hover .solution-card-link::after {
    width: 100%;
}


/* =========================================================
   ARROW
========================================================= */

#solutions .solution-card-arrow {
    transition:
        transform 0.3s ease;
}

#solutions .solution-card:hover .solution-card-arrow {
    transform: translateX(3px);
}


/* =========================================================
   BOTTOM DIVIDER
========================================================= */

#solutions .solutions-divider {
    position: relative;

    width: 100%;
    height: 1px;

    margin-top: 58px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(56, 189, 248, 0.30),
            rgba(56, 189, 248, 0.70),
            rgba(56, 189, 248, 0.30),
            transparent);
}

#solutions .solutions-divider span {
    position: absolute;

    top: -1px;
    left: 50%;

    width: 90px;
    height: 3px;

    transform: translateX(-50%);

    border-radius: 10px;

    background: #38bdf8;

    box-shadow:
        0 0 10px rgba(56, 189, 248, 0.65),
        0 0 22px rgba(56, 189, 248, 0.25);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] #solutions .solutions-header {
    padding-left: 0;
    padding-right: 30px;
}

html[dir="rtl"] #solutions .solutions-header-border {
    left: auto;
    right: 0;
}

html[dir="rtl"] #solutions .solutions-header-border span {
    left: auto;
    right: 0;
}

html[dir="rtl"] #solutions .solutions-title {
    text-align: right;
}

html[dir="rtl"] #solutions .solutions-description p {
    text-align: right;
}

html[dir="rtl"] #solutions .solution-card {
    text-align: right;
}

html[dir="rtl"] #solutions .solution-card-title,
html[dir="rtl"] #solutions .solution-card-text {
    text-align: right;
}

html[dir="rtl"] #solutions .solution-card-link {
    align-self: flex-end;
    flex-direction: row-reverse;
}

html[dir="rtl"] #solutions .solution-card-link::after {
    left: auto;
    right: 0;
}

html[dir="rtl"] #solutions .solution-card:hover .solution-card-arrow {
    transform: translateX(-3px);
}





/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    #solutions::before,
    #solutions .solutions-header-border span,
    #solutions .solutions-title {
        animation: none !important;
    }

    #solutions .solution-card,
    #solutions .solution-card-icon,
    #solutions .solution-card-icon svg,
    #solutions .solution-card-link,
    #solutions .solution-card::after {
        transition: none !important;
    }
}


