    /* =====================================================
        TECHNOLOGY CARD
===================================================== */

    .technology-card {

        position: relative;

        width: 100%;

        min-height: 180px;

        display: flex;

        flex-direction: column;

        align-items: flex-start;

        justify-content: center;

        gap: 13px;

