            RIGHT VISUAL
===================================================== */

    .technology-visual {

        position: relative;

        width: 100%;

        display: flex;

        flex-direction: column;

        align-items: center;

        margin: 0 auto;

        z-index: 2;

    }


    /* =====================================================
            IMAGE WRAPPER
===================================================== */

    .technology-image-wrapper {

        position: relative;

        width: min(80%, 595px);

        aspect-ratio: 1 / 1;

        height: auto;

        overflow: hidden;

        border-radius: 20px;

        background: #020b14;

        border:

            1px solid rgba(7, 45, 70, .35);

        box-shadow:

            0 20px 42px rgba(8, 38, 60, .16);

        isolation: isolate;

    }


    /* =====================================================
            IMAGE
===================================================== */

    .technology-image {

        position: absolute;

        inset: 0;

        width: 100%;

        height: 100%;

        object-fit: cover;

        object-position: center center;



        transform: translate3d(0, 0, 0);

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;

    }


    /* =====================================================
            IMAGE OVERLAY
===================================================== */

    .technology-image-overlay {

        position: absolute;

        inset: 0;

        z-index: 2;

        pointer-events: none;

        background:

            linear-gradient(180deg,
                rgba(2, 15, 28, .04),
                transparent 45%,
                rgba(1, 10, 20, .24));

    }


    /* =====================================================
        HOLOGRAM BASE
===================================================== */

    .technology-hologram {

        position: absolute;

        left: 37% !important;

        top: 50%;

        width: 300px;

        height: 300px;


        transform:
            translate3d(-50%, -50%, 0);

        transform-origin: center center;

        z-index: 5;

        perspective: 800px;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;

        will-change: transform;

        contain: layout paint;

    }


    /* =====================================================
            CORE
===================================================== */

    .holo-core {

        left: 50%;

        top: 72%;

        width: 58px;

        height: 58px;

    }


    .holo-core-center {

        width: 9px;

        height: 9px;

    }


    /* =====================================================
            CONTACT GLOW
===================================================== */

    .technology-hologram::before {

        left: 50%;

        top: 72%;

        width: 105px;

        height: 58px;

        filter: blur(8px);

    }


    /* =====================================================
            HOLO ELEMENT
===================================================== */

    .holo-element {

        width: 70px;

        height: 38px;

        padding: 0 7px;

        border-radius: 7px;

        transform-origin: center center;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;

        transform-style: preserve-3d;

    }


    /* =====================================================
            HOLO ICON
===================================================== */

    .holo-icon {

        width: 20px;

        height: 20px;

    }


    /* =====================================================
        HOLOGRAM POSITIONS
===================================================== */

    .holo-1 {

        left: 50%;

        top: 72%;

        width: 78px;

        height: 40px;

        --x: -105px;

        --y: -110px;

    }


    .holo-2 {

        left: 50%;

        top: 72%;

        width: 74px;

        height: 39px;

        --x: 88px;

        --y: -120px;

    }


    .holo-3 {

        left: 50%;

        top: 72%;

        width: 80px;

        height: 42px;

        --x: -115px;

        --y: -46px;

    }


    .holo-4 {

        left: 50%;

        top: 72%;

        width: 72px;

        height: 39px;

        --x: 110px;

        --y: -50px;

    }


    .holo-5 {

        left: 50%;

        top: 72%;

        width: 76px;

        height: 40px;

        --x: -78px;

        --y: -155px;

    }


    .holo-6 {

        left: 50%;

        top: 72%;

        width: 74px;

        height: 39px;

        --x: 73px;

        --y: -170px;

    }


