    /* =========================================================
   IMAGE WRAPPER
   STABLE GPU LAYER
   ========================================================= */

    .infrastructure-image-wrapper {
        position: relative;


        width: 100%;

        max-width: 690px;

        height: 350px;

        margin: 0 auto;

        overflow: hidden;

        border-radius: 18px;

        background: #020b14;

        border:
            1px solid rgba(56, 189, 248, .22);

        box-shadow:
            0 20px 45px rgba(0, 0, 0, .38),
            0 0 30px rgba(21, 158, 229, .10);

        isolation: isolate;


        transform: translateZ(0);

        -webkit-transform: translateZ(0);


        transform-style: flat;

        -webkit-transform-style: flat;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;

        contain: paint;
    }


    /* =========================================================
   IMAGE
   COMPLETELY STATIC
   ========================================================= */

    .infrastructure-image {
        position: absolute;

        inset: 0;

        width: 100%;
        height: 100%;

        object-fit: cover;

        object-position: center;


        transform: translateZ(0) !important;

        -webkit-transform: translateZ(0) !important;

        animation: none !important;

        transition:
            filter .5s ease;

        transform-style: flat;

        -webkit-transform-style: flat;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;

        will-change: auto;

        contain: paint;
    }


    /* =========================================================
   IMAGE HOVER
   ========================================================= */

    .infrastructure-image-wrapper:hover .infrastructure-image {
        transform: translateZ(0) !important;

        filter:
            brightness(1.05) saturate(1.05);
    }


    /* =========================================================
   IMAGE OVERLAY
   STATIC
   ========================================================= */

    .infrastructure-image-overlay {
        position: absolute;

        inset: 0;

        z-index: 2;

        pointer-events: none;

        background:
            linear-gradient(180deg,
                rgba(1, 12, 22, .05),
                transparent 45%,
                rgba(1, 12, 22, .38));

        transform: translateZ(0);

        -webkit-transform: translateZ(0);

        transform-style: flat;

        -webkit-transform-style: flat;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
   LIGHT SWEEP
   IMAGE NEVER MOVES
   ONLY THE SWEEP MOVES
   ========================================================= */

    .infrastructure-image-wrapper::after {
        content: "";

        position: absolute;

        top: -20%;

        left: -18%;

        width: 22%;

        height: 140%;

        z-index: 3;

        pointer-events: none;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(125, 211, 252, .12),
                rgba(255, 255, 255, .28),
                transparent);


        transform:
            translate3d(-180%, 0, 0) skewX(-18deg);

        -webkit-transform:
            translate3d(-180%, 0, 0) skewX(-18deg);

        filter: blur(5px);

        opacity: 0;

        will-change:
            transform,
            opacity;

        animation:
            infrastructureTabletLightSweep 8s ease-in-out infinite;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
   LIGHT SWEEP ANIMATION
   ========================================================= */

    @keyframes infrastructureTabletLightSweep {

        0% {
            transform:
                translate3d(-180%, 0, 0) skewX(-18deg);

            -webkit-transform:
                translate3d(-180%, 0, 0) skewX(-18deg);

            opacity: 0;
        }

        15% {
            opacity: .65;
        }

        50% {
            opacity: .28;
        }

        75% {
            opacity: .08;
        }

        100% {
            transform:
                translate3d(620%, 0, 0) skewX(-18deg);

            -webkit-transform:
                translate3d(620%, 0, 0) skewX(-18deg);

            opacity: 0;
        }
    }


    /* =========================================================
   HOLOGRAM
   ========================================================= */

    .infrastructure-hologram {
        position: absolute;

        left: 50%;

        top: 50%;

        width: 300px;

        height: 250px;

        transform:
            translate3d(-50%, -50%, 0) scale(.68);

        -webkit-transform:
            translate3d(-50%, -50%, 0) scale(.68);

        transform-origin: center center;

        z-index: 6;

        pointer-events: none;

        transform-style: flat;

        -webkit-transform-style: flat;

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;

        will-change: transform;
    }


