    .web-design-title-accent {

        width: 75px;

        height: 3px;

        margin-top: 18px;

        margin-bottom: 22px;

        border-radius: 999px;

        background:

            linear-gradient(90deg,
                #159ee5,
                rgba(56, 189, 248, .08));

    }





    html[dir="rtl"] .web-design-title-accent {

        margin-left: auto;

        margin-right: 0;

    }





    /* =========================================================
                    DESCRIPTION
========================================================= */


    .web-design-description {

        width: 100%;

        max-width: 680px;

        margin: 0;

        color: #a9bdca;

        font-size: var(--font-size-xl);

        line-height: 1.85;

        font-weight: 400;

    }





    .web-design-description p {

        margin: 22px auto;

    }





    .web-design-description p+p {

        margin-top: 18px;

    }





    html[dir="rtl"] .web-design-description {

        text-align: right;

    }

    /* =========================================================
   WEB DESIGN SECTION
   TABLET 768px STYLE
   PART 2

   CARDS
   GRID 2x2
   ICON
   CONTENT
   RTL / LTR
========================================================= */



    /* =========================================================
                    CARDS GRID
========================================================= */


    .web-design-cards {

        width: 100%;
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 76px;
        margin-top: 10px;
        align-items: stretch;
        margin-left: -25px;

    }

    html[dir="rtl"] .web-design-cards {

        width: 100%;
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 76px;
        margin-top: 10px;
        align-items: stretch;
        margin-right: -25px;

    }





    /* =========================================================
                    CARD
========================================================= */


    .web-design-card {

        position: relative;

        width: 351px;

        min-height: 155px;

        display: flex;

        flex-direction: row;

        align-items: flex-start;

        gap: 16px;

        padding: 22px 20px;

        overflow: hidden;

        border-radius: 20px;


        background: linear-gradient(145deg, #ffffff 0%, #f8fbfe 100%);


        border:
            1px solid rgba(56, 189, 248, .16);


        box-shadow:
            0 18px 38px rgba(0, 0, 0, .25),
            inset 0 1px 0 rgba(255, 255, 255, .05);


        backdrop-filter: blur(12px);
        -webkit-backdrop-filter: blur(12px);

    }





    /* =========================================================
                    CARD GLOW LINE
========================================================= */


    .web-design-card::before {


        content: "";


        position: absolute;


        left: 0;


        top: 0;


        width: 3px;


        height: 100%;



        background:

            linear-gradient(to bottom,
                transparent,
                #159ee5,
                transparent);



        opacity: .8;


    }





    /* =========================================================
                    CARD ICON
========================================================= */


    .web-design-card-icon {


        flex: 0 0 auto;


        width: 58px;


        height: 58px;



        display: flex;


        align-items: center;


        justify-content: center;



        border-radius: 15px;



        background:

            linear-gradient(145deg,
                #06243a,
                #0a3854);



        border:

            1px solid rgba(56, 189, 248, .35);



        color: #55c9f7;



        box-shadow:

            0 10px 25px rgba(0, 0, 0, .25),

            inset 0 0 15px rgba(56, 189, 248, .15);



        transition:

            transform .35s ease,

            box-shadow .35s ease;


    }





    .web-design-card-icon svg {


        width: 30px;


        height: 30px;


    }






    /* =========================================================
                    CARD INFO
========================================================= */


    .web-design-card-info {


        flex: 1;


        min-width: 0;


    }





    .web-design-card-info h3 {


        margin: 0 0 9px;


        color: #152d47;


        font-size: 18px;


        line-height: 1.35;


        font-weight: 750;


    }





    .web-design-card-info p {


        margin: 0;


        color: #9eb5c3;


        font-size: 15.5px;


        line-height: 1.7;


    }





    /* =========================================================
                    CARD HOVER
========================================================= */


    .web-design-card:hover {


        transform:

            translate3d(0, -6px, 0);



        border-color:

            rgba(56, 189, 248, .45);



        box-shadow:


            0 22px 45px rgba(0, 0, 0, .30),


            0 0 28px rgba(56, 189, 248, .12);



    }





    .web-design-card:hover .web-design-card-icon {


        transform:

            translate3d(0, -3px, 0) scale(1.05);



        box-shadow:


            0 14px 30px rgba(0, 0, 0, .28),


            0 0 18px rgba(56, 189, 248, .18),


            inset 0 0 15px rgba(56, 189, 248, .16);



    }





    /* =========================================================
                    RTL CARD
========================================================= */


    html[dir="rtl"] .web-design-card {


        direction: rtl;


        flex-direction: row-reverse;


        text-align: right;


    }





    html[dir="rtl"] .web-design-card::before {


        left: auto;


        right: 0;


    }





    html[dir="rtl"] .web-design-card-info {


        text-align: right;


    }





    /* =========================================================
                    LTR CARD
========================================================= */


    html[dir="ltr"] .web-design-card {


        direction: ltr;


        flex-direction: row;


        text-align: left;


    }





    /* =========================================================
                    RTL GRID STABILITY
========================================================= */


    html[dir="rtl"] .web-design-cards {


        direction: rtl;


    }





    /* =========================================================
                    CARD TOUCH SAFETY
========================================================= */


    .web-design-card,

    .web-design-card-icon {


        -webkit-tap-highlight-color: transparent;


    }


    /* =========================================================
   WEB DESIGN SECTION
   TABLET 768px STYLE
   PART 3

   IMAGE
   ANIMATION FIX
   CTA
   DIVIDER
   RTL GPU STABILITY
========================================================= */



    /* =========================================================
                    IMAGE AREA
========================================================= */


    .web-design-visual {

        width: 100%;

        display: flex;

        justify-content: center;

        align-items: center;

    }





    /* =========================================================
                    IMAGE WRAPPER
                    GPU STABLE
========================================================= */


    .web-design-image-wrapper {


        position: relative;


        width: 93%;


        max-width: 540px;


        aspect-ratio: 1 / 1;


        overflow: hidden;


        border-radius: 24px;



        background: #020b14;



        border:

            1px solid rgba(56, 189, 248, .22);



        box-shadow:


            0 25px 55px rgba(0, 0, 0, .38),


            0 0 35px rgba(21, 158, 229, .12);



        isolation: isolate;


        contain: paint;



        transform:

            translate3d(0, 0, 0);



        transform-style: preserve-3d;


        -webkit-transform-style: preserve-3d;



        backface-visibility: hidden;


        -webkit-backface-visibility: hidden;


    }





    /* =========================================================
                    IMAGE
                    NEVER ANIMATE
========================================================= */


    .web-design-image {


        position: absolute;


        inset: 0;



        width: 100%;


        height: 100%;



        object-fit: cover;


        object-position: center;



        transform:

            translate3d(0, 0, 0) !important;



        animation: none !important;



        backface-visibility: hidden;


        -webkit-backface-visibility: hidden;



        will-change: auto;



    }





    /* =========================================================
                    IMAGE OVERLAY
========================================================= */


    .web-design-image-overlay {


        position: absolute;


        inset: 0;


        z-index: 2;


        pointer-events: none;



        background:


            linear-gradient(180deg,

                rgba(1, 12, 22, .05),

                transparent 45%,

                rgba(1, 12, 22, .35));



    }





    /* =========================================================
            LIGHT SWEEP
            MOVE ONLY OVERLAY
========================================================= */


    .web-design-image-wrapper::after {


        content: "";


        position: absolute;


        top: -20%;


        left: -20%;



        width: 25%;


        height: 140%;



        z-index: 3;



        pointer-events: none;



        background:


            linear-gradient(90deg,

                transparent,

                rgba(125, 211, 252, .12),

                rgba(255, 255, 255, .28),

                transparent);



        transform:


            translate3d(-180%, 0, 0) skewX(-18deg);



        filter: blur(5px);



        opacity: 0;



        animation:

            webDesignTabletSweep 8s ease-in-out infinite;



        will-change: transform, opacity;


    }





    @keyframes webDesignTabletSweep {


        0% {


            transform:


                translate3d(-180%, 0, 0) skewX(-18deg);



            opacity: 0;


        }



        20% {


            opacity: .7;


        }



        55% {


            opacity: .25;


        }



        100% {


            transform:


                translate3d(620%, 0, 0) skewX(-18deg);



            opacity: 0;


        }


    }





    /* =========================================================
                    CTA WRAPPER
========================================================= */


    .web-design-cta-wrapper {


        width: 100%;


        display: flex;


        justify-content: flex-start;


        margin-top: 10px;


    }





    html[dir="rtl"] .web-design-cta-wrapper {


        justify-content: flex-end;


    }





    /* =========================================================
                    CTA BUTTON
========================================================= */


    .web-design-cta {
        position: relative;
        width: 361px;
        min-height: 54px;
        display: flex;
        align-items: center;
        justify-content: center;
        overflow: hidden;
        padding: 14px 26px;
        color: #7dd3fc;
        border: 1px solid #159ee5;
        border-radius: 12px;
        background: transparent;
        font-size: 18px;
        font-weight: 700;
        text-decoration: none;
        white-space: nowrap;
        box-shadow: 0 10px 28px rgba(21, 158, 229, .14);
        transition: transform .35s ease, color .35s ease, box-shadow .35s ease;
        margin-top: 54px;
        margin-left: -13px;
    }





    .web-design-cta::after {


        content: "";


        position: absolute;


        inset: 0;


        z-index: -1;



        background:


            linear-gradient(100deg,

                #087ec5,

                #159ee5,

                #38bdf8);



        transform:

            scaleX(0);



        transform-origin: left center;



        transition:

            transform .45s ease;



    }





    html[dir="rtl"] .web-design-cta::after {


        transform-origin: right center;


    }





    .web-design-cta:hover {


        color: #fff;



        transform:

            translate3d(0, -3px, 0);



        box-shadow:


            0 15px 35px rgba(21, 158, 229, .22);



    }





    .web-design-cta:hover::after {


        transform:

            scaleX(1);


    }





    /* =========================================================
                    DIVIDER
========================================================= */


    .web-design-divider {


        position: relative;


        width: 88%;


        height: 2px;



        margin: 55px auto 0;



        background:


            linear-gradient(90deg,

                transparent,

                rgba(21, 158, 229, .55),

                transparent);



    }





    .web-design-divider span {


        position: absolute;


        top: 50%;


        left: 15%;



        width: 80px;


        height: 6px;



        transform:


            translate3d(-50%, -50%, 0);



        border-radius: 999px;



        background: #38bdf8;



        filter: blur(1px);



        box-shadow:


            0 0 18px rgba(56, 189, 248, .75);



        animation:

            webDesignDividerMove 4s ease-in-out infinite;



    }





    @keyframes webDesignDividerMove {


        0% {


            transform:


                translate3d(-50%, -50%, 0);


            opacity: 0;


        }



        25% {


            opacity: 1;


        }



        100% {


            transform:


                translate3d(620%, -50%, 0);


            opacity: 0;


        }


    }





    /* =========================================================
                    RTL IMAGE FINAL FIX
========================================================= */


    html[dir="rtl"] .web-design-image-wrapper {


        direction: ltr;


        transform:

            translate3d(0, 0, 0) !important;



        isolation: isolate;


    }





    html[dir="rtl"] .web-design-image {


        direction: ltr;


        transform:

            translate3d(0, 0, 0) !important;



        animation: none !important;



    }





    /* =========================================================
                    GPU COMPOSITING
========================================================= */


    .web-design-image-wrapper,

    .web-design-image,

    .web-design-image-overlay,

    .web-design-image-wrapper::after {


        backface-visibility: hidden;


        -webkit-backface-visibility: hidden;



        transform-style: preserve-3d;


        -webkit-transform-style: preserve-3d;


    }





    /* =========================================================
                    TOUCH SAFE
========================================================= */


    .web-design-image-wrapper,

    .web-design-image {


        -webkit-tap-highlight-color: transparent;


    }


    /* =========================================================
   SOFTWARE DEVELOPMENT
   TABLET 768px
   ========================================================= */


    /* =========================================================
   SECTION
   ========================================================= */

    .software-development-section {
        width: 100%;
        padding: 70px 0 55px;
        overflow: hidden;
    }


    /* =========================================================
   CONTAINER
   ========================================================= */

    .software-development-container {
        width: 100%;
        max-width: 720px;
        margin: 0 auto;
        padding: 0 20px;
    }


    /* =========================================================
   HEADER
   ========================================================= */

    .software-development-header {
        width: 100%;
        max-width: 100%;
        margin-bottom: 32px;
        text-align: left;
    }


    /* =========================================================
   EYEBROW
   ========================================================= */

    .software-development-eyebrow {
        display: flex;
        align-items: center;
        gap: 10px;

        margin-bottom: 14px;

        font-size: var(--font-size-base);

        line-height: 1.4;
        letter-spacing: 0.09em;
        font-weight: 700;
    }


    /* =========================================================
   EYEBROW LINE
   ========================================================= */

    .software-development-eyebrow-line {
        width: 34px;
        height: 2px;
        flex: 0 0 34px;
        border-radius: 50px;
    }


    /* =========================================================
   TITLE
   ========================================================= */

    .software-development-title {
        margin: 0;

        font-size: var(--font-size-4xl);

        line-height: 1.2;
        font-weight: 800;
        letter-spacing: -0.025em;
    }


    /* =========================================================
   TITLE ACCENT
   ========================================================= */

    .software-development-title-accent {
        width: 65px;
        height: 3px;

        margin-top: 15px;
        margin-bottom: 18px;

        border-radius: 999px;
    }


    /* =========================================================
   DESCRIPTION
   ========================================================= */

    .software-development-description {
        width: 100%;
        max-width: 100%;

        margin: 0;

        font-size: var(--font-size-xl);

        line-height: 1.75;
    }


    /* =========================================================
   VISUAL
   ========================================================= */

    .software-development-visual {
        position: relative;

        width: 100%;

        margin: 0 auto 32px;

        direction: ltr;
        unicode-bidi: isolate;

        overflow: visible;
    }


    /* =========================================================
   IMAGE WRAPPER
   LARGER TABLET SIZE
   ========================================================= */

    .software-development-image-wrapper {
        position: relative;

        width: 100%;

        height: 310px;

        margin: 0 auto;

        overflow: hidden;

        border-radius: 17px;

        background: #020b14;

        border: 1px solid rgba(56, 189, 248, 0.20);

        box-shadow:
            0 18px 40px rgba(0, 0, 0, 0.35),
            0 0 25px rgba(21, 158, 229, 0.08);

        isolation: isolate;

        /*
     * IMAGE WRAPPER NEVER MOVES
     */
        transform:
            translate3d(0, 0, 0) !important;

        transform-origin:
            center center;

        transform-style: flat;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        contain:
            layout paint style;

        direction: ltr;
        unicode-bidi: isolate;
    }


    /* =========================================================
   IMAGE
   COMPLETELY STATIC
   ========================================================= */

    .software-development-image {
        position: absolute;

        inset: 0;

        width: 100%;
        height: 100%;

        display: block;

        object-fit: cover;
        object-position: center;

        /*
     * CRITICAL:
     * IMAGE HAS ZERO MOVEMENT
     */
        transform:
            translate3d(0, 0, 0) !important;

        transform-origin:
            center center;

        animation: none !important;
        transition: none !important;

        will-change: auto;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        transform-style: flat;

        direction: ltr;
        unicode-bidi: isolate;
    }


    /* =========================================================
   IMAGE HOVER
   NO MOVEMENT
   ========================================================= */

    .software-development-image-wrapper:hover .software-development-image {

        transform:
            translate3d(0, 0, 0) !important;

        filter:
            brightness(1.05) saturate(1.05);
    }


    /* =========================================================
   IMAGE OVERLAY
   STATIC
   ========================================================= */

    .software-development-image-overlay {
        position: absolute;

        inset: 0;

        z-index: 2;

        pointer-events: none;

        background:
            linear-gradient(180deg,
                rgba(1, 12, 22, 0.08),
                transparent 45%,
                rgba(1, 12, 22, 0.35));

        transform:
            translate3d(0, 0, 0) !important;

        animation: none !important;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        direction: ltr;
        unicode-bidi: isolate;
    }


    /* =========================================================
   HOLOGRAM
   ========================================================= */

    .software-hologram {
        position: absolute;

        left: 61%;
        right: auto;
        top: 36%;

        width: 260px;
        height: 220px;

        /*
     * ONLY THE HOLOGRAM MOVES
     */
        transform:
            translate3d(-50%, -50%, 0) scale(0.72);

        transform-origin:
            center center;

        z-index: 6;

        pointer-events: none;

        overflow: visible;

        direction: ltr !important;
        unicode-bidi: isolate;

        writing-mode: horizontal-tb;

        isolation: isolate;

        contain:
            layout paint style;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        transform-style: preserve-3d;

        will-change: transform;
    }


    /* =========================================================
   RTL HOLOGRAM
   FORCE LTR COORDINATE SYSTEM
   ========================================================= */

    html[dir="rtl"] .software-hologram {

        left: 61%;
        right: auto;
        top: 36%;

        direction: ltr !important;
        unicode-bidi: isolate;

        writing-mode: horizontal-tb;

        transform:
            translate3d(-50%, -50%, 0) scale(0.72) !important;

        transform-origin:
            center center !important;

        isolation: isolate;

        contain:
            layout paint style;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        transform-style: preserve-3d;

        will-change: transform;
    }


    /* =========================================================
   HOLOGRAM CHILDREN
   FORCE LTR
   ========================================================= */

    .software-hologram .software-orb,
    .software-hologram .hologram-line,
    .software-hologram .hologram-particle,
    .software-hologram .software-origin {

        direction: ltr !important;

        unicode-bidi: isolate;

        writing-mode: horizontal-tb;
    }


    /* =========================================================
   ORBS
   ========================================================= */

    .software-orb {
        width: 68px;
        height: 68px;
    }


    /* =========================================================
   ORB ICON
   ========================================================= */

    .orb-icon {
        width: 38px;
        height: 38px;
    }


    .orb-icon svg {
        width: 29px;
        height: 29px;
    }


    /* =========================================================
   ORB POSITIONS
   ========================================================= */

    .orb-1 {
        left: calc(50% - 34px);
        top: calc(50% - 112px);

        animation:
            softwareOrbTop 7s ease-in-out infinite;
    }


    .orb-2 {
        left: calc(50% - 118px);
        top: calc(50% - 62px);

        animation:
            softwareOrbTopLeft 7s ease-in-out infinite 0.55s;
    }


    .orb-3 {
        left: calc(50% + 55px);
        top: calc(50% - 66px);

        animation:
            softwareOrbTopRight 7s ease-in-out infinite 1.10s;
    }


    .orb-4 {
        left: calc(50% - 138px);
        top: calc(50% - 4px);

        animation:
            softwareOrbLeft 7s ease-in-out infinite 1.65s;
    }


    .orb-5 {
        left: calc(50% - 102px);
        top: calc(50% + 58px);

        animation:
            softwareOrbBottomLeft 7s ease-in-out infinite 2.20s;
    }


    .orb-6 {
        left: calc(50% + 68px);
        top: calc(50% + 10px);

        animation:
            softwareOrbRight 7s ease-in-out infinite 2.75s;
    }


    /* =========================================================
   HOLOGRAM LINES
   ========================================================= */

    .hologram-line {
        left: 50%;
        top: 50%;

        transform-origin:
            left center !important;
    }


    .line-1 {
        width: 115px;

        transform:
            rotate(-90deg) scaleX(0);
    }


    .line-2 {
        width: 120px;

        transform:
            rotate(-143deg) scaleX(0);
    }


    .line-3 {
        width: 110px;

        transform:
            rotate(-43deg) scaleX(0);
    }


    .line-4 {
        width: 135px;

        transform:
            rotate(178deg) scaleX(0);
    }


    .line-5 {
        width: 115px;

        transform:
            rotate(145deg) scaleX(0);
    }


    .line-6 {
        width: 115px;

        transform:
            rotate(-5deg) scaleX(0);
    }


    /* =========================================================
   ORIGIN
   ========================================================= */

    .software-origin {

        left: 50% !important;
        right: auto !important;

        top: 50% !important;

        width: 20px;
        height: 20px;

        transform:
            translate3d(-50%, -50%, 0) !important;
    }


    /* =========================================================
   ORIGIN CORE
   ========================================================= */

    .origin-core {

        width: 8px;
        height: 8px;

        transform:
            translate3d(-50%, -50%, 0);
    }


    /* =========================================================
   ORIGIN FLASH
   ========================================================= */

    .origin-flash {

        width: 5px;
        height: 5px;

        transform:
            translate3d(-50%, -50%, 0);
    }


    /* =========================================================
   ORIGIN RINGS
   ========================================================= */

    .origin-ring-1 {
        width: 25px;
        height: 25px;
    }


    .origin-ring-2 {
        width: 48px;
        height: 48px;
    }


    .origin-ring-3 {
        width: 76px;
        height: 76px;
    }


    /* =========================================================
   PARTICLES
   ========================================================= */

    .hologram-particle {
        width: 2px;
        height: 2px;
    }


    /* =========================================================
   LIGHT SWEEP
   IMAGE OVERLAY ONLY
   ========================================================= */

    .software-development-image-wrapper::after {

        content: "";

        position: absolute;

        top: -20%;
        left: -25%;
        right: auto;

        width: 25%;
        height: 140%;

        z-index: 3;

        pointer-events: none;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(125, 211, 252, 0.15),
                rgba(255, 255, 255, 0.25),
                transparent);

        transform:
            translate3d(-120%, 0, 0) skewX(-18deg);

        filter: blur(5px);

        animation:
            softwareMobileLightSweep 8s ease-in-out infinite;

        will-change:
            transform,
            opacity;

        direction: ltr;
        unicode-bidi: isolate;
    }


    /* =========================================================
   CARDS
   2 COLUMNS
   ========================================================= */

    .software-development-cards {

        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 33px;
        margin-top: 25px;
        margin-bottom: 32px;
        margin-left: -28px;
    }


    /* =========================================================
   CARD
   SQUARE / COMPACT
   ========================================================= */

    .software-development-card {

        position: relative;

        width: 348px;

        min-height: 175px;

        margin: 0;

        display: flex;

        flex-direction: row;

        align-items: center;

        justify-content: flex-start;

        gap: 13px;

        padding: 17px 14px;

        overflow: hidden;

        border-radius: 16px;

        border:
            1px solid rgba(56, 189, 248, 0.18);

        background:
            linear-gradient(145deg,
                rgba(255, 255, 255, 0.075),
                rgba(255, 255, 255, 0.025));

        box-shadow:
            0 12px 28px rgba(0, 0, 0, 0.18),
            inset 0 1px 0 rgba(255, 255, 255, 0.05);

        backdrop-filter: blur(7px);

        -webkit-tap-highlight-color: transparent;

        transition:
            transform 0.35s ease,
            border-color 0.35s ease;
    }


    /* =========================================================
   CARD ICON
   ENGLISH = LEFT
   ========================================================= */

    .software-development-card-icon {

        flex:
            0 0 48px;

        width: 48px;
        height: 48px;

        display: flex;

        align-items: center;
        justify-content: center;

        border-radius: 12px;

        margin: 0;

        order: 1;
    }


    /* =========================================================
   CARD SVG
   ========================================================= */

    .software-development-card-icon svg {

        width: 25px;
        height: 25px;
    }


    /* =========================================================
   CARD INFO
   ENGLISH = RIGHT OF ICON
   ========================================================= */

    .software-development-card-info {

        width: auto;

        flex: 1;

        min-width: 0;

        display: flex;

        flex-direction: column;

        align-items: flex-start;

        justify-content: center;

        text-align: left;

        order: 2;
    }


    /* =========================================================
   CARD TITLE
   ========================================================= */

    .software-development-card-info h3 {

        width: 100%;

        margin: 0 0 7px;

        font-size: 20px;

        line-height: 1.35;

        font-weight: 700;

        text-align: left;
    }


    /* =========================================================
   CARD DESCRIPTION
   ========================================================= */

    .software-development-card-info p {

        width: 100%;

        margin: 0;

        font-size: 17px;

        line-height: 1.55;

        text-align: left;

        overflow-wrap: break-word;

        word-break: normal;
    }


    /* =========================================================
   CARD HOVER
   ========================================================= */

    .software-development-card:hover {

        transform:
            translateY(-3px);
    }


    /* =========================================================
   RTL CARD
   ICON = RIGHT
   CONTENT = LEFT
   ========================================================= */

    html[dir="rtl"] .software-development-card {

        direction: rtl;

        flex-direction: row;

        justify-content: flex-start;
    }


    /* =========================================================
   RTL ICON
   ========================================================= */

    html[dir="rtl"] .software-development-card .software-development-card-icon {

        order: 2;

        margin: 0;
    }


    /* =========================================================
   RTL INFO
   ========================================================= */

    html[dir="rtl"] .software-development-card .software-development-card-info {

        order: 1;

        align-items: flex-end;

        text-align: right;
    }


    /* =========================================================
   RTL TITLE
   ========================================================= */

    html[dir="rtl"] .software-development-card-info h3 {

        direction: rtl;

        text-align: right;
    }


    /* =========================================================
   RTL DESCRIPTION
   ========================================================= */

    html[dir="rtl"] .software-development-card-info p {

        direction: rtl;

        text-align: right;
    }


    /* =========================================================
   CTA WRAPPER
   ========================================================= */

    .software-development-cta-wrapper {

        width: 100%;

        display: flex;

        justify-content: flex-start;

        margin-top: 0;
    }


    /* =========================================================
   CTA
   60% WIDTH
   ========================================================= */

    .software-development-cta {

        width: 60%;
        min-height: 50px;
        padding: 0 24px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 17px;
        font-weight: 700;
        line-height: 1.3;
        border-radius: 11px;
        -webkit-tap-highlight-color: transparent;
        margin-top: 23px;
    }

    html[dir="rtl"] .software-development-cta {

        width: 60%;
        min-height: 50px;
        padding: 0 24px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 17px;
        font-weight: 700;
        line-height: 1.3;
        border-radius: 11px;
        -webkit-tap-highlight-color: transparent;
        margin-top: 23px;
        margin-left: 282px;
    }


    /* =========================================================
   ENGLISH CTA
   LEFT
   ========================================================= */

    html[dir="ltr"] .software-development-cta-wrapper {

        justify-content: flex-start;

    }


    /* =========================================================
   ARABIC CTA
   RIGHT
   ========================================================= */

    html[dir="rtl"] .software-development-cta-wrapper {

        justify-content: flex-end;
    }


    /* =========================================================
   HEADER RTL
   ========================================================= */

    html[dir="rtl"] .software-development-header {

        text-align: right;
    }


    /* =========================================================
   EYEBROW RTL
   ========================================================= */

    html[dir="rtl"] .software-development-eyebrow {

        flex-direction: row-reverse;

        direction: rtl;

        justify-content: flex-start;
    }


    /* =========================================================
   TITLE ACCENT RTL
   ========================================================= */

    html[dir="rtl"] .software-development-title-accent {

        margin-left: auto;

        margin-right: 0;
    }


    /* =========================================================
   VISUAL RTL
   FORCE LTR
   ========================================================= */

    html[dir="rtl"] .software-development-visual {

        direction: ltr !important;

        unicode-bidi: isolate;
    }


    /* =========================================================
   IMAGE WRAPPER RTL
   ABSOLUTELY STABLE
   ========================================================= */

    html[dir="rtl"] .software-development-image-wrapper {

        direction: ltr !important;

        unicode-bidi: isolate;

        transform:
            translate3d(0, 0, 0) !important;

        transform-origin:
            center center !important;

        transform-style: flat;

        contain:
            layout paint style;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
   RTL IMAGE
   NEVER MOVE
   ========================================================= */

    html[dir="rtl"] .software-development-image-wrapper .software-development-image {

        direction: ltr !important;

        transform:
            translate3d(0, 0, 0) !important;

        transform-origin:
            center center !important;

        animation: none !important;

        transition: none !important;

        will-change: auto;

        transform-style: flat;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
   RTL IMAGE OVERLAY
   ========================================================= */

    html[dir="rtl"] .software-development-image-overlay {

        direction: ltr !important;

        unicode-bidi: isolate;

        transform:
            translate3d(0, 0, 0) !important;

        transform-origin:
            center center !important;

        animation: none !important;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
   RTL LIGHT SWEEP
   ========================================================= */

    html[dir="rtl"] .software-development-image-wrapper::after {

        direction: ltr !important;

        left: -25% !important;
        right: auto !important;

        transform-origin:
            center center;

        will-change:
            transform,
            opacity;
    }


    /* =========================================================
   RTL HOLOGRAM CHILDREN
   ========================================================= */

    html[dir="rtl"] .software-hologram .software-orb,

    html[dir="rtl"] .software-hologram .hologram-line,

    html[dir="rtl"] .software-hologram .hologram-particle,

    html[dir="rtl"] .software-hologram .software-origin {

        direction: ltr !important;

        unicode-bidi: isolate;

        writing-mode: horizontal-tb;
    }


    /* =========================================================
   RTL HOLOGRAM LINES
   ========================================================= */

    html[dir="rtl"] .software-hologram .hologram-line {

        direction: ltr !important;

        unicode-bidi: isolate;

        transform-origin:
            left center !important;
    }


    /* =========================================================
   RTL ORIGIN
   ========================================================= */

    html[dir="rtl"] .software-hologram .software-origin {

        left: 50% !important;

        right: auto !important;

        top: 50% !important;

        direction: ltr !important;

        unicode-bidi: isolate;
    }


    /* =========================================================
   FINAL IMAGE SHAKE PROTECTION
   LTR + RTL
   ========================================================= */

    .software-development-image-wrapper {

        animation: none !important;

        transform:
            translate3d(0, 0, 0) !important;
    }


    .software-development-image {

        animation: none !important;

        transform:
            translate3d(0, 0, 0) !important;

        transition: none !important;

        will-change: auto;
    }


    .software-development-image-overlay {

        animation: none !important;

        transform:
            translate3d(0, 0, 0) !important;
    }


    /* =========================================================
   GPU STABILITY
   ========================================================= */

    .software-development-image-wrapper,
    .software-development-image,
    .software-development-image-overlay {

        backface-visibility: hidden;

        -webkit-backface-visibility: hidden;
    }


/* =========================================================
   MICROSOFT CLOUD PLATFORM
   TABLET 768px STYLE
   TECHNOLOGY CLOUD SOLUTIONS DESIGN

   SAME DESIGN PHILOSOPHY AS
   WEB DESIGN & DEVELOPMENT — TABLET

   PART 1
   SECTION
   CONTAINER
   LAYOUT
   CONTENT
   TITLE
   DESCRIPTION
========================================================= */


/* =========================================================
                    SECTION
========================================================= */

.microsoft-cloud-section {

    width: 100%;

    padding: 75px 0 65px;

    overflow: hidden;

    color: #e7f7ff;

}


/* =========================================================
                    SECTION BACKGROUND
========================================================= */

.microsoft-cloud-section::before {

    top: 5%;

    right: -210px;

    width: 340px;

    height: 340px;

}

.microsoft-cloud-section::after {

    bottom: -210px;

    left: -210px;

    width: 340px;

    height: 340px;

}


/* =========================================================
                    CONTAINER
========================================================= */

.microsoft-cloud-container {

    position: relative;

    z-index: 2;

    width: 100%;

    max-width: 720px;

    margin: 0 auto;

    padding: 0 28px;

}


/* =========================================================
                    MAIN LAYOUT

        SAME PHILOSOPHY AS WEB DESIGN
        CONTENT FIRST
        VISUAL SECOND
========================================================= */

.microsoft-cloud-layout {

    display: flex;

    flex-direction: column;

    align-items: center;

    gap: 42px;

}


/* =========================================================
                    CONTENT
========================================================= */

.microsoft-cloud-content {

    width: 100%;

    max-width: none;

    min-width: 0;

    text-align: left;

}

html[dir="rtl"] .microsoft-cloud-content {

    text-align: right;

}


/* =========================================================
                    EYEBROW
========================================================= */

.microsoft-cloud-eyebrow {

    display: flex;

    align-items: center;

    justify-content: flex-start;

    gap: 12px;

    margin-bottom: 16px;

    color: #55c9f7;

    font-size: var(--font-size-base);

    font-weight: 700;

    letter-spacing: .08em;

    text-transform: uppercase;

}

.microsoft-cloud-eyebrow-line {

    width: 38px;

    height: 2px;

    flex: 0 0 38px;

    border-radius: 50px;

    background:

        linear-gradient(90deg,
            #159ee5,
            #7dd3fc);

}

html[dir="rtl"] .microsoft-cloud-eyebrow {

    flex-direction: row-reverse;

}


/* =========================================================
                    TITLE
========================================================= */

.microsoft-cloud-title {

    margin: 0;

    color: #10243b;

    font-size: var(--font-size-4xl);

    line-height: 1.18;

    font-weight: 800;

    letter-spacing: -.03em;

}


/* =========================================================
                    TITLE ACCENT
========================================================= */

.microsoft-cloud-title-accent {

    width: 75px;

    height: 3px;

    margin-top: 18px;

    margin-bottom: 22px;

    border-radius: 999px;

    background:

        linear-gradient(90deg,
            #159ee5,
            rgba(56, 189, 248, .08));

}

html[dir="rtl"] .microsoft-cloud-title-accent {

    margin-left: auto;

    margin-right: 0;

}


/* =========================================================
                    DESCRIPTION
========================================================= */

.microsoft-cloud-description {

    width: 100%;

    max-width: 680px;

    margin: 0;

    color: #a9bdca;

    font-size: var(--font-size-xl);

    line-height: 1.85;

    font-weight: 400;

}

.microsoft-cloud-description p {

    margin: 22px auto;

}

.microsoft-cloud-description p+p {

    margin-top: 18px;

}

html[dir="rtl"] .microsoft-cloud-description {

    text-align: right;

}


/* =========================================================
   MICROSOFT CLOUD PLATFORM
   TABLET 768px STYLE
   PART 2

   CARDS
   GRID 2x2
   ICON
   CONTENT
   RTL / LTR
========================================================= */


/* =========================================================
                    CARDS GRID
========================================================= */

.microsoft-cloud-cards {

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 76px;

    margin-top: 10px;

    align-items: stretch;

    margin-left: -25px;

}

html[dir="rtl"] .microsoft-cloud-cards {

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 76px;

    margin-top: 10px;

    align-items: stretch;

    margin-right: -25px;

}


/* =========================================================
                    CARD
========================================================= */

.microsoft-cloud-card {

    position: relative;

    width: 351px;

    min-height: 155px;

    display: flex;

    flex-direction: row;

    align-items: flex-start;

    gap: 16px;

    padding: 22px 20px;

    overflow: hidden;

    border-radius: 20px;

    background:

        linear-gradient(145deg,
            #ffffff 0%,
            #f8fbfe 100%);

    border:
        1px solid rgba(56, 189, 248, .16);

    box-shadow:

        0 18px 38px rgba(0, 0, 0, .25),

        inset 0 1px 0 rgba(255, 255, 255, .05);

    backdrop-filter: blur(12px);

    -webkit-backdrop-filter: blur(12px);

}


/* =========================================================
                    CARD GLOW LINE
========================================================= */

.microsoft-cloud-card::before {

    content: "";

    position: absolute;

    left: 0;

    top: 0;

    width: 3px;

    height: 100%;

    background:

        linear-gradient(to bottom,
            transparent,
            #159ee5,
            transparent);

    opacity: .8;

}


/* =========================================================
                    CARD ICON
========================================================= */

.microsoft-cloud-card-icon {

    flex: 0 0 auto;

    width: 58px;

    height: 58px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 15px;

    background:

        linear-gradient(145deg,
            #06243a,
            #0a3854);

    border:

        1px solid rgba(56, 189, 248, .35);

    color: #55c9f7;

    box-shadow:

        0 10px 25px rgba(0, 0, 0, .25),

        inset 0 0 15px rgba(56, 189, 248, .15);

    transition:

        transform .35s ease,

        box-shadow .35s ease;

}

.microsoft-cloud-card-icon svg {

    width: 30px;

    height: 30px;

}


/* =========================================================
                    CARD INFORMATION
========================================================= */

.microsoft-cloud-card-info {

    flex: 1;

    min-width: 0;

}

.microsoft-cloud-card-info h3 {

    margin: 0 0 9px;

    color: #152d47;

    font-size: 20px;

    line-height: 1.35;

    font-weight: 750;

}

.microsoft-cloud-card-info p {

    margin: 0;

    color: #9eb5c3;

    font-size: 17px;

    line-height: 1.7;

}


/* =========================================================
                    CARD HOVER
========================================================= */

.microsoft-cloud-card:hover {

    transform:

        translate3d(0, -6px, 0);

    border-color:

        rgba(56, 189, 248, .45);

    box-shadow:

        0 22px 45px rgba(0, 0, 0, .30),

        0 0 28px rgba(56, 189, 248, .12);

}

.microsoft-cloud-card:hover .microsoft-cloud-card-icon {

    transform:

        translate3d(0, -3px, 0) scale(1.05);

    box-shadow:

        0 14px 30px rgba(0, 0, 0, .28),

        0 0 18px rgba(56, 189, 248, .18),

        inset 0 0 15px rgba(56, 189, 248, .16);

}


/* =========================================================
                    RTL CARD
========================================================= */

html[dir="rtl"] .microsoft-cloud-card {

    direction: rtl;

    flex-direction: row-reverse;

    text-align: right;

}

html[dir="rtl"] .microsoft-cloud-card::before {

    left: auto;

    right: 0;

}

html[dir="rtl"] .microsoft-cloud-card-info {

    text-align: right;

}


/* =========================================================
                    LTR CARD
========================================================= */

html[dir="ltr"] .microsoft-cloud-card {

    direction: ltr;

    flex-direction: row;

    text-align: left;

}


/* =========================================================
                    RTL GRID STABILITY
========================================================= */

html[dir="rtl"] .microsoft-cloud-cards {

    direction: rtl;

}


/* =========================================================
                    CARD TOUCH SAFETY
========================================================= */

.microsoft-cloud-card,

.microsoft-cloud-card-icon {

    -webkit-tap-highlight-color: transparent;

}


/* =========================================================
   MICROSOFT CLOUD PLATFORM
   TABLET 768px STYLE
   PART 3

   IMAGE
   ANIMATION
   CTA
   DIVIDER
   GPU STABILITY
========================================================= */


/* =========================================================
                    IMAGE AREA
========================================================= */

.microsoft-cloud-visual {

    width: 100%;

    display: flex;

    justify-content: center;

    align-items: center;

}


/* =========================================================
                    IMAGE WRAPPER

        LARGER THAN MOBILE
        STABLE GPU LAYER
========================================================= */

.microsoft-cloud-image-wrapper {

    position: relative;

    width: 93%;

    max-width: 540px;

    aspect-ratio: 1 / 1;

    overflow: hidden;

    border-radius: 24px;

    background: #020b14;

    border:

        1px solid rgba(56, 189, 248, .22);

    box-shadow:

        0 25px 55px rgba(0, 0, 0, .38),

        0 0 35px rgba(21, 158, 229, .12);

    isolation: isolate;

    contain: paint;

    transform:

        translate3d(0, 0, 0);

    transform-style: preserve-3d;

    -webkit-transform-style: preserve-3d;

    backface-visibility: hidden;

    -webkit-backface-visibility: hidden;

}


/* =========================================================
                    IMAGE

        NEVER ANIMATE
        PREVENTS RTL / LTR SHAKE
========================================================= */

.microsoft-cloud-image {

    position: absolute;

    inset: 0;

    width: 100%;

    height: 100%;

    object-fit: cover;

    object-position: center;

    transform:

        translate3d(0, 0, 0) !important;

    animation: none !important;

    backface-visibility: hidden;

    -webkit-backface-visibility: hidden;

    will-change: auto;

}


/* =========================================================
                    IMAGE OVERLAY
========================================================= */

.microsoft-cloud-image-overlay {

    position: absolute;

    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:

        linear-gradient(180deg,
            rgba(1, 12, 22, .05),
            transparent 45%,
            rgba(1, 12, 22, .35));

}


/* =========================================================
                    LIGHT SWEEP

        ANIMATION ONLY ON OVERLAY
        NEVER TOUCH THE IMAGE
========================================================= */

.microsoft-cloud-image-wrapper::after {

    content: "";

    position: absolute;

    top: -20%;

    left: -20%;

    width: 25%;

    height: 140%;

    z-index: 3;

    pointer-events: none;

    background:

        linear-gradient(90deg,
            transparent,
            rgba(125, 211, 252, .12),
            rgba(255, 255, 255, .28),
            transparent);

    transform:

        translate3d(-180%, 0, 0) skewX(-18deg);

    filter: blur(5px);

    opacity: 0;

    animation:

        microsoftCloudTabletSweep 8s ease-in-out infinite;

    will-change:

        transform,
        opacity;

}


/* =========================================================
                    SWEEP ANIMATION
========================================================= */

@keyframes microsoftCloudTabletSweep {

    0% {

        transform:

            translate3d(-180%, 0, 0) skewX(-18deg);

        opacity: 0;

    }

    20% {

        opacity: .7;

    }

    55% {

        opacity: .25;

    }

    100% {

        transform:

            translate3d(620%, 0, 0) skewX(-18deg);

        opacity: 0;

    }

}


/* =========================================================
                    CLOUD ANIMATION SYSTEM
========================================================= */

.microsoft-cloud-animation {

    position: absolute;

    inset: 0;

    width: 100%;

    height: 100%;

    z-index: 4;

    pointer-events: none;

    transform:

        translate3d(0, 0, 0);

    backface-visibility: hidden;

    -webkit-backface-visibility: hidden;

}


/* =========================================================
                    CLOUD GLOW
========================================================= */

.microsoft-cloud-glow {

    position: absolute;

    width: 180px;

    height: 180px;

    left: 50%;

    top: 48%;

    transform:

        translate3d(-50%, -50%, 0);

    filter: blur(2px);

}


/* =========================================================
                    CLOUD CORE
========================================================= */

.microsoft-cloud-core {

    position: absolute;

    width: 78px;

    height: 52px;

    left: 50%;

    top: 48%;

    transform:

        translate3d(-50%, -50%, 0);

    border-radius:

        38px 38px 28px 28px;

}

.microsoft-cloud-core svg {

    width: 82px;

    height: 58px;

}


/* =========================================================
                    CLOUD CORE HIGHLIGHTS
========================================================= */

.microsoft-cloud-core::before {

    left: 11px;

    bottom: 16px;

    width: 30px;

    height: 30px;

}

.microsoft-cloud-core::after {

    right: 9px;

    bottom: 14px;

    width: 38px;

    height: 38px;

}


/* =========================================================
                    ORBIT SYSTEM
========================================================= */

.microsoft-cloud-orbit {

    position: absolute;

    width: 105px;

    height: 105px;

    left: 50%;

    top: 48%;

    transform:

        translate3d(-50%, -50%, 0);

}

.microsoft-cloud-orbit::before,

.microsoft-cloud-orbit::after {

    height: 25px;

}


/* =========================================================
                    ORBIT 1
========================================================= */

.microsoft-cloud-orbit-1 {

    width: 112px;

    height: 112px;

}


/* =========================================================
                    ORBIT 2
========================================================= */

.microsoft-cloud-orbit-2 {

    width: 155px;

    height: 155px;

}


/* =========================================================
                    ORBIT 3
========================================================= */

.microsoft-cloud-orbit-3 {

    width: 195px;

    height: 195px;

}


/* =========================================================
                    DATA PACKETS
========================================================= */

.microsoft-cloud-packet {

    width: 5px;

    height: 5px;

}


/* =========================================================
                    CLOUD SERVICE NODES
========================================================= */

.microsoft-cloud-node {

    min-width: 62px;

    height: 27px;

    padding: 0 7px;

    gap: 4px;

    font-size: 7px;

    letter-spacing: .065em;

    border-radius: 999px;

    backdrop-filter: blur(6px);

    -webkit-backdrop-filter: blur(6px);

    transform:

        translate3d(0, 0, 0);

    backface-visibility: hidden;

    -webkit-backface-visibility: hidden;

}


/* =========================================================
                    NODE ICON
========================================================= */

.microsoft-cloud-node-icon {

    width: 14px;

    height: 14px;

    flex: 0 0 14px;

}

.microsoft-cloud-node-icon svg {

    width: 13px;

    height: 13px;

}


/* =========================================================
                    NODE AZURE
========================================================= */

.microsoft-cloud-node-azure {

    left: 8%;

    top: 22%;

}


/* =========================================================
                    NODE 365
========================================================= */

.microsoft-cloud-node-365 {

    right: 8%;

    top: 21%;

}


/* =========================================================
                    NODE DYNAMICS
========================================================= */

.microsoft-cloud-node-dynamics {

    left: 7%;

    bottom: 22%;

}


/* =========================================================
                    NODE DATA
========================================================= */

.microsoft-cloud-node-data {

    right: 7%;

    bottom: 21%;

}


/* =========================================================
                    CENTRAL PULSE
========================================================= */

.microsoft-cloud-pulse {

    width: 13px;

    height: 13px;

}


/* =========================================================
                    DATA SCAN
========================================================= */

.microsoft-cloud-scan {

    width: 185px;

    height: 1px;

}


/* =========================================================
