        width: 26px;
        height: 26px;
    }


    /* =========================================================
ORB POSITIONS
MOBILE
========================================================= */

    /* CODING */

    .orb-1 {
        left: calc(50% - 30px);
        top: calc(50% - 100px);

        animation:
            softwareOrbTop 7s ease-in-out infinite;
    }


    /* DEVELOPMENT */

    .orb-2 {
        left: calc(50% - 105px);
        top: calc(50% - 58px);

        animation:
            softwareOrbTopLeft 7s ease-in-out infinite 0.55s;
    }


    /* CLOUD */

    .orb-3 {
        left: calc(50% + 48px);
        top: calc(50% - 62px);

        animation:
            softwareOrbTopRight 7s ease-in-out infinite 1.10s;
    }


    /* SECURITY */

    .orb-4 {
        left: calc(50% - 125px);
        top: calc(50% - 5px);

        animation:
            softwareOrbLeft 7s ease-in-out infinite 1.65s;
    }


    /* MOBILE */

    .orb-5 {
        left: calc(50% - 92px);
        top: calc(50% + 48px);

        animation:
            softwareOrbBottomLeft 7s ease-in-out infinite 2.20s;
    }


    /* DATABASE */

    .orb-6 {
        left: calc(50% + 58px);
        top: calc(50% + 8px);

        animation:
            softwareOrbRight 7s ease-in-out infinite 2.75s;
    }


    /* =========================================================
HOLOGRAM CONNECTION LINES
MOBILE
========================================================= */

    .hologram-line {
        left: 50%;
        top: 50%;
    }


    /* TOP */

    .line-1 {
        width: 105px;

        transform:
            rotate(-90deg) scaleX(0);
    }


    /* TOP LEFT */

    .line-2 {
        width: 110px;

        transform:
            rotate(-143deg) scaleX(0);
    }


    /* TOP RIGHT */

    .line-3 {
        width: 100px;

        transform:
            rotate(-43deg) scaleX(0);
    }


    /* LEFT */

    .line-4 {
        width: 125px;

        transform:
            rotate(178deg) scaleX(0);
    }


    /* BOTTOM LEFT */

    .line-5 {
        width: 105px;

        transform:
            rotate(145deg) scaleX(0);
    }


    /* RIGHT */

    .line-6 {
        width: 105px;

        transform:
            rotate(-5deg) scaleX(0);
    }


    /* =========================================================
ORIGIN
========================================================= */

    .software-origin {
        left: 50%;
        top: 50%;

        width: 18px;
        height: 18px;

