    /* =========================================================
IMAGE WRAPPER
========================================================= */

    .software-development-image-wrapper {
        position: relative;

        width: 95%;
        height: 260px;

        margin: auto;

        overflow: hidden;

        border-radius: 16px;

        background: #020b14;

        border:
            1px solid rgba(56, 189, 248, 0.20);

        box-shadow:
            0 18px 40px rgba(0, 0, 0, 0.35),
            0 0 25px rgba(21, 158, 229, 0.08);

        isolation: isolate;

        /* IMPORTANT — IMAGE STABILITY */
        transform: translate3d(0, 0, 0);
        transform-style: preserve-3d;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        contain: paint;
    }


    /* =========================================================
IMAGE
NO MOVEMENT
NO SCALE
========================================================= */

    .software-development-image {
        position: absolute;

        inset: 0;

        width: 100%;
        height: 100%;

        display: block;

        object-fit: cover;
        object-position: center;

        /* IMPORTANT */
        transform: translate3d(0, 0, 0) !important;

        transform-style: preserve-3d;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        /* Prevent image shaking */
        animation: none !important;
        transition: none !important;

        will-change: auto;
    }


    /* =========================================================
REMOVE IMAGE HOVER MOVEMENT
========================================================= */

    .software-development-image-wrapper:hover .software-development-image {
        transform: translate3d(0, 0, 0) !important;

        filter:
            brightness(1.05) saturate(1.05);
    }


    /* =========================================================
IMAGE OVERLAY
========================================================= */

    .software-development-image-overlay {
        position: absolute;

        inset: 0;

        z-index: 2;

        pointer-events: none;

        background:
            linear-gradient(180deg,
                rgba(1, 12, 22, 0.08),
                transparent 45%,
                rgba(1, 12, 22, 0.35));

        transform: translate3d(0, 0, 0);

        transform-style: preserve-3d;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
HOLOGRAM
MOBILE
========================================================= */

    .software-hologram {
        position: absolute;

        left: 72%;

        top: 37%;

        width: 260px;
        height: 220px;

        transform:
            translate3d(-50%, -50%, 0) scale(0.55);

        transform-origin: center center;

        z-index: 6;

        pointer-events: none;

        overflow: visible;

        transform-style: preserve-3d;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        will-change: transform;
    }


    /* =========================================================
SOFTWARE ORBS
MOBILE SIZE
========================================================= */

    .software-orb {
        width: 60px;
        height: 60px;
    }


    /* =========================================================
ORB ICON
========================================================= */

    .orb-icon {
        width: 34px;
        height: 34px;
    }


    .orb-icon svg {
        width: 26px;
        height: 26px;
    }


    /* =========================================================
ORB POSITIONS
MOBILE
========================================================= */

    /* CODING */

    .orb-1 {
        left: calc(50% - 30px);
        top: calc(50% - 100px);

        animation:
            softwareOrbTop 7s ease-in-out infinite;
    }


    /* DEVELOPMENT */

    .orb-2 {
        left: calc(50% - 105px);
        top: calc(50% - 58px);

        animation:
            softwareOrbTopLeft 7s ease-in-out infinite 0.55s;
    }


    /* CLOUD */

    .orb-3 {
        left: calc(50% + 48px);
        top: calc(50% - 62px);

        animation:
            softwareOrbTopRight 7s ease-in-out infinite 1.10s;
    }


    /* SECURITY */

    .orb-4 {
        left: calc(50% - 125px);
        top: calc(50% - 5px);

        animation:
            softwareOrbLeft 7s ease-in-out infinite 1.65s;
    }


    /* MOBILE */

    .orb-5 {
        left: calc(50% - 92px);
        top: calc(50% + 48px);

        animation:
            softwareOrbBottomLeft 7s ease-in-out infinite 2.20s;
    }


    /* DATABASE */

    .orb-6 {
        left: calc(50% + 58px);
        top: calc(50% + 8px);

        animation:
            softwareOrbRight 7s ease-in-out infinite 2.75s;
    }


    /* =========================================================
HOLOGRAM CONNECTION LINES
MOBILE
========================================================= */

    .hologram-line {
        left: 50%;
        top: 50%;
    }


    /* TOP */

    .line-1 {
        width: 105px;

        transform:
            rotate(-90deg) scaleX(0);
    }


    /* TOP LEFT */

    .line-2 {
        width: 110px;

        transform:
            rotate(-143deg) scaleX(0);
    }


    /* TOP RIGHT */

    .line-3 {
        width: 100px;

        transform:
            rotate(-43deg) scaleX(0);
    }


    /* LEFT */

    .line-4 {
        width: 125px;

        transform:
            rotate(178deg) scaleX(0);
    }


    /* BOTTOM LEFT */

    .line-5 {
        width: 105px;

        transform:
            rotate(145deg) scaleX(0);
    }


    /* RIGHT */

    .line-6 {
        width: 105px;

        transform:
            rotate(-5deg) scaleX(0);
    }


    /* =========================================================
ORIGIN
========================================================= */

    .software-origin {
        left: 50%;
        top: 50%;

        width: 18px;
        height: 18px;

        transform:
            translate3d(-50%, -50%, 0);
    }


    /* =========================================================
ORIGIN CORE
========================================================= */

    .origin-core {
        width: 7px;
        height: 7px;

        transform:
            translate3d(-50%, -50%, 0);
    }


    /* =========================================================
ORIGIN FLASH
========================================================= */

    .origin-flash {
        width: 4px;
        height: 4px;

        transform:
            translate3d(-50%, -50%, 0);
    }


    /* =========================================================
ORIGIN RINGS
========================================================= */

    .origin-ring-1 {
        width: 22px;
        height: 22px;
    }


    .origin-ring-2 {
        width: 42px;
        height: 42px;
    }


    .origin-ring-3 {
        width: 68px;
        height: 68px;
    }


    /* =========================================================
MICRO PARTICLES
========================================================= */

    .hologram-particle {
        width: 2px;
        height: 2px;
    }


    /* =========================================================
LIGHT SWEEP
ANIMATION ON OVERLAY LAYER
NOT ON IMAGE
========================================================= */

    .software-development-image-wrapper::after {
        content: "";

        position: absolute;

        top: -20%;
        left: -25%;

        width: 25%;
        height: 140%;

        z-index: 3;

        pointer-events: none;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(125, 211, 252, 0.15),
                rgba(255, 255, 255, 0.25),
                transparent);

        transform:
            translate3d(-120%, 0, 0) skewX(-18deg);

        filter: blur(5px);

        animation:
            softwareMobileLightSweep 8s ease-in-out infinite;

        will-change: transform, opacity;
    }


    /* =========================================================
MOBILE LIGHT SWEEP
========================================================= */

    @keyframes softwareMobileLightSweep {

        0% {
            transform:
                translate3d(-120%, 0, 0) skewX(-18deg);

            opacity: 0;
        }

        20% {
            opacity: 0.7;
        }

        55% {
            opacity: 0.25;
        }

        100% {
            transform:
                translate3d(520%, 0, 0) skewX(-18deg);

            opacity: 0;
        }
    }


