    }


    /* =========================================================
SOFTWARE HOLOGRAM
FORCE LTR ANIMATION SYSTEM
FIX RTL SHAKE
========================================================= */

    .software-hologram {
        direction: ltr !important;
        unicode-bidi: isolate;

        writing-mode: horizontal-tb;

        left: 65%;

        right: auto;

        transform:
            translate3d(-50%, -50%, 0) scale(0.55);

        transform-origin: center center;

        isolation: isolate;

        contain: layout paint style;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        transform-style: preserve-3d;

        will-change: transform;
    }


    /* =========================================================
RTL — HOLOGRAM MUST STAY LTR
========================================================= */

    html[dir="rtl"] .software-hologram {

        direction: ltr !important;

        unicode-bidi: isolate;

        writing-mode: horizontal-tb;

        left: 65%;

        right: auto !important;

        transform:
            translate3d(-50%, -50%, 0) scale(0.55) !important;

        transform-origin:
            center center !important;

        isolation: isolate;

        contain: layout paint style;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        transform-style: preserve-3d;

        will-change: transform;
    }


    /* =========================================================
RTL — ALL HOLOGRAM CHILDREN
KEEP THE ANIMATION COORDINATE SYSTEM LTR
========================================================= */

    html[dir="rtl"] .software-hologram .software-orb,
    html[dir="rtl"] .software-hologram .hologram-line,
    html[dir="rtl"] .software-hologram .hologram-particle,
    html[dir="rtl"] .software-hologram .software-origin {

        direction: ltr !important;

        writing-mode: horizontal-tb;

        unicode-bidi: isolate;
    }


    /* =========================================================
ORBS — DO NOT INHERIT RTL BEHAVIOR
========================================================= */

    html[dir="rtl"] .software-hologram .software-orb {

        direction: ltr !important;

        unicode-bidi: isolate;

        transform-style: preserve-3d;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
    }


    /* =========================================================
LINES — KEEP ORIGINAL LTR GEOMETRY
========================================================= */

    html[dir="rtl"] .software-hologram .hologram-line {

        direction: ltr !important;

        unicode-bidi: isolate;

        transform-origin:
            left center;
    }


    /* =========================================================
ORIGIN — FIXED CENTER
========================================================= */

    html[dir="rtl"] .software-hologram .software-origin {

        left: 50% !important;
        right: auto !important;

        top: 50% !important;

        direction: ltr !important;

        unicode-bidi: isolate;
    }


    /* =========================================================
IMAGE WRAPPER — ABSOLUTELY STABLE
========================================================= */

    html[dir="rtl"] .software-development-image-wrapper {

        direction: ltr !important;

        unicode-bidi: isolate;

        transform:
            translate3d(0, 0, 0) !important;

        transform-origin:
            center center !important;

        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;

        transform-style: preserve-3d;

        contain: layout paint style;
    }


    /* =========================================================
IMAGE — NEVER MOVE IN RTL
========================================================= */

