        transition-delay: 0.95s;
    }


    /* =====================================================
REVEAL ORDER — DIVIDER
===================================================== */

    .microsoft-cloud-section.is-visible .microsoft-cloud-divider {
        transition-delay: 1.08s;
    }


    /* =====================================================
SUPPORT OTHER JS CLASSES
===================================================== */

    .microsoft-cloud-section.visible .microsoft-cloud-content,

    .microsoft-cloud-section.microsoft-cloud-visible .microsoft-cloud-content {
        transition-delay: 0s;
    }

