/* =====================================================
            IMAGE WRAPPER
===================================================== */

.technology-image-wrapper {

    position: relative;

    width: 100%;
    height: 315px;

    overflow: hidden;

    border-radius: 18px;

    background: #020b14;

    border:
        1px solid rgba(7, 45, 70, .35);

    box-shadow:
        0 18px 38px rgba(8, 38, 60, .14);

    /*
     * Creates an isolated compositor layer.
     * This helps prevent RTL transform repaint jitter.
     */
    isolation: isolate;

}


/* =====================================================
            IMAGE
===================================================== */

.technology-image {

    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    object-fit: cover;
    object-position: center center;

    /*
     * Keep the actual image completely static.
     * Only the hologram should animate.
     */
    transform: translate3d(0, 0, 0);

    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;

}


/* =====================================================
            IMAGE OVERLAY
===================================================== */

.technology-image-overlay {

    position: absolute;

    inset: 0;

    z-index: 2;

    pointer-events: none;

    background:

        linear-gradient(180deg,
            rgba(2, 15, 28, .05),
            transparent 45%,
            rgba(1, 10, 20, .22));

}


/* =====================================================
        HOLOGRAM - STABLE BASE
===================================================== */

.technology-hologram {

    position: absolute;

    left: 38%;
    top: 46%;

    width: 240px;
    height: 240px;

    /*
     * IMPORTANT:
     * The base transform remains fixed.
     * This prevents RTL layout recalculation from
     * fighting the hologram animation.
     */
    transform:
        translate3d(-50%, -50%, 0);

    transform-origin: center center;

    z-index: 5;

    perspective: 700px;

    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;

    will-change: transform;

    contain: layout paint;

}


/* =====================================================
            CORE
===================================================== */

.holo-core {

    left: 50%;
    top: 72%;

    width: 52px;
    height: 52px;

}


.holo-core-center {

    width: 8px;
    height: 8px;

}


/* =====================================================
            CONTACT GLOW
===================================================== */

.technology-hologram::before {

    left: 50%;
    top: 72%;

    width: 90px;
    height: 50px;

    filter: blur(7px);

}


/* =====================================================
            HOLO ELEMENT
===================================================== */

.holo-element {

    width: 60px;
    height: 34px;

    padding: 0 6px;

    border-radius: 6px;

    transform-origin: center center;

    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;

    transform-style: preserve-3d;

}


/* =====================================================
            HOLO ICON
===================================================== */

.holo-icon {

    width: 18px;
