    box-shadow:
        0 18px 38px rgba(8, 38, 60, .14);

    /*
     * Creates an isolated compositor layer.
     * This helps prevent RTL transform repaint jitter.
     */
    isolation: isolate;

}


/* =====================================================
            IMAGE
===================================================== */

.technology-image {

    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    object-fit: cover;
    object-position: center center;

    /*
     * Keep the actual image completely static.
     * Only the hologram should animate.
     */
    transform: translate3d(0, 0, 0);

    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;

}


/* =====================================================
