}


/* =====================================================
        HOLOGRAM - STABLE BASE
===================================================== */

.technology-hologram {

    position: absolute;

    left: 38%;
    top: 46%;

    width: 240px;
    height: 240px;

    /*
     * IMPORTANT:
     * The base transform remains fixed.
     * This prevents RTL layout recalculation from
     * fighting the hologram animation.
     */
    transform:
        translate3d(-50%, -50%, 0);

    transform-origin: center center;

    z-index: 5;

    perspective: 700px;

    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;

    will-change: transform;

    contain: layout paint;

}


