     /* =========================================================
   ORIGIN
========================================================= */

     .software-origin {
         left: 50%;
         top: 50%;

         width: 18px;
         height: 18px;

         transform:
             translate3d(-50%, -50%, 0);
     }


     /* =========================================================
   ORIGIN CORE
========================================================= */

     .origin-core {
         width: 7px;
         height: 7px;

         transform:
             translate3d(-50%, -50%, 0);
