     }





     /* =========================================================
   CARD INFO
========================================================= */

     .security-solutions-card-info {

         flex: 1;

         min-width: 0;
     }



     .security-solutions-card-info h3 {

         margin:

             0 0 6px;


         font-size: 15px;

         line-height: 1.35;

         font-weight: 700;
     }



     .security-solutions-card-info p {

         margin: 0;


         font-size: 12px;

         line-height: 1.65;
     }





     /* =========================================================
   CARD HOVER
========================================================= */


     .security-solutions-card:hover {

         transform:

             translateY(-3px);


         border-color:

             rgba(56, 189, 248, .45);
     }





     /* =========================================================
   RTL CARD
========================================================= */


     html[dir="rtl"] .security-solutions-card {

         direction: rtl;
     }


     html[dir="rtl"] .security-solutions-card-info {

         text-align: right;
     }





     /* =========================================================
   CTA
========================================================= */


     .security-solutions-cta-wrapper {

         width: 100%;


         display: flex;

         justify-content: flex-start;


         margin-top: 0;
     }




     .security-solutions-cta {

         width: 100%;


         min-height: 44px;


         display: flex;

         align-items: center;

         justify-content: center;


         padding:

             0 20px;


         font-size: 13px;


         border-radius: 10px;


         -webkit-tap-highlight-color: transparent;
     }





     .security-solutions-cta-text {

         position: relative;

         z-index: 2;
     }





     /* =========================================================
   DIVIDER
========================================================= */


     .security-solutions-divider {

         position: relative;


         width: 90%;


         height: 2px;


         margin:

             45px auto 0;


         background:

             linear-gradient(90deg,
                 transparent,
                 rgba(21, 158, 229, .55),
                 transparent);
     }





     .security-solutions-divider span {


         position: absolute;


         top: 50%;

         left: 15%;


         width: 70px;

         height: 6px;


         transform:

             translate3d(-50%, -50%, 0);


         border-radius: 999px;


         background: #38bdf8;


         filter: blur(1px);


         box-shadow:

             0 0 15px rgba(56, 189, 248, .7);


         animation:

             securityDividerMobile 4s ease-in-out infinite;
     }




     /* =========================================================
   DIVIDER ANIMATION
========================================================= */


     @keyframes securityDividerMobile {


         0% {

             left: 10%;

             opacity: 0;
         }



         20% {

             opacity: 1;
         }



         100% {

             left: 90%;

             opacity: 0;
         }

     }


     /* =========================================================
   SOLUTIONS SECTION - MOBILE 320px OPTIMIZATION
   WITHOUT MEDIA QUERY
========================================================= */


     #solutions {
         padding: 60px 0;
     }


     #solutions .solutions-container {
         width: calc(100% - 32px);
         margin: 0 auto;
     }


     /* =========================================================
   HEADER
========================================================= */


     #solutions .solutions-header {

         display: block;

         width: 100%;

         margin: 0 0 35px;

         padding-left: 18px;

     }


     #solutions .solutions-header-content {

         width: 100%;

     }


     /* vertical line */

     #solutions .solutions-header-border {

         width: 4px;

     }



     /* =========================================================
   EYEBROW
========================================================= */


     #solutions .solutions-eyebrow {

         margin-bottom: 10px;

         font-size: 11px;

         letter-spacing: 1.8px;

     }



     /* =========================================================
   TITLE
========================================================= */


     #solutions .solutions-title {

         font-size: var(--font-size-2xl);

         line-height: 1.25;

         letter-spacing: -0.3px;

         margin-bottom: 16px;

         max-width: 100%;

         text-align: left;

         word-break: normal;

     }



     /* RTL title */

     html[dir="rtl"] #solutions .solutions-title {

         text-align: right;

     }



     /* =========================================================
   DESCRIPTION
========================================================= */


     #solutions .solutions-description {

         width: 100%;

         max-width: 100%;

     }


     #solutions .solutions-description p {

         font-size: 13px;

         line-height: 1.85;

         width: 100%;

         text-align: left;

     }



     html[dir="rtl"] #solutions .solutions-description p {

         text-align: right;

     }



     /* =========================================================
   GRID
========================================================= */


     #solutions .solutions-grid {

         display: flex;

         flex-direction: column;

         gap: 16px;

         margin-top: 10px;

     }



     /* =========================================================
   CARD
========================================================= */


     #solutions .solution-card {

         width: 100%;

         min-height: auto;

         padding: 24px 20px;

         border-radius: 18px;

     }



     #solutions .solution-card-inner {

         min-height: 0;

     }



     /* =========================================================
   ICON
========================================================= */


     #solutions .solution-card-icon {

         width: 52px;

         height: 52px;

         margin-bottom: 18px;

         border-radius: 14px;

     }


     #solutions .solution-card-icon svg {

         width: 26px;

         height: 26px;

     }



     /* =========================================================
   CARD CONTENT
========================================================= */


     #solutions .solution-card-content {

         width: 100%;

     }



     /* title */

     #solutions .solution-card-title {

         font-size: 18px;

         line-height: 1.4;

         margin-bottom: 10px;

     }



     html[dir="rtl"] #solutions .solution-card-title {

         text-align: right;

     }



     /* text */

     #solutions .solution-card-text {

         font-size: 13px;

         line-height: 1.75;

         margin-bottom: 12px;

     }


     html[dir="rtl"] #solutions .solution-card-text {

         text-align: right;

     }



     /* =========================================================
   LINK
========================================================= */


     #solutions .solution-card-link {

         margin-top: 18px;

         font-size: 12px;

     }


     html[dir="rtl"] #solutions .solution-card-link {

         align-self: flex-start;

     }



     /* =========================================================
   HOVER MOBILE FIX
========================================================= */


     #solutions .solution-card:hover {

         transform: translateY(-5px) scale(1.01);

     }



     /* =========================================================
   DIVIDER
========================================================= */


     #solutions .solutions-divider {

         margin-top: 40px;

     }




     /* =========================================================
   RTL MOBILE
========================================================= */


     html[dir="rtl"] #solutions .solutions-header {

         padding-left: 0;

         padding-right: 18px;

     }


     html[dir="rtl"] #solutions .solutions-header-border {

         right: 0;

         left: auto;

     }


     html[dir="rtl"] #solutions .solution-card {

         text-align: right;

     }



     html[dir="rtl"] #solutions .solution-card-link {

         flex-direction: row-reverse;

     }






}









